# JPEG gia' pronte passano come sempre e le altre si saltano
# (pip install pillow pillow-heif).
try:
    from PIL import Image as ImmaginePillow
    from PIL import ImageOps
except ImportError:
    ImmaginePillow = None
    ImageOps = None
try:
    import pillow_heif
    pillow_heif.register_heif_opener()
except ImportError:
    pillow_heif = None
