def _dati_distintivi(con, tg_id: int) -> dict | None:
    """I numeri veri su cui si giudicano i criteri, ricalcolati sempre
    dalle tabelle (mai da contatori)."""
    u = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                    (tg_id,)).fetchone()
    if not u:
        return None
    q = lambda sql, *p: con.execute(sql, p).fetchone()[0]
    fb = con.execute("SELECT COUNT(*) AS n, AVG(voto) AS media "
                     "FROM feedback WHERE per_tg_id=?", (tg_id,)).fetchone()
    return dict(
        tg_id=tg_id,
        npub_verificata=u["npub_verificata"],
        npub_accesso=u["npub_accesso"],
        # posizione d'iscrizione: registrato=0 (chi c'era prima della
        # colonna) = i piu' vecchi di tutti; i nuovi arrivano sempre
        # dopo, quindi la posizione di chi c'e' non peggiora mai
        posizione=q("SELECT COUNT(*) FROM utenti WHERE registrato<? "
                    "OR (registrato=? AND tg_id<=?)",
                    u["registrato"], u["registrato"], tg_id),
        vendite=q("SELECT COUNT(*) FROM ordini WHERE venditore_id=? "
                  "AND stato='released'", tg_id),
        acquisti=q("SELECT COUNT(*) FROM ordini WHERE compratore_id=? "
                   "AND stato='released'", tg_id),
        # disputa persa: il venditore se fini' in rimborso, il
        # compratore se i sats andarono comunque al venditore
        dispute_perse=q("SELECT COUNT(*) FROM ordini WHERE disputata=1 "
                        "AND ((venditore_id=? AND stato='refunded') OR "
                        "(compratore_id=? AND stato='released'))",
                        tg_id, tg_id),
        # niente 'revisione': un annuncio mai approvato non apre bottega
        annunci=q("SELECT COUNT(*) FROM annunci WHERE venditore_id=? "
                  "AND stato NOT IN ('rimosso','revisione')", tg_id),
        fb_ricevuti=fb["n"], fb_media=fb["media"] or 0,
        fb_lasciati=q("SELECT COUNT(*) FROM feedback WHERE da_tg_id=?",
                      tg_id),
        # pagato_il non esiste, ma un ordine mai pagato muore in 30
        # minuti (pulisci_ordini_fantasma): creato+30min e' il tetto
        # fisico del pagamento. Margine a favore del venditore.
        lampo=q("SELECT COUNT(*) FROM ordini WHERE venditore_id=? "
                "AND stato='released' AND spedito_il>0 "
                "AND spedito_il-creato <= ?", tg_id, 86400 + 1800))


def controlla_distintivi(con, tg_id: int) -> list[str]:
    """Il giudice unico: valuta TUTTI i criteri e assegna cio' che
    manca (INSERT OR IGNORE: idempotente, mai doppioni). Niente
    commit, e' del chiamante. Ritorna gli id appena guadagnati,
    per le notifiche 🏅 dei ganci dal vivo."""
    d = _dati_distintivi(con, tg_id)
    if not d:
        return []
    nuovi = []
    for dd in DISTINTIVI:
        if dd["criterio"](d):
            r = con.execute(
                "INSERT OR IGNORE INTO badge_utente"
                "(tg_id, badge_id, ottenuto_il) VALUES(?,?,?)",
                (tg_id, dd["id"], int(time.time())))
            if r.rowcount:
                nuovi.append(dd["id"])
    return nuovi


# ---------------------- LE COORTI (ago 2026) -------------------------
# «Pioniere» esisteva gia' come distintivo (posizione <= 100): qui la
# stessa idea diventa una scala, perche' chi arriva dopo i primi cento
# non deve trovare la porta chiusa — ha un'altra porta, che dice
# un'altra cosa vera.
# Chi entra oltre l'ultima soglia NON ha coorte, ed e' giusto: la
# coorte e' un FATTO, non un premio da distribuire a tutti. Se ce
# l'hanno tutti non dice piu' niente, e chi e' arrivato per primo se
# ne accorge.
# «Fondatore» NON e' una coorte (ago 2026, decisione di Andrea): e' di
# chi il Barattolo l'ha fatto, e nessuno puo' piu' ottenerlo. La voce
# dei 500 si chiamava cosi' e ha cambiato nome — l'id con lei, perche'
# un id 'fondatore' che mostra «Dei primi giorni» sarebbe una trappola
# per chi legge fra sei mesi; il pregresso lo raddrizza una riga di
# migrazione in init_db.
COORTI = [(100, "pioniere", "🌱", "Pioniere",
           "Tra i primi 100 iscritti del Barattolo"),
          (500, "primi_giorni", "🧱", "Dei primi giorni",
           "Tra i primi 500 iscritti del Barattolo"),
          (2000, "veterano", "🏺", "Veterano",
           "Tra i primi 2.000 iscritti del Barattolo"),
          (10000, "bottegaio", "🏪", "Bottegaio",
           "Tra i primi 10.000 iscritti del Barattolo")]

# I FONDATORI, per tg_id, dal config del VPS (vuoto nel codice: gli id
# delle persone non stanno in repo). Non e' un traguardo che si
# raggiunge — e' un fatto, come la coorte, ma di due persone sole.
try:
    from config import FONDATORI
except ImportError:
    FONDATORI = ()


def coorte_da_posizione(posizione: int) -> str:
    """La coorte di chi si e' iscritto in quella posizione ('' = e'
    arrivato oltre l'ultima soglia)."""
    for soglia, cid, _e, _n, _d in COORTI:
        if posizione <= soglia:
            return cid
    return ""


def assegna_coorte(con, tg_id: int) -> str:
    """Scrive utenti.coorte UNA volta sola e poi la CONGELA. La
    posizione in una fila non cambia mai piu': ricalcolarla a ogni
    giro e' lavoro buttato, e a diecimila utenti sarebbe una scansione
    per ogni chiamata. Niente commit: e' del chiamante."""
    u = con.execute("SELECT registrato, coorte FROM utenti WHERE tg_id=?",
                    (tg_id,)).fetchone()
    if not u or u["coorte"]:
        return u["coorte"] if u else ""
    # Stessa posizione del distintivo Pioniere: registrato=0 (chi c'era
    # prima della colonna) vale come i piu' vecchi di tutti
    pos = con.execute(
        "SELECT COUNT(*) FROM utenti WHERE registrato<? "
        "OR (registrato=? AND tg_id<=?)",
        (u["registrato"], u["registrato"], tg_id)).fetchone()[0]
    c = coorte_da_posizione(pos)
    if c:
        con.execute("UPDATE utenti SET coorte=? WHERE tg_id=?", (c, tg_id))
    return c


# ------------------------- GLI XP (ago 2026) -------------------------
# La moneta dell'impegno. Il tariffario dice una cosa sola, ed e' la
# REGOLA DA NON ROVESCIARE: nessuna azione ripetibile a costo zero
# deve valere quanto una che muove sats. Pubblicare, salvare nel
# barattolo, fare un'offerta — tutte a tetto giornaliero o a zero.
# Altrimenti la scala premia chi fa rumore invece di chi commercia, e
# a quel punto smette di descrivere il mercatino.
FISSO_XP_ORDINE = 10        # ogni affare concluso conta, anche da 3 €
XP_PER_EURO = 1             # un euro, un punto
# NESSUN TETTO, ed e' una decisione esplicita di Andrea: un acquisto
# da 4.000 € su un mercatino appena nato non e' un'anomalia da limare,
# e' qualcuno che ha affidato quella cifra al deposito di garanzia.
# Frequenza e importo valgono ENTRAMBI — sul volume ci guadagniamo le
# fee a ogni transazione, sull'importo grosso ci guadagniamo la
# fiducia — e il fisso+variabile li premia tutti e due senza doverli
# pesare l'uno contro l'altro.
# Il venditore prende piu' del compratore perche' VENDERE E' IL LATO
# SCARSO: un mercatino muore per mancanza di merce, mai di curiosi.
XP_RUOLO = {"venditore": 1.0, "compratore": 0.6}
AZIONI_XP = {
    "visita": 1,            # presenza, non merito
    "annuncio": 5,          # UNO al giorno, o si pubblica spazzatura
    "feedback": 10,         # uno per ordine, come il feedback stesso
    "incassi": 20,          # Lightning address impostato, una volta sola
    "identita": 15,         # npub verificata, Telegram collegato
    "distintivo": 25,
}


def oggi_locale() -> str:
    """Il giorno di oggi, ora del server ('2026-08-05'). Locale e non
    UTC: chi apre l'app alle 23 di sera e alle 8 del mattino dopo deve
    vedere due giorni, non uno — e' l'ora che ha lui sull'orologio."""
    return time.strftime("%Y-%m-%d", time.localtime())


def _ricalcola_xp(con, tg_id: int):
    """Rifa' utenti.xp dal registro. Nessun commit: e' del chiamante.
    E' cio' che rende la fusione un caso NON speciale — si migrano le
    righe e si ricalcola, come per rating e feedback."""
    n = con.execute("SELECT COALESCE(SUM(punti),0) AS s FROM xp_eventi "
                    "WHERE tg_id=?", (tg_id,)).fetchone()["s"]
    con.execute("UPDATE utenti SET xp=? WHERE tg_id=?", (n, tg_id))
    return n


def assegna_xp(con, tg_id: int, tipo: str, punti: int,
               riferimento: str = "") -> int:
    """Scrive una riga di registro e aggiorna la somma. Ritorna i punti
    DAVVERO assegnati: 0 se erano gia' stati dati (la UNIQUE fa da
    giudice, qui non si controlla niente a mano). Niente commit: la
    transazione e' del chiamante, come in controlla_distintivi."""
    if not tg_id or punti <= 0:
        return 0
    r = con.execute(
        "INSERT OR IGNORE INTO xp_eventi"
        "(tg_id, tipo, punti, riferimento, creato) VALUES(?,?,?,?,?)",
        (tg_id, tipo, int(punti), riferimento, int(time.time())))
    if not r.rowcount:
        return 0            # gia' pagato: e' il retry, ed e' innocuo
    con.execute("UPDATE utenti SET xp=xp+? WHERE tg_id=?",
                (int(punti), tg_id))
    return int(punti)


async def premia_xp(tg_id: int, tipo: str, punti: int,
                    riferimento: str = ""):
    """Il gancio standard, gemello di premia_distintivi: connessione
    propria, commit, fail-open totale. Un errore negli XP non deve MAI
    poter toccare cio' che stava premiando — men che meno uno sblocco
    di sats. Nessuna notifica: gli XP non si annunciano uno a uno, si
    guardano nel Profilo."""
    try:
        con = db()
        dati = assegna_xp(con, tg_id, tipo, punti, riferimento)
        con.commit()
        con.close()
        return dati
    except Exception as e:
        print(f"⚠️ XP saltati per {tg_id} ({tipo}/{riferimento}): {e}")
        return 0


def xp_ordine(prezzo_sats: int, cambio_eur: float, ruolo: str) -> int:
    """Gli XP di un affare concluso. La base e' il TOTALE in cassaforte
    — articolo + spedizione + protezione — perche' chi paga 300 € di
    spedizione ha speso 300 €, e si premia cio' che e' stato speso.
    Cambio sconosciuto (ordine storico, CoinGecko muto) = resta il solo
    fisso: meglio 10 punti invece di 310 che un numero inventato, la
    stessa regola per cui un avviso in EUR non scatta senza cambio."""
    euro = (prezzo_sats / 100_000_000 * cambio_eur) if cambio_eur > 0 else 0.0
    return int((FISSO_XP_ORDINE + euro * XP_PER_EURO)
               * XP_RUOLO.get(ruolo, 1.0))


# ---------------------- I LIVELLI (ago 2026) -------------------------
# DUE CHIAVI, e non e' un vezzo: e' la conseguenza diretta del «nessun
# tetto» sugli XP. Senza tetto una vendita da 4.000 € vale piu' di
# trecento piccole, quindi un livello sui SOLI XP direbbe «ha venduto
# una cosa cara», non «commercia». Le soglie guardano gli XP E il
# numero di affari conclusi, cosi' il grado dice tutte e due le cose —
# la stessa idea per cui frequenza e importo valgono entrambi.
# Derivati, mai in colonna: si ricalcolano da xp e dai contatori, come
# i distintivi si ricalcolano dai dati veri.
LIVELLI = [(0, 0, "nuovo", "Nuovo arrivato"),
           (150, 1, "avviato", "Bottega avviata"),
           (600, 5, "pratico", "Mercante pratico"),
           (2500, 15, "esperto", "Mercante esperto"),
           (9000, 40, "maestro", "Maestro del banco")]


def livello_utente(xp: int, affari: int) -> dict:
    """Il grado di chi ha quegli XP e quegli affari. Il piu' alto che
    soddisfa ENTRAMBE le soglie: chi ha 5.000 XP da una vendita sola
    non passa davanti a chi ne ha venti."""
    vinto = LIVELLI[0]
    for l in LIVELLI:
        if xp >= l[0] and affari >= l[1]:
            vinto = l
    i = LIVELLI.index(vinto)
    pross = LIVELLI[i + 1] if i + 1 < len(LIVELLI) else None
    return {"id": vinto[2], "nome": vinto[3], "numero": i + 1,
            "xp_prossimo": pross[0] if pross else 0,
            "affari_prossimo": pross[1] if pross else 0,
            "nome_prossimo": pross[3] if pross else ""}


# ---------------------- I TITOLI (ago 2026) --------------------------
# Il distintivo dice «ho fatto», il titolo dice «chi sono» — ed e' la
# parte che si SCEGLIE. Il requisito e' sempre un fatto gia' calcolato
# altrove (una coorte, un distintivo guadagnato, un livello raggiunto):
# qui non si giudica niente di nuovo, si compone.
# IL CATALOGO E' CHIUSO, e resta chiuso: un titolo scritto a mano
# dall'utente sarebbe una superficie di abuso — «Moderatore»,
# «Barattolo ufficiale» — che nessun esc() risolve, perche' il
# problema non e' l'HTML ma il significato.
TITOLI = (
    # Il primo della fila, e l'unico che non si puo' guadagnare
    [dict(id="t_fondatore", nome="🏛 Fondatore",
          descrizione="Ha fondato Barattolo",
          serve=("fondatore", ""))]
    + [dict(id=f"coorte_{cid}", nome=f"{emo} {nome}", descrizione=desc,
            serve=("coorte", cid)) for _s, cid, emo, nome, desc in COORTI]
    + [dict(id="t_nostrano", nome="🟣 Nostrano",
            descrizione="Serve la npub verificata con nota pubblica",
            serve=("distintivo", "nostrano")),
       dict(id="t_specchiato", nome="🪞 Specchiato",
            descrizione="Serve il distintivo Specchiato",
            serve=("distintivo", "specchiato")),
       dict(id="t_fulmine", nome="⚡ Fulmine",
            descrizione="Serve il distintivo Fulmine",
            serve=("distintivo", "fulmine")),
       dict(id="t_pratico", nome="🧺 Mercante pratico",
            descrizione="Serve il livello «Mercante pratico»",
            serve=("livello", "pratico")),
       dict(id="t_esperto", nome="🏆 Mercante esperto",
            descrizione="Serve il livello «Mercante esperto»",
            serve=("livello", "esperto")),
       dict(id="t_maestro", nome="👑 Maestro del banco",
            descrizione="Serve il livello «Maestro del banco»",
            serve=("livello", "maestro"))])


NOMI_TITOLI = {t["id"]: t["nome"] for t in TITOLI}


def titoli_disponibili(con, tg_id: int) -> list[str]:
    """Gli id dei titoli che quell'utente ha davvero sbloccato. Giudice
    unico: da qui passa sia l'elenco mostrato nel Profilo sia la
    validazione della scelta — o si potrebbe indossare un titolo che
    l'elenco non offre."""
    u = con.execute("SELECT xp, coorte, vendite_ok, acquisti_ok "
                    "FROM utenti WHERE tg_id=?", (tg_id,)).fetchone()
    if not u:
        return []
    badge = {r["badge_id"] for r in con.execute(
        "SELECT badge_id FROM badge_utente WHERE tg_id=?", (tg_id,))}
    liv = livello_utente(u["xp"] or 0,
                         (u["vendite_ok"] or 0) + (u["acquisti_ok"] or 0))
    # I livelli sono una SCALA: chi e' maestro puo' portare anche i
    # titoli dei gradini sotto (li ha attraversati tutti)
    raggiunti = {l[2] for l in LIVELLI[:LIVELLI.index(
        next(l for l in LIVELLI if l[2] == liv["id"])) + 1]}
    fatto = {"coorte": lambda v: v == (u["coorte"] or ""),
             "distintivo": lambda v: v in badge,
             "livello": lambda v: v in raggiunti,
             "fondatore": lambda _v: tg_id in FONDATORI}
    return [t["id"] for t in TITOLI if fatto[t["serve"][0]](t["serve"][1])]


def init_db():
    con = db()
    con.executescript("""
    CREATE TABLE IF NOT EXISTS utenti(
        tg_id INTEGER PRIMARY KEY, nome TEXT, username TEXT,
        ln_address TEXT DEFAULT '',   -- es. mario@walletofsatoshi.com: incassi automatici
        npub TEXT DEFAULT '',         -- npub Nostr auto-dichiarata (badge)
        npub_verificata INTEGER DEFAULT 0,  -- 1 = nota di verifica trovata sui relay
        verifica_codice TEXT DEFAULT '',    -- codice da pubblicare in una nota
        verifica_scade INTEGER DEFAULT 0,   -- il codice vale 1 ora
        registrato INTEGER DEFAULT 0, -- quando l'utente e' entrato la prima volta
        negozio TEXT DEFAULT '',      -- codice pubblico del negozio (URL condivisibile)
        vendite_ok INTEGER DEFAULT 0, acquisti_ok INTEGER DEFAULT 0,
        rating REAL DEFAULT 0, n_feedback INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS annunci(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        venditore_id INTEGER, titolo TEXT, descrizione TEXT,
        categoria TEXT, prezzo_sats INTEGER, zona TEXT,
        foto TEXT DEFAULT '',              -- lista JSON: nomi file o URL
        contatto_nostr TEXT DEFAULT '',    -- npub del venditore (annunci importati)
        nostr_event_id TEXT DEFAULT '',    -- evento NIP-99 firmato dalla piattaforma
        stato TEXT DEFAULT 'attivo',      -- attivo | venduto | rimosso
        creato INTEGER
    );
    CREATE TABLE IF NOT EXISTS ordini(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER, compratore_id INTEGER, venditore_id INTEGER,
        prezzo_sats INTEGER,
        stato TEXT DEFAULT 'creato',
        -- creato | locked | shipped | delivered | confirmed | released
        -- | dispute | return_pending | return_shipped | refund
        -- | refunded | annullato
        -- (delivered = consegnato, finestra di conferma aperta;
        --  return_pending/shipped = rimborso previa restituzione)
        payment_hash TEXT,                 -- invoice dell'acquirente (escrow)
        invoice_venditore TEXT,            -- dove sbloccare i sats
        invoice_rimborso TEXT DEFAULT '',  -- dove rimborsare l'acquirente
        corriere TEXT DEFAULT '', tracking TEXT DEFAULT '',
        corriere_reso TEXT DEFAULT '', tracking_reso TEXT DEFAULT '',
        spedito_il INTEGER DEFAULT 0,      -- per l'auto-sblocco a 10 giorni
        consegnato INTEGER DEFAULT 0,      -- per la finestra delle 72 ore
        sollecito_il INTEGER DEFAULT 0,    -- ultimo promemoria del venditore
        sollecito_incasso_il INTEGER DEFAULT 0, -- ultimo promemoria «incassa!»
        solleciti_incasso INTEGER DEFAULT 0,    -- quanti ne ha ignorati
        creato INTEGER, aggiornato INTEGER
    );
    CREATE TABLE IF NOT EXISTS ordine_righe(
        -- Il set «Riempi il barattolo» (lug 2026): piu' annunci DIVERSI
        -- dello stesso venditore in UN ordine solo. La testata resta in
        -- ordini — un escrow, una invoice, un tracking: annuncio_id=0 e
        -- quantita = somma dei pezzi — e qui vive la merce, una riga
        -- per annuncio. Gli ordini MONO non hanno righe MAI: gliele
        -- sintetizza _righe_ordine dalla testata. unitario_sats e' il
        -- prezzo del singolo pezzo GIA' scontato (lampo/accordo).
        -- LO SCONTO CARRELLO NON LE TOCCA (ago 2026): e' una voce di
        -- TESTATA (ordini.sconto_sats), perche' e' una proprieta' del
        -- CARRELLO e non della cosa — l'unitario resta la FOTOGRAFIA
        -- del listino di quel giorno, e limarlo vorrebbe dire
        -- distribuire un resto su N righe e poi litigarci in disputa.
        -- L'invariante e' della testata:
        --   prezzo_sats = somma(unitario x quantita) - sconto_sats
        --                 + spedizione_sats + protezione_sats
        -- Il titolo si fotografa all'acquisto — il patto delle quote
        -- fissate: l'annuncio puo' cambiare o sparire, l'ordine e la
        -- contabilita' no.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ordine_id INTEGER NOT NULL,
        annuncio_id INTEGER NOT NULL,
        quantita INTEGER NOT NULL DEFAULT 1,
        unitario_sats INTEGER NOT NULL,
        titolo TEXT NOT NULL DEFAULT ''
    );
    CREATE INDEX IF NOT EXISTS idx_righe_ordine
        ON ordine_righe(ordine_id);
    CREATE INDEX IF NOT EXISTS idx_righe_annuncio
        ON ordine_righe(annuncio_id);
    CREATE TABLE IF NOT EXISTS sessioni(
        -- login web dal browser: nel DB c'e' SOLO l'hash del token,
        -- il token vero vive nel cookie dell'utente e basta
        token_hash TEXT PRIMARY KEY,
        tg_id INTEGER,
        creato INTEGER,
        scade INTEGER
    );
    CREATE TABLE IF NOT EXISTS feedback(
        -- il giudizio reciproco a affare concluso: da qui nascono
        -- rating e n_feedback dell'utente (sempre per RICALCOLO,
        -- mai per incremento: cosi' rimozioni e fusioni si sistemano
        -- da sole)
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ordine_id INTEGER NOT NULL,
        da_tg_id INTEGER NOT NULL,   -- chi lo lascia
        per_tg_id INTEGER NOT NULL,  -- chi lo riceve
        voto INTEGER NOT NULL CHECK(voto BETWEEN 1 AND 5),
        commento TEXT DEFAULT '',
        creato INTEGER,
        UNIQUE(ordine_id, da_tg_id)  -- uno per ordine per parte
    );
    CREATE INDEX IF NOT EXISTS idx_feedback_per
        ON feedback(per_tg_id, creato DESC);
    CREATE TABLE IF NOT EXISTS badge_utente(
        -- i distintivi guadagnati; le definizioni (nome, emoji,
        -- criterio) vivono nel codice, in DISTINTIVI: qui solo
        -- chi, cosa, quando
        tg_id INTEGER NOT NULL,
        badge_id TEXT NOT NULL,
        ottenuto_il INTEGER,
        PRIMARY KEY(tg_id, badge_id)
    );
    CREATE TABLE IF NOT EXISTS firme_nostr(
        -- LA CODA DELLE FIRME (ago 2026). Un doppio cittadino che
        -- pubblica qui deve ritrovarsi l'annuncio sul SUO account
        -- Nostr, non su quello di Barattolo: e' la sua reputazione,
        -- non la nostra. Ma la nsec non ce l'abbiamo e non la vogliamo
        -- (regola ferrea 2), quindi a firmare e' il BROWSER — e il
        -- browser c'e' solo quando l'utente e' li'.
        -- Da qui la coda: il server prepara l'evento e aspetta. La
        -- PUBBLICAZIONE e' solo la prima azione, non un caso a parte,
        -- e cosi' pubblicare e aggiornare hanno un motore solo.
        -- UNA riga per annuncio (PK): l'ultima azione vince, che e'
        -- anche la cosa giusta — venduto e poi rimborsato fa 'active',
        -- e non due firme da chiedere.
        annuncio_id INTEGER PRIMARY KEY,
        tg_id INTEGER NOT NULL,
        azione TEXT NOT NULL,     -- pubblica | sold | active | ritira
        creato INTEGER
    );
    CREATE TABLE IF NOT EXISTS xp_eventi(
        -- IL REGISTRO DEGLI XP, ed e' append-only per una ragione che
        -- vale la pena scrivere: distintivi e rating si RICALCOLANO
        -- dai dati veri, quindi una passata retroattiva li rimette in
        -- pari e un bug non lascia cicatrici. Gli XP no — una visita
        -- giornaliera e' un evento, e se non lo scrivi quando succede
        -- e' perso per sempre. Quindi qui la verita' e' la tabella, e
        -- utenti.xp e' solo la sua somma (cache ricalcolabile, come
        -- rating e n_feedback lo sono della tabella feedback).
        -- riferimento = cosa ha guadagnato quei punti
        -- ('ordine:42:venditore', 'giorno:2026-08-04', 'annuncio:7'):
        -- con la UNIQUE qui sotto e' il GIUDICE dell'idempotenza. Non
        -- si chiede a chi scrive un gancio di ricordarsi «gliel'ho
        -- gia' dato?»: un retry, un doppio gancio, un riavvio a meta'
        -- o un moderatore che rilancia una funzione sbattono tutti
        -- contro il vincolo e non pagano due volte.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tg_id INTEGER NOT NULL,
        tipo TEXT NOT NULL,
        punti INTEGER NOT NULL,
        riferimento TEXT NOT NULL DEFAULT '',
        creato INTEGER,
        UNIQUE(tg_id, tipo, riferimento)
    );
    CREATE INDEX IF NOT EXISTS idx_xp_utente ON xp_eventi(tg_id, creato DESC);
    CREATE TABLE IF NOT EXISTS doppioni_ignorati(
        -- «non e' un doppione»: la coppia archiviata non si ripropone
        -- mai piu', su nessun dispositivo (per questo vive nel DB e
        -- non in localStorage)
        id_importato INTEGER NOT NULL,  -- riga con contatto_nostr pieno
        id_nativo INTEGER NOT NULL,     -- riga ripubblicata dalla piattaforma
        tg_id INTEGER,
        creato INTEGER,
        PRIMARY KEY(id_importato, id_nativo)
    );
    CREATE TABLE IF NOT EXISTS avvisi_ricerca(
        -- «dimmi quando esce quello che cerco»: i criteri salvati
        -- dall'utente. Il matching gira alla pubblicazione (coda +
        -- drenatore, gemello dei post automatici)
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tg_id INTEGER NOT NULL,
        categorie TEXT DEFAULT '',    -- '|Elettronica|Motori|' ('' = tutte)
        comune TEXT DEFAULT '',       -- nome dal dataset ('' = tutta Italia)
        lat REAL DEFAULT 0, lon REAL DEFAULT 0,
        raggio_km INTEGER DEFAULT 0,  -- 0 = tutta Italia
        prezzo_max_sats INTEGER DEFAULT 0,  -- tetto in sats (0 = nessuno)
        prezzo_max_eur REAL DEFAULT 0,      -- OPPURE in EUR (mai entrambi)
        parole TEXT DEFAULT '',       -- gia' normalizzate, spazio-separate
        attivo INTEGER DEFAULT 1,     -- 0 = in pausa
        creato INTEGER
    );
    CREATE INDEX IF NOT EXISTS idx_avvisi_ricerca_tg
        ON avvisi_ricerca(tg_id);
    CREATE TABLE IF NOT EXISTS avvisi_notificati(
        -- dedup: lo stesso annuncio non suona MAI due volte per lo
        -- stesso utente (modifiche, re-import). Nel DB e non in
        -- memoria: un riavvio non deve far risuonare nulla.
        tg_id INTEGER NOT NULL,
        annuncio_id INTEGER NOT NULL,
        creato INTEGER,
        PRIMARY KEY(tg_id, annuncio_id)
    );
    CREATE TABLE IF NOT EXISTS preferiti(
        -- «nel tuo barattolo»: gli annunci messi da parte col 🫙.
        -- CHI ha salvato non esce MAI (i preferiti restano privati);
        -- QUANTI si', anonimo e pubblico dall'ago 2026 — il numero
        -- accanto al barattolino in vetrina e nel dettaglio.
        tg_id INTEGER NOT NULL,
        annuncio_id INTEGER NOT NULL,
        creato INTEGER,
        PRIMARY KEY(tg_id, annuncio_id)
    );
    -- La PK e' (tg_id, annuncio_id): senza questo indice il conteggio
    -- per ANNUNCIO — che dall'ago 2026 gira su ogni pagina di vetrina
    -- — sarebbe una scansione della tabella intera.
    CREATE INDEX IF NOT EXISTS idx_preferiti_annuncio
      ON preferiti(annuncio_id);
    CREATE TABLE IF NOT EXISTS offerte(
        -- la contrattazione strutturata (MAI una chat): proposta del
        -- compratore, al massimo UNA controproposta del venditore,
        -- accettazione = diritto di comprare al prezzo concordato
        -- entro la scadenza. L'annuncio NON si blocca mai: vince chi
        -- paga per primo. L'accordo riguarda il SOLO articolo:
        -- spedizione e protezione si sommano sopra come sempre.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER NOT NULL,
        compratore_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        valuta TEXT DEFAULT 'sats',      -- fotografia della valuta del listino
        importo_sats INTEGER DEFAULT 0,  -- la proposta (l'altro campo resta 0)
        importo_eur REAL DEFAULT 0,
        contro_sats INTEGER DEFAULT 0,   -- la controproposta (0 = nessuna)
        contro_eur REAL DEFAULT 0,
        stato TEXT DEFAULT 'proposta',   -- proposta | controproposta | accettata |
                                         -- rifiutata | scaduta | decaduta | conclusa
        scadenza INTEGER DEFAULT 0,      -- il prossimo appuntamento:
                                         -- risposta oppure pagamento
        ordine_id INTEGER DEFAULT 0,     -- l'ordine nato dall'offerta
        creato INTEGER, aggiornato INTEGER
    );
    CREATE INDEX IF NOT EXISTS idx_offerte_annuncio
        ON offerte(annuncio_id, stato);
    CREATE INDEX IF NOT EXISTS idx_offerte_scadenza
        ON offerte(stato, scadenza);
    CREATE INDEX IF NOT EXISTS idx_offerte_compratore
        ON offerte(compratore_id);
    CREATE INDEX IF NOT EXISTS idx_offerte_venditore
        ON offerte(venditore_id);
    CREATE TABLE IF NOT EXISTS offerte_lampo(
        -- lo STORICO dei lanci: la lampo attiva vive sulle colonne
        -- annunci.lampo_* (una sola per annuncio, lettura pubblica
        -- veloce), ma quelle si sovrascrivono e non contano il
        -- passato — questo registro serve al tetto settimanale.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        percento INTEGER, scadenza INTEGER, creato INTEGER
    );
    CREATE INDEX IF NOT EXISTS idx_lampo_annuncio
        ON offerte_lampo(annuncio_id, creato);
    CREATE TABLE IF NOT EXISTS puntate(
        -- l'asta (ago 2026): UNA riga per offerente per asta — la sua
        -- cassaforte in gara. 'chiusa' = ritirato o perdente: i suoi
        -- sats vivono nel registro rimborsi_asta. IL RITIRO E'
        -- DEFINITIVO: la riga 'chiusa' su un'asta viva E' il divieto
        -- di rientro (mette un tetto per costruzione ai rimborsi, uno
        -- a offerente, e rende il gesto inequivocabile). L'etichetta
        -- anonima («Offerente A, B, C...») si assegna al primo saldo
        -- ed e' stabile dentro l'asta.
        -- VERSATO vs ESPOSTO (il proxy, ago 2026): versato e' il
        -- budget in cassaforte, offerto la puntata VISIBILE in gara.
        -- INVARIANTE: versato >= offerto SEMPRE, uguali quando
        -- proxy=0 (le manuali di sempre). La CAPACITA' che gareggia
        -- e' il versato; il pubblico vede solo l'esposto, e chi vince
        -- paga l'ESPOSTO — l'eccedenza torna dal registro.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER NOT NULL,
        tg_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        etichetta TEXT DEFAULT '',
        versato_sats INTEGER DEFAULT 0,  -- somma dei delta SALDATI
                                         -- (= il budget, segreto)
        offerto_sats INTEGER DEFAULT 0,  -- l'ESPOSTO che gareggia
        proxy INTEGER DEFAULT 0,         -- 1 = «rilancia per me»: il
                                         -- motore espone il minimo
        -- il numero d'ordine dell'ULTIMO saldo (progressivo globale):
        -- e' il tie-break della testa — l'orario ha la risoluzione del
        -- secondo, e due saldi nello stesso secondo sono gia' successi
        -- in collaudo. «Fa fede l'orario di saldo» si giudica da qui.
        saldo_seq INTEGER DEFAULT 0,
        stato TEXT DEFAULT 'attiva',     -- attiva | vincitrice | chiusa
        creato INTEGER, aggiornato INTEGER,
        UNIQUE(annuncio_id, tg_id)
    );
    CREATE INDEX IF NOT EXISTS idx_puntate_annuncio
        ON puntate(annuncio_id, stato);
    CREATE INDEX IF NOT EXISTS idx_puntate_utente
        ON puntate(tg_id, stato);
    CREATE TABLE IF NOT EXISTS rilanci(
        -- una riga per FATTURA di versamento: il client dichiara il
        -- totale desiderato, il SERVER calcola la differenza da
        -- versare (mai fidarsi di importi dal client). Fa fede
        -- l'orario di SALDO: un pagamento non si respinge mai — se
        -- nel frattempo la testa e' salita si resta puntata valida
        -- non in testa; 'tardivo' = saldato ad asta gia' chiusa, i
        -- sats vanno dritti nel registro rimborsi. Nessun ordine,
        -- nessuna eccezione.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        puntata_id INTEGER NOT NULL,
        annuncio_id INTEGER NOT NULL,
        tg_id INTEGER NOT NULL,
        offerto_sats INTEGER NOT NULL,   -- il totale dichiarato (per
                                         -- una fattura proxy e' il
                                         -- MASSIMO segreto: mai in
                                         -- cronologia — quella legge
                                         -- esposto_sats)
        delta_sats INTEGER NOT NULL,     -- la fattura (calcolo server)
        payment_hash TEXT DEFAULT '',
        stato TEXT DEFAULT 'creato',     -- creato | saldato | tardivo
                                         -- | annullato (la lapide)
        proxy INTEGER DEFAULT 0,         -- l'intento dichiarato
        esposto_sats INTEGER DEFAULT 0,  -- l'esposto al saldo (post
                                         -- motore): la cifra pubblica
        creato INTEGER, saldato_il INTEGER DEFAULT 0,
        aggiornato INTEGER
    );
    CREATE INDEX IF NOT EXISTS idx_rilanci_puntata
        ON rilanci(puntata_id, stato);
    CREATE INDEX IF NOT EXISTS idx_rilanci_annuncio
        ON rilanci(annuncio_id, stato);
    CREATE TABLE IF NOT EXISTS rimborsi_asta(
        -- il REGISTRO dei rimborsi, con chiave d'idempotenza: la
        -- chiusura deve poter morire a meta' ed essere rilanciata
        -- senza rimborsi doppi ne' ordini doppi. «Da riscuotere» e'
        -- lo stesso binario degli incassi venditore (cascata invoice
        -- depositata -> LN address -> fermo col sollecito): NESSUN
        -- tubo nuovo per i pagamenti in uscita. INVARIANTE (aggiornata
        -- col proxy): per ogni asta finita, somma dei delta saldati =
        -- OFFERTO (esposto) della vincitrice + somma degli importi
        -- qui dentro — perdenti col versato pieno, piu' l'eccedenza
        -- della vincitrice quando il suo budget supera l'esposto.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER NOT NULL,
        tg_id INTEGER NOT NULL,
        puntata_id INTEGER NOT NULL,
        rilancio_id INTEGER DEFAULT 0,   -- >0 solo per i saldi tardivi
        importo_sats INTEGER NOT NULL,
        motivo TEXT DEFAULT '',          -- ritiro | perdente | tardivo
                                         -- | annullo_admin
                                         -- | eccedenza_ritiro (gesto
                                         --   del leader proxy, a gara
                                         --   viva) | eccedenza (della
                                         --   vincitrice, a chiusura)
                                         -- DUE motivi APPOSTA: uno
                                         -- solo, con la fusione che
                                         -- riaccende il proxy, farebbe
                                         -- ignorare la riga di
                                         -- chiusura dall'indice
                                         -- parziale = sats mai
                                         -- rimborsati in silenzio
        stato TEXT DEFAULT 'da_riscuotere',  -- da_riscuotere | riscosso
        invoice_riscossione TEXT DEFAULT '',
        solleciti INTEGER DEFAULT 0,
        sollecito_il INTEGER DEFAULT 0,
        creato INTEGER, aggiornato INTEGER
    );
    CREATE INDEX IF NOT EXISTS idx_rimborsi_utente
        ON rimborsi_asta(tg_id, stato);
    CREATE INDEX IF NOT EXISTS idx_rimborsi_annuncio
        ON rimborsi_asta(annuncio_id);
    -- le due cinture d'idempotenza (indici PARZIALI): un solo
    -- rimborso da chiusura per puntata, un solo rimborso per saldo
    -- tardivo — anche se un domani una query se ne dimenticasse
    CREATE UNIQUE INDEX IF NOT EXISTS idx_rimborso_chiusura
        ON rimborsi_asta(puntata_id)
        WHERE motivo IN ('perdente', 'annullo_admin');
    CREATE UNIQUE INDEX IF NOT EXISTS idx_rimborso_tardivo
        ON rimborsi_asta(rilancio_id) WHERE rilancio_id > 0;
    -- le cinture del proxy: l'eccedenza si ritira UNA volta per asta
    -- («scesa non risale»), e la riga di chiusura non si raddoppia
    CREATE UNIQUE INDEX IF NOT EXISTS idx_rimborso_ecc_ritiro
        ON rimborsi_asta(puntata_id) WHERE motivo = 'eccedenza_ritiro';
    CREATE UNIQUE INDEX IF NOT EXISTS idx_rimborso_eccedenza
        ON rimborsi_asta(puntata_id) WHERE motivo = 'eccedenza';
    CREATE TABLE IF NOT EXISTS moderazione_log(
        -- il REGISTRO della moderazione (lug 2026): ogni esito, della
        -- macchina e dell'umano, per correggere il prompt A MANO sui
        -- dati veri. Append-only; la macchina raccoglie, mai decide.
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        annuncio_id INTEGER DEFAULT 0,   -- 0 = bloccato prima di nascere
        titolo TEXT DEFAULT '',
        venditore_id INTEGER DEFAULT 0,
        strato TEXT DEFAULT '',          -- parole | ai | ai_lotto | admin
        esito TEXT DEFAULT '',           -- vietato | dubbio | pubblicato | rifiutato | rimosso
        motivo TEXT DEFAULT '',
        deciso_da INTEGER DEFAULT 0,     -- tg_id del moderatore (0 = la macchina)
        creato INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS categoria_proposta(
        -- La coda della RICATEGORIZZAZIONE (lug 2026): quando il
        -- catalogo e' passato da 9 a 25 voci, gli annunci di ieri sono
        -- rimasti nelle caselle di ieri (un portatile in «Elettronica»
        -- invece che in «Informatica») e gli importati nascono tutti
        -- in «Altro». Uno script chiede all'AI dove starebbero meglio
        -- e scrive QUI: nella colonna `annunci.categoria` non ci
        -- arriva mai da solo — un annuncio non cambia casella senza
        -- che un umano l'abbia vista.
        -- Una riga per annuncio (l'ultima proposta vince), e resta
        -- dopo la decisione: e' anche il registro di cos'e' successo.
        annuncio_id INTEGER PRIMARY KEY,
        categoria_ora TEXT DEFAULT '',
        categoria_nuova TEXT DEFAULT '',
        motivo TEXT DEFAULT '',
        creato INTEGER DEFAULT 0,
        stato TEXT DEFAULT 'proposta',   -- proposta | applicata | scartata
        deciso_da INTEGER DEFAULT 0,     -- tg_id del moderatore
        deciso_il INTEGER DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_categoria_proposta
        ON categoria_proposta(stato, categoria_ora, categoria_nuova);
    CREATE TABLE IF NOT EXISTS cambio_noto(
        -- L'ULTIMO CAMBIO CHE ABBIAMO LETTO DAVVERO (ago 2026). Una
        -- riga sola, oggi 'eur'. NON e' un dato di denaro e nessun
        -- conto ci poggia sopra: e' il promemoria fra un riavvio e
        -- l'altro — la verita' resta CoinGecko, questa e' la memoria
        -- di cosa aveva detto l'ultima volta che ha risposto. Serve
        -- perche' la cache in RAM nasceva vuota, e un deploy dentro
        -- un'interruzione lasciava l'app senza saper convertire.
        valuta TEXT PRIMARY KEY,      -- 'eur' (oggi l'unica)
        valore REAL DEFAULT 0,        -- euro per BTC
        quando INTEGER DEFAULT 0      -- quando l'abbiamo letto (unix)
    );
    """)
    # Migrazione per database creati prima dell'introduzione degli
    # incassi automatici: aggiunge la colonna se manca.
    try:
        con.execute("ALTER TABLE utenti ADD COLUMN ln_address TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    # Migrazioni utenti: badge Nostr (npub e verifica), data di
    # registrazione (chi c'era gia' resta senza data: si mostra "—")
    # e npub_accesso = la chiave Nostr che puo' ENTRARE in questa riga
    # (login Nostr). Diversa dal badge npub: quella e' una dichiarazione
    # pubblica, questa e' una credenziale. Oggi la valorizza il login
    # Nostr; domani anche un account Telegram potra' riceverla (doppia
    # cittadinanza) senza toccare lo schema.
    for colonna in ("npub TEXT DEFAULT ''",
                    "npub_verificata INTEGER DEFAULT 0",
                    "verifica_codice TEXT DEFAULT ''",
                    "verifica_scade INTEGER DEFAULT 0",
                    "registrato INTEGER DEFAULT 0",
                    "negozio TEXT DEFAULT ''",
                    "npub_accesso TEXT DEFAULT ''",
                    # canale_notifiche: '' = automatico (Telegram se
                    # tg_id>0, DM Nostr per i nativi), oppure la scelta
                    # esplicita 'telegram' | 'nostr' | 'entrambi'
                    "canale_notifiche TEXT DEFAULT ''",
                    # avatar (lug 2026): il francobollo della foto
                    # profilo, preso dal social di provenienza (foto
                    # Telegram, o picture del kind-0 Nostr). Nome file
                    # in foto/ ('' = niente foto, resta l'iniziale);
                    # avatar_scelta e' il selettore «La tua foto» del
                    # cassetto Identita': '' = automatico (la catena
                    # Telegram → Nostr → iniziale), oppure la scelta
                    # esplicita 'telegram' | 'nostr' | 'nessuna'
                    "avatar TEXT DEFAULT ''",
                    "avatar_aggiornato INTEGER DEFAULT 0",
                    "avatar_scelta TEXT DEFAULT ''",
                    # suggerimenti_annunci (lug 2026): l'interruttore
                    # del singolo utente per «💡 Suggerimenti sui miei
                    # annunci». Il VALORE della sua scelta, e non se
                    # l'ha fatta — quello lo dice la colonna qui sotto.
                    # Dall'ago 2026 il default di serie e' una LEVA
                    # (SUGGERIMENTI_DI_SERIE, accesa) e questo 0 non e'
                    # piu' «spento», e' solo «il valore di partenza di
                    # una riga che nessuno ha ancora toccato»: a
                    # deciderlo e' suggerimenti_accesi().
                    "suggerimenti_annunci INTEGER DEFAULT 0",
                    # IL GESTO (ago 2026): 0 = l'utente non ha mai
                    # toccato quell'interruttore, 1 = ha deciso lui, in
                    # un verso o nell'altro. Serve perche' «acceso di
                    # serie» e «acceso da lui» sono la stessa cosa
                    # finche' non si vuole ROVESCIARE il default: da
                    # quel momento chi l'aveva spento a mano deve
                    # restare spento, e senza questa colonna e'
                    # indistinguibile da chi non l'ha mai guardato.
                    # UNA COLONNA E NON UN TERZO STATO dentro l'altra:
                    # con «2 = spento esplicito» il primo
                    # `if u["suggerimenti_annunci"]` scritto
                    # distrattamente leggerebbe 2 come ACCESO — fallire
                    # nel verso di scrivere a chi ha detto no. Cosi'
                    # invece il valore conserva per sempre il suo
                    # significato (0 no, 1 si'), che e' il patto delle
                    # due soglie dello sconto e delle due tariffe di
                    # spedizione.
                    "suggerimenti_scelti INTEGER DEFAULT 0",
                    # IL RITMO (ago 2026): quando e' partito l'ULTIMO
                    # suggerimento, di qualunque tipo. Il tetto e' per
                    # PERSONA e non per coda — prima era per annuncio, e
                    # chi ne pubblicava cinque in un pomeriggio ne
                    # riceveva cinque. Il perche' vale piu' del come:
                    # chi si stufa BLOCCA IL BOT, e col bot bloccato non
                    # riceve piu' le notifiche degli ordini, che sono
                    # portanti; su Nostr il danno e' lo stesso e meno
                    # visibile, perche' smette semplicemente di leggere
                    # i DM. Un consiglio non vale quel rischio.
                    "suggerito_il INTEGER DEFAULT 0",
                    # I due timbri dei suggerimenti di FUNZIONE: una
                    # volta sola per sempre, come avvisato_contatto e
                    # avvisato_spedizioniere (quattro precedenti in
                    # casa, tutti a colonna). Il ritmo qui sopra e'
                    # un'altra cosa e vive per conto suo: questi dicono
                    # «gliel'ho gia' detto», quello «non adesso».
                    "suggerito_sconto INTEGER DEFAULT 0",
                    "suggerito_sped INTEGER DEFAULT 0",
                    # n_recensori (ago 2026): quante PERSONE DIVERSE
                    # hanno lasciato un feedback, accanto a quanti
                    # feedback sono. Serve perche' i feedback del
                    # negozio pubblico escono senza nomi (di
                    # proposito: chi ha comprato non si annuncia), e
                    # senza questo numero un venditore con 40 feedback
                    # dallo stesso account si vede IDENTICO a uno con
                    # 40 feedback di 40 persone. Non e' un giudizio:
                    # e' il dato che permette a chi guarda di darne
                    # uno. Ricalcolata da _ricalcola_rating come
                    # rating e n_feedback, quindi rimozione admin e
                    # fusione si sistemano da sole.
                    "n_recensori INTEGER DEFAULT 0",
                    # xp (ago 2026): la SOMMA del registro xp_eventi,
                    # tenuta qui perche' ogni card e ogni profilo la
                    # legge e non si fa una SUM per riga. Cache, non
                    # verita': si rifa' da capo con _ricalcola_xp, che
                    # e' cio' che rende la fusione un caso non
                    # speciale (si sommano i registri e si ricalcola).
                    # xp_ultimo_giorno e' il giorno LOCALE dell'ultima
                    # visita premiata: serve solo a non rifare la
                    # scrittura mille volte al giorno — a impedire il
                    # doppio punto ci pensa comunque la UNIQUE del
                    # registro, questa e' cortesia verso il database.
                    "xp INTEGER DEFAULT 0",
                    "xp_ultimo_giorno TEXT DEFAULT ''",
                    # coorte (ago 2026): in che ondata e' arrivato.
                    # CONGELATA al primo calcolo — la posizione in una
                    # fila non cambia mai piu' —, '' = arrivato oltre
                    # l'ultima soglia, e va bene cosi'.
                    "coorte TEXT DEFAULT ''",
                    # Il sollecito «hai annunci che aspettano la tua
                    # firma»: per UTENTE e non per annuncio — si bussa
                    # una volta sola per tutta la coda, o dieci
                    # annunci farebbero dieci messaggi. Colonne sue e
                    # non quelle degli altri solleciti: un contatore
                    # ereditato manderebbe al tetto una coda appena
                    # nata (la lezione di sollecita_conferme_ferme).
                    "sollecito_firme_il INTEGER DEFAULT 0",
                    "solleciti_firme INTEGER DEFAULT 0",
                    # titolo (ago 2026): quale dei titoli SBLOCCATI
                    # l'utente ha scelto di portare sotto il nome
                    # ('' = nessuno). Il distintivo dice «ho fatto»,
                    # il titolo dice «chi sono», ed e' la parte che si
                    # sceglie. Catalogo CHIUSO: un titolo scritto a
                    # mano sarebbe impersonazione («Moderatore»), che
                    # non e' un problema di esc() ma di significato.
                    "titolo TEXT DEFAULT ''",
                    # comune: COLONNA INERTE (lug 2026). Nata per il
                    # filtro «📍 Vicino a me», tolto due giorni dopo
                    # perche' si sovrapponeva al filtro per regione —
                    # oggi nessuno la scrive e nessuno la legge. Resta
                    # per non fare una migrazione distruttiva su chi
                    # l'aveva gia' valorizzata in quei due giorni, come
                    # avatar_visibile prima di lei. Chi la ritrova: non
                    # e' un dato su cui contare, e se serve un comune
                    # dell'utente va ripensato da capo.
                    "comune TEXT DEFAULT ''",
                    # spedizioniere (ago 2026, pagina d'acquisto): con
                    # che rete di punti di ritiro spedisce il negozio
                    # (catalogo SPEDIZIONIERI). '' = non dichiarato —
                    # dal secondo giro del cantiere la via punto resta
                    # OFFERTA lo stesso (decisione di Andrea: meglio
                    # l'accordo in chat che la porta chiusa), e il
                    # dichiarato serve a dire al compratore la rete
                    # («Spedisce con InPost») invece della riga
                    # «accordatevi in chat».
                    "spedizioniere TEXT DEFAULT ''",
                    # il timbro della notifica una-tantum ai venditori
                    # che spediscono senza spedizioniere dichiarato
                    # (avvisa_spedizioniere_mancante): UNA volta per
                    # venditore, mai un giro dopo — e' una colonna e
                    # non memoria, deve sopravvivere ai riavvii
                    "avvisato_spedizioniere INTEGER DEFAULT 0",
                    # il timbro del venditore irraggiungibile (ago
                    # 2026): chi pubblica senza username ne' npub
                    # dimostrata riceve UN avviso dal bot, alla prima
                    # pubblicazione e mai piu' (avvisa_contatto_
                    # mancante) — colonna e non memoria, il patto del
                    # gemello qui sopra
                    "avvisato_contatto INTEGER DEFAULT 0",
                    # il timbro dell'avviso sul rischio del trasporto
                    # (ago 2026): il foglio che si legge PRIMA della
                    # prima spedizione — il deposito protegge i sats,
                    # non il pacco. UNA volta per venditore e per
                    # sempre; colonna e non localStorage perche' e' un
                    # fatto della PERSONA e non del dispositivo (a
                    # differenza del dismiss del wallet NWC, che il
                    # wallet ce l'ha solo quel telefono).
                    "avvisato_trasporto INTEGER DEFAULT 0",
                    # IL NEGOZIO IN FERIE (ago 2026): 0 = aperto,
                    # altrimenti il timestamp del rientro. UNA colonna
                    # e non un booleano piu' una data, ed e' la scelta
                    # che porta via tutto il resto del lavoro: come
                    # lampo_scadenza e asta_scadenza il gate e' in
                    # LETTURA, quindi il negozio riapre DA SOLO quando
                    # la data passa — se il server resta spento una
                    # settimana, al riavvio chi doveva riaprire e' gia'
                    # aperto. Gli annunci non si toccano mai: restano
                    # in vetrina, col prezzo in grigio.
                    "ferie_fino INTEGER DEFAULT 0",
                    # il timbro del promemoria del giorno prima
                    # (avvisa_rientro_ferie): si scrive PRIMA
                    # dell'invio — un errore di rete puo' perdere un
                    # avviso di cortesia, mai raddoppiarlo — e lo
                    # rimette a zero la scopa, per le ferie successive
                    "ferie_avvisato INTEGER DEFAULT 0",
                    # LO SCONTO CARRELLO (ago 2026): la regola del
                    # negozio — «da N articoli, −X%» — che vale su
                    # tutti i suoi annunci. 0/0 = spento, e non serve
                    # una terza colonna «dichiarata» come per la
                    # tariffa punto: li' lo zero era ambiguo (gratis o
                    # non detto?), qui uno sconto dello 0% e nessuno
                    # sconto sono la stessa cosa per chiunque guardi.
                    # Prima la soglia e poi la percentuale, come si
                    # legge la frase.
                    "sconto_pacco_soglia INTEGER DEFAULT 0",
                    "sconto_pacco_percento INTEGER DEFAULT 0",
                    # IL CRITERIO della soglia (ago 2026): 'pezzi' come
                    # sempre, oppure 'valore' — «da N € di articoli
                    # nel carrello». Il DEFAULT 'pezzi' E' la
                    # migrazione: SQLite riempie da sola le righe di
                    # ieri, e chi sconta oggi continua identico senza
                    # che nessuno tocchi un dato (il precedente in casa
                    # e' "valuta TEXT DEFAULT 'sats'" degli annunci).
                    "sconto_pacco_criterio TEXT DEFAULT 'pezzi'",
                    # La soglia a VALORE in una colonna SUA:
                    # sconto_pacco_soglia resta i PEZZI e non cambia MAI
                    # significato. Costa una colonna e la ripaga due
                    # volte — chi legge il database a mano (il polso
                    # SQL) non deve incrociare due colonne per sapere
                    # cosa vuol dire un numero, e chi prova il criterio
                    # a valore e torna indietro ritrova la sua soglia a
                    # pezzi. E' il patto delle due tariffe di
                    # spedizione, tenute separate.
                    # QUESTA E' IN SATS ED E' MORTA (ago 2026, il
                    # passaggio all'euro): non la legge piu' nessuno.
                    # Resta perche' una colonna non cambia mai
                    # significato — e perche' e' da qui che
                    # converti_soglie_euro.py pesca. Precedenti in
                    # casa: utenti.comune e avatar_visibile.
                    "sconto_pacco_valore INTEGER DEFAULT 0",
                    # ...e la sua erede, in EURO INTERI. Interi e non
                    # centesimi ne' REAL: il filo della soglia resta
                    # esatto senza inventare una convenzione nuova, la
                    # colonna ha la stessa forma delle sorelle, e una
                    # soglia e' una promessa di bottega — «da 50 €»,
                    # non «da 49,90», che e' un trucco da listino.
                    "sconto_pacco_valore_eur INTEGER DEFAULT 0",
                    # LA SPEDIZIONE GRATIS SOPRA SOGLIA (ago 2026): il
                    # valore di articoli da cui il negozio non fa pagare
                    # la spedizione; 0 = promessa spenta. UNA colonna e
                    # basta — niente criterio (il criterio E' il
                    # valore) e niente percentuale (gratis e' gratis) —
                    # e nessuna «dichiarata», per la stessa ragione
                    # dello sconto: una soglia a zero e nessuna
                    # promessa sono la stessa cosa per chi guarda.
                    # Anche qui la prima e' in sats ed e' MORTA, e la
                    # seconda in euro interi: le ragioni sono le stesse
                    # della gemella qui sopra.
                    "sped_gratis_soglia INTEGER DEFAULT 0",
                    "sped_gratis_soglia_eur INTEGER DEFAULT 0"):
        try:
            con.execute(f"ALTER TABLE utenti ADD COLUMN {colonna}")
        except sqlite3.OperationalError:
            pass
    # La levetta binaria avatar_visibile e' vissuta solo nei DB di
    # collaudo (mai deployata): chi l'aveva spenta passa a 'nessuna'
    # nel selettore che l'ha sostituita, la colonna vecchia resta
    # inerte dov'era
    try:
        con.execute("UPDATE utenti SET avatar_scelta='nessuna' "
                    "WHERE avatar_visibile=0 AND avatar_scelta=''")
    except sqlite3.OperationalError:
        pass   # DB nato dopo la levetta: la colonna vecchia non c'e'
    # Due account non possono condividere la stessa chiave di accesso:
    # lo garantisce il database stesso, non solo il codice.
    con.execute(
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_utenti_npub_accesso "
        "ON utenti(npub_accesso) WHERE npub_accesso != ''")
    # Ogni utente riceve il codice pubblico del negozio, una volta sola
    # (i nuovi lo prendono all'ingresso, in verifica_utente)
    for r in con.execute(
            "SELECT tg_id FROM utenti WHERE negozio=''").fetchall():
        con.execute("UPDATE utenti SET negozio=? WHERE tg_id=?",
                    (nuovo_codice_negozio(con), r["tg_id"]))
    # «Fondatore» e' diventato un titolo dei due che hanno fatto
    # Barattolo, quindi la coorte dei primi 500 ha cambiato nome. Una
    # riga, idempotente: chi l'aveva gia' scritta in colonna la trova
    # raddrizzata e non si accorge di niente.
    try:
        con.execute("UPDATE utenti SET coorte='primi_giorni' "
                    "WHERE coorte='fondatore'")
        con.execute("UPDATE utenti SET titolo='coorte_primi_giorni' "
                    "WHERE titolo='coorte_fondatore'")
    except sqlite3.OperationalError:
        pass
    # I fondatori portano il loro titolo SUBITO, senza doverlo
    # scegliere: non e' un premio da sbloccare, e' chi sono. Solo se
    # il posto e' libero — chi ne ha scelto un altro se lo tiene.
    for tg in FONDATORI:
        con.execute("UPDATE utenti SET titolo='t_fondatore' "
                    "WHERE tg_id=? AND titolo=''", (tg,))
    # Le coorti di chi c'era gia': idempotente, tocca solo chi non ce
    # l'ha ancora (la colonna e' congelata al primo calcolo). Girato in
    # ordine d'iscrizione, cosi' la posizione e' quella vera.
    try:
        for r in con.execute(
                "SELECT tg_id FROM utenti WHERE coorte='' "
                "ORDER BY registrato, tg_id").fetchall():
            assegna_coorte(con, r["tg_id"])
    except sqlite3.OperationalError:
        pass
    # n_recensori per chi aveva gia' dei feedback: idempotente, tocca
    # solo le righe ancora vuote (gemello di deriva_regioni). Da qui
    # in poi ci pensa _ricalcola_rating a ogni voto.
    try:
        con.execute(
            "UPDATE utenti SET n_recensori=("
            "  SELECT COUNT(DISTINCT da_tg_id) FROM feedback "
            "  WHERE per_tg_id=utenti.tg_id) "
            "WHERE n_recensori=0 AND n_feedback>0")
    except sqlite3.OperationalError:
        pass   # la tabella feedback nasce piu' sotto: al primo avvio non c'e'
    # Migrazioni annunci: foto, contatto Nostr, l'evento NIP-99
    # pubblicato dalla piattaforma e la doppia valuta (il venditore
    # sceglie se il listino e' in sats o in EUR; per gli annunci EUR
    # prezzo_sats resta l'equivalente al cambio di pubblicazione)
    # nostr_origine_d/foto: le coordinate dell'evento importato (tag d
    # e URL foto originali), scritte dall'import — servono alla
    # modifica firmata per ricostruire l'evento da sostituire sui relay
    # post_canale_id/post_nostr_id: i riferimenti dei post automatici
    # (message_id nel canale Telegram, event id della nota kind-1),
    # scritti solo dai post singoli — servono al ciclo di vita
    # (✏️ "Venduto" sul canale, cancellazione alla rimozione)
    for colonna in ("foto TEXT DEFAULT ''", "contatto_nostr TEXT DEFAULT ''",
                    "nostr_event_id TEXT DEFAULT ''",
                    # nostr_autore (ago 2026): la chiave hex che ha
                    # FIRMATO l'evento di questo annuncio ('' = la
                    # piattaforma, com'e' sempre stato). Serve a una
                    # cosa sola ma decisiva: un evento firmato
                    # dall'utente la piattaforma NON lo puo' piu'
                    # toccare — niente «venduto», niente NIP-09 — e
                    # senza questa colonna ci proverebbe lo stesso,
                    # scrivendone uno suo accanto al suo.
                    # NON si usa contatto_nostr per dirlo: quella
                    # colonna significa «importato dai relay» e
                    # l'import orario riscriverebbe l'annuncio da capo
                    # (piu' l'invariante che le due non stiano insieme).
                    "nostr_autore TEXT DEFAULT ''",
                    "valuta TEXT DEFAULT 'sats'",
                    "prezzo_eur REAL DEFAULT 0",
                    "nostr_origine_d TEXT DEFAULT ''",
                    "nostr_origine_foto TEXT DEFAULT ''",
                    "post_canale_id INTEGER DEFAULT 0",
                    "post_nostr_id TEXT DEFAULT ''",
                    # lat/lon: coordinate del comune riconosciuto nella
                    # zona (0,0 = non riconosciuta). Scritte una volta
                    # alla pubblicazione/modifica, mai a ogni match; il
                    # backfill vive in backfill_coordinate(), che gira
                    # dopo carica_comuni()
                    "lat REAL DEFAULT 0",
                    "lon REAL DEFAULT 0",
                    # regione (lug 2026): DERIVATA dalla sigla della
                    # provincia nella zona, mai chiesta al venditore
                    # ('' = sigla assente o sconosciuta). Serve al filtro
                    # della vetrina; il backfill vive in deriva_regioni()
                    "regione TEXT DEFAULT ''",
                    # consegna e spedizione (lug 2026, modello Vinted):
                    # la modalita' la sceglie il venditore ('' = non
                    # specificata: annunci storici e importati, per loro
                    # tutto resta come prima che la spedizione esistesse);
                    # il costo e' nella valuta del listino, con
                    # l'equivalente sats al cambio di pubblicazione (lo
                    # stesso patto di prezzo_sats); la taglia del pacco
                    # servira' alle etichette automatiche di domani
                    "consegna TEXT DEFAULT ''",
                    "spedizione_sats INTEGER DEFAULT 0",
                    "spedizione_eur REAL DEFAULT 0",
                    "taglia_pacco TEXT DEFAULT ''",
                    # anche_digitale (lug 2026): la gift card che si puo'
                    # avere in due modi — la modalita' fisica in consegna
                    # + il codice in piattaforma. Ortogonale di proposito:
                    # consegna tiene la semantica di sempre e ogni check
                    # esistente resta vero; lecito solo con una modalita'
                    # fisica (con 'digitale' o '' si forza 0)
                    "anche_digitale INTEGER DEFAULT 0",
                    # condizione dell'oggetto (lug 2026): la scala a 5
                    # livelli del form ('' = annunci storici e importati,
                    # nessun obbligo retroattivo; la modifica la chiede)
                    "condizione TEXT DEFAULT ''",
                    # offerta lampo (lug 2026): lo sconto a tempo su
                    # tutto l'annuncio. percento>0 e scadenza nel futuro
                    # = attiva; oltre la scadenza torna prezzo pieno da
                    # solo (la lettura gatea su scadenza, l'orologio
                    # ripulisce). Non tocca mai prezzo_sats/prezzo_eur.
                    # colpo_avvisato: memoria del cooldown dell'avviso
                    # anonimo «ha fatto colpo» al venditore.
                    "lampo_percento INTEGER DEFAULT 0",
                    "lampo_scadenza INTEGER DEFAULT 0",
                    "lampo_creato INTEGER DEFAULT 0",
                    "lampo_colpo_avvisato INTEGER DEFAULT 0",
                    # quantita (lug 2026): i pezzi disponibili ADESSO,
                    # non lo storico. Default 1 = ogni annuncio di ieri
                    # resta un pezzo solo. INVARIANTE: stato='venduto'
                    # <=> quantita=0 (l'esaurito RIUSA lo stato venduto,
                    # nessuno stato nuovo: tutti i filtri di vetrina,
                    # offerte e import valgono gratis). Scala in
                    # verifica_pagamento, risale col rimborso e con la
                    # ricarica del venditore.
                    "quantita INTEGER DEFAULT 1",
                    # modificato (lug 2026): quando il contenuto e'
                    # cambiato l'ultima volta (0 = mai). Per i nativi lo
                    # scrivono modifica() e la modifica firmata; per gli
                    # importati l'import ci mette la data dell'EVENTO
                    # Nostr (created_at), che per un replaceable e' la
                    # data di pubblicazione vera. Serve alla riga
                    # «pubblicato/aggiornato N giorni fa» del dettaglio.
                    "modificato INTEGER DEFAULT 0",
                    # completamento_avvisato (lug 2026, import aperto):
                    # al venditore scoperto su Nostr si chiede UNA volta
                    # sola di completare cio' che l'evento NIP-99 non
                    # porta (consegna, condizione, categoria). Una
                    # colonna e non una coda in memoria, perche' «gliel'ho
                    # gia' chiesto» deve sopravvivere ai riavvii: e' la
                    # differenza tra un invito e il ronzio di ogni ora.
                    "completamento_avvisato INTEGER DEFAULT 0",
                    # sottocategoria (ago 2026): l'albero DORMIENTE —
                    # il catalogo SOTTOCATEGORIE esiste, nessuna UI la
                    # mostra ancora. '' = non dichiarata, per sempre
                    # lecito; la scrivono solo i payload che la portano
                    # gia' oggi (facoltativa e silenziosa)
                    "sottocategoria TEXT DEFAULT ''",
                    # asta a tempo (ago 2026): base>0 = quest'annuncio
                    # e' un'asta; viva = scadenza nel futuro; base>0 e
                    # scadenza=0 = deserta, in mano al venditore (che
                    # la rilancia o converte a prezzo fisso). Il patto
                    # e' quello di lampo_*: il gate e' in LETTURA,
                    # l'orologio chiude e aggiudica. prezzo_sats RESTA
                    # la base d'asta e non si tocca mai;
                    # asta_avvisata_1h e' il timbro dell'avviso «scade
                    # tra 1h» ai partecipanti (una volta sola).
                    "asta_base_sats INTEGER DEFAULT 0",
                    "asta_scadenza INTEGER DEFAULT 0",
                    "asta_creato INTEGER DEFAULT 0",
                    "asta_avvisata_1h INTEGER DEFAULT 0",
                    # il secondo costo di spedizione (ago 2026, pagina
                    # d'acquisto): la tariffa verso un PUNTO DI RITIRO,
                    # gemella byte-per-byte di spedizione_sats/eur
                    # (stessa semantica di valuta: sats = fisso, eur =
                    # ancorato). Il FLAG distingue «non dichiarato»
                    # (vale la tariffa casa, retrocompat decisa da
                    # Andrea) da «dichiarato 0 = gratis al punto» — una
                    # sentinella -1 costringerebbe guardie >=0 sparse.
                    "spedizione_punto_sats INTEGER DEFAULT 0",
                    "spedizione_punto_eur REAL DEFAULT 0",
                    "spedizione_punto_dichiarata INTEGER DEFAULT 0",
                    # IL SUPPLEMENTO PER PEZZO (ago 2026, caso dal
                    # campo: il riso da 4 kg venduto a sacchi, con la
                    # spedizione di UNO solo dichiarata). Gemella di
                    # spedizione_sats/eur nella semantica di valuta —
                    # sats = fisso, eur = ancorato, stesso toggle — ma
                    # SENZA il flag delle punto, ed e' la differenza da
                    # ricordare: la' vuoto e zero sono cose diverse
                    # (vuoto = vale la casa), qui «supplemento 0» e
                    # «nessun supplemento» sono la STESSA cosa, quindi
                    # lo zero basta a dirlo. Uno solo per annuncio: vale
                    # per la via casa e per la via punto, perche'
                    # dipende dall'OGGETTO e non dalla destinazione (un
                    # sacco di riso pesa uguale ovunque vada).
                    "spedizione_extra_sats INTEGER DEFAULT 0",
                    "spedizione_extra_eur REAL DEFAULT 0"):
        try:
            con.execute(f"ALTER TABLE annunci ADD COLUMN {colonna}")
        except sqlite3.OperationalError:
            pass
    # Migrazione categorie (lug 2026): il set nuovo rinomina tre voci
    # vecchie, le altre restano com'erano. COLLATE NOCASE raddrizza
    # anche le maiuscole storte dei vecchi import ('casa' minuscola,
    # vista nei dati veri). Idempotente: su un database gia' migrato
    # questi UPDATE non trovano piu' nulla.
    for vecchia, nuova in (
            ("Sport", "Sport e hobby"), ("Casa", "Casa e giardino"),
            ("Libri", "Libri e media"), ("Elettronica", "Elettronica"),
            ("Abbigliamento", "Abbigliamento"), ("Motori", "Motori"),
            ("Bambini", "Bambini"), ("Animali", "Animali"),
            ("Altro", "Altro")):
        con.execute(
            "UPDATE annunci SET categoria=? "
            "WHERE categoria=? COLLATE NOCASE AND categoria!=?",
            (nuova, vecchia, nuova))
    # Il catalogo largo (lug 2026) NON ha una sua migrazione, ed e' una
    # scelta: le nove voci di ieri restano tutte, con lo stesso nome —
    # le nuove si AGGIUNGONO accanto. Quindi non c'e' un solo annuncio
    # da spostare, e la migrazione piu' sicura e' quella che non esiste
    # (vedi CATEGORIE).
    # Indici per la vetrina a volume (lug 2026): con centinaia di
    # annunci le liste ordinate per data non devono piu' scandire
    # tutta la tabella. Coprono le tre strade calde: vetrina per
    # stato, filtro per categoria, negozio del venditore. Il DESC
    # combacia con l'ORDER BY delle query (e col cursore keyset).
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_vetrina "
                "ON annunci(stato, creato DESC, id DESC)")
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_categoria "
                "ON annunci(categoria, stato, creato DESC, id DESC)")
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_venditore "
                "ON annunci(venditore_id, stato, creato DESC, id DESC)")
    # L'ordinamento per prezzo della vetrina (lug 2026): stesso
    # keyset, chiavi (prezzo_sats, id). L'indice serve i due versi.
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_prezzo "
                "ON annunci(stato, prezzo_sats, id)")
    # Il filtro/ordinamento «⚡ In offerta» (lug 2026): keyset su
    # (lampo_scadenza, id) per le lampo vive.
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_lampo "
                "ON annunci(stato, lampo_scadenza, id)")
    # Il filtro/ordinamento «🔨 All'asta» (ago 2026): keyset su
    # (asta_scadenza, id) per le aste vive — chi scade prima in testa.
    con.execute("CREATE INDEX IF NOT EXISTS idx_annunci_asta "
                "ON annunci(stato, asta_scadenza, id)")
    # Migrazione per i rimborsi delle dispute
    try:
        con.execute("ALTER TABLE ordini ADD COLUMN invoice_rimborso TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    # Migrazione per il tie-break dei saldi d'asta (nata col cantiere:
    # copre i database creati tra il primo e il terzo passo)
    try:
        con.execute("ALTER TABLE puntate ADD COLUMN saldo_seq INTEGER DEFAULT 0")
    except sqlite3.OperationalError:
        pass
    # Migrazioni del proxy a budget depositato (ago 2026): il flag su
    # puntate e fatture, e l'ESPOSTO sulla fattura — la cronologia non
    # deve mai dire il totale dichiarato, che per un rilancio proxy e'
    # il massimo segreto.
    for tab_col in ("puntate ADD COLUMN proxy INTEGER DEFAULT 0",
                    "rilanci ADD COLUMN proxy INTEGER DEFAULT 0",
                    "rilanci ADD COLUMN esposto_sats INTEGER DEFAULT 0"):
        try:
            con.execute(f"ALTER TABLE {tab_col}")
        except sqlite3.OperationalError:
            pass
    # Backfill idempotente: le fatture saldate di ieri sono tutte
    # manuali, l'esposto E' il totale dichiarato. Le nuove lo scrivono
    # al saldo (mai 0: l'esposto parte dalla base, che e' > 0).
    con.execute("UPDATE rilanci SET esposto_sats=offerto_sats "
                "WHERE esposto_sats=0 AND stato='saldato'")
    # Migrazioni per spedizione, consegna e resi
    for colonna in ("corriere TEXT DEFAULT ''", "tracking TEXT DEFAULT ''",
                    "corriere_reso TEXT DEFAULT ''",
                    "tracking_reso TEXT DEFAULT ''",
                    # La correzione del tracciamento da parte di un
                    # MODERATORE (ago 2026, dal campo: chi compra la
                    # spedizione da un intermediario riceve il codice
                    # vero del corriere solo DOPO aver consegnato il
                    # pacco, e segna_spedito si scrive una volta sola).
                    # 0 = mai corretto. La traccia si vede nell'ordine
                    # da entrambe le parti: un tracciamento riscritto
                    # in silenzio varrebbe meno, non di piu'.
                    "tracking_corretto_il INTEGER DEFAULT 0",
                    "tracking_reso_corretto_il INTEGER DEFAULT 0",
                    "spedito_il INTEGER DEFAULT 0",
                    "consegnato INTEGER DEFAULT 0",
                    "sollecito_il INTEGER DEFAULT 0",
                    # il sollecito degli incassi fermi (lug 2026):
                    # quando e' partito l'ultimo e quanti ne sono
                    # gia' partiti (al tetto la palla va ai moderatori)
                    "sollecito_incasso_il INTEGER DEFAULT 0",
                    "solleciti_incasso INTEGER DEFAULT 0",
                    # disputata: 1 se sull'ordine e' stata aperta una
                    # disputa, anche se poi risolta (lo stato viene
                    # sovrascritto: senza questa traccia il distintivo
                    # Specchiato non saprebbe chi ha perso una disputa)
                    "disputata INTEGER DEFAULT 0",
                    # cambio_eur: EUR per BTC al momento della chiusura
                    # (released/refunded). 0 = sconosciuto: gli ordini
                    # storici restano cosi', e nel CSV il campo e' vuoto.
                    "cambio_eur REAL DEFAULT 0",
                    # cambio_ordine: EUR per BTC al momento della
                    # CREAZIONE della invoice — annunci in EUR, e dal
                    # lug 2026 anche i listini sats con la spedizione
                    # ancorata all'euro (e' il cambio che ha fissato i
                    # sats dell'ordine). 0 = nessuna conversione.
                    "cambio_ordine REAL DEFAULT 0",
                    # il conto scomposto (lug 2026, modello Vinted):
                    # prezzo_sats resta il TOTALE in cassaforte (invoice
                    # e rimborso non cambiano semantica), le due quote si
                    # FISSANO alla creazione — il config puo' cambiare,
                    # l'ordine no. L'articolo si deriva per sottrazione.
                    # consegna_scelta: spedizione | ritiro | digitale
                    # | '' (ordini storici e annunci senza modalita')
                    "consegna_scelta TEXT DEFAULT ''",
                    "spedizione_sats INTEGER DEFAULT 0",
                    "protezione_sats INTEGER DEFAULT 0",
                    # contenuto_digitale (lug 2026): il bene della
                    # consegna digitale (buono, codice, licenza),
                    # cifrato a riposo se la chiave e' in config
                    # (prefisso 'f:') o in chiaro ('plain:').
                    # MAI in /api/orders: si legge solo dall'endpoint
                    # /contenuto, che fa da ricevuta di lettura.
                    "contenuto_digitale TEXT DEFAULT ''",
                    # quantita (lug 2026): i pezzi dell'ordine.
                    # prezzo_sats resta il TOTALE in cassaforte (invoice,
                    # rimborso integrale e CSV non cambiano semantica);
                    # l'articolo unitario si deriva:
                    # (prezzo_sats - spedizione_sats - protezione_sats)
                    # / quantita, divisione esatta per costruzione.
                    "quantita INTEGER DEFAULT 1",
                    # invoice (ago 2026, cantiere della ripresa): la
                    # bolt11 dell'ordine, cosi' il compratore pentito
                    # che ritenta si vede RIPRESENTARE la sua fattura
                    # ancora viva invece di un «qualcun altro sta
                    # pagando» che parla di lui. '' = ordini storici:
                    # per loro la ripresa non scatta e si rinnova.
                    "invoice TEXT DEFAULT ''",
                    # il promemoria dei ritiri fermi (ago 2026):
                    # colonne SUE e non quelle del sollecito incassi —
                    # quelle vivono sullo stato 'confirmed', e un
                    # contatore ereditato salterebbe dritto al tetto
                    "sollecito_ritiro_il INTEGER DEFAULT 0",
                    "solleciti_ritiro INTEGER DEFAULT 0",
                    # il promemoria delle conferme ferme (ago 2026,
                    # disarmo dell'auto-sblocco): colonne SUE come per
                    # i ritiri — un contatore ereditato salterebbe
                    # dritto al tetto
                    "sollecito_conferma_il INTEGER DEFAULT 0",
                    "solleciti_conferma INTEGER DEFAULT 0",
                    # il promemoria al venditore fermo (ago 2026): le
                    # colonne dicono CHI aspettiamo — _conferma il
                    # compratore, _venditore il venditore. Non si
                    # riusano quelle di sopra: un ordine che prende i
                    # suoi squilli da 'locked' e poi viene spedito
                    # atterrerebbe nella popolazione 'shipped' gia' al
                    # tetto, e il compratore non sentirebbe mai il suo.
                    # (Da non confondere con `sollecito_il`, che e' il
                    # contrario: quando il venditore ha sollecitato il
                    # compratore col suo bottone.)
                    "sollecito_venditore_il INTEGER DEFAULT 0",
                    "solleciti_venditore INTEGER DEFAULT 0",
                    # il pagamento in uscita di cui non sappiamo l'esito
                    # (ago 2026, audit): '' = normale, 'incerto' =
                    # congelato, nessuna strada puo' ritentare finche'
                    # un moderatore non guarda; 'uscito' = ha guardato,
                    # i sats erano partiti, e il prossimo giro chiude
                    # l'ordine SENZA pagare di nuovo — cosi' il ramo
                    # riuscito di sempre si riusa dov'e', invece di
                    # riscriverlo qui in copia.
                    "payout_stato TEXT DEFAULT ''",
                    "payout_hash TEXT DEFAULT ''",
                    # CHI stava per essere pagato. Non si deduce dallo
                    # stato: un ordine in 'dispute' puo' essere sulla
                    # strada del venditore (disputa decisa a suo
                    # favore) o su quella del compratore (rimborso), e
                    # indovinare vorrebbe dire pagare la persona
                    # sbagliata quando il moderatore dice «e' uscito».
                    "payout_verso TEXT DEFAULT ''",
                    # punto_ritiro (ago 2026, pagina d'acquisto): il
                    # punto scelto dal compratore per la spedizione a
                    # un punto di ritiro (testo libero, ≤120) — MAI un
                    # valore nuovo di consegna_scelta, che resta
                    # 'spedizione': cosi' timer e solleciti restano
                    # veri per costruzione (il precedente e'
                    # anche_digitale). '' = casa/ritiro/digitale,
                    # storici e aste... OPPURE via punto col punto non
                    # ancora indicato: dal terzo giro chi lo dice e'
                    # la colonna qui sotto, non il testo.
                    "punto_ritiro TEXT DEFAULT ''",
                    # via_punto (ago 2026, terzo giro): 1 = il
                    # compratore ha scelto la STRADA del punto di
                    # ritiro. Serve perche' senza rete dichiarata il
                    # punto si indica DOPO il pagamento, dal campo
                    # dell'ordine — e «via punto, punto vuoto» deve
                    # esistere: e' lo stato che blocca segna_spedito
                    # (dove spedirebbe?).
                    "via_punto INTEGER DEFAULT 0",
                    # LO SCONTO CARRELLO (ago 2026), voce di TESTATA.
                    # ATTENZIONE, ed e' la riga da leggere prima di
                    # toccare qualunque strada del denaro: questa e'
                    # una colonna TESTIMONE, NON UN MOTORE. L'unico
                    # numero che comanda e' prezzo_sats, che nasce gia'
                    # scontato — l'incasso del venditore, il rimborso,
                    # gli XP e il CSV leggono LUI e solo lui. Chi qui
                    # leggesse «il venditore deve incassare il pieno» e
                    # ne facesse un netto_venditore(prezzo + sconto)
                    # farebbe uscire dall'escrow DI ALTRI ORDINI la
                    # differenza, e la cintura di paga_venditore non lo
                    # vedrebbe: per lei dovuto e bolt11 combacerebbero.
                    # Serve al compratore, che nell'ordine vede le
                    # righe LORDE e senza questa cifra farebbe la somma
                    # a mano concludendo di essere stato derubato.
                    "sconto_sats INTEGER DEFAULT 0",
                    # la fotografia della REGOLA, non della cifra: il
                    # venditore puo' cambiarla il minuto dopo e la
                    # ricevuta deve continuare a dire «−10%» per sempre
                    # (dedurla da sconto/articolo direbbe 9,99%). Si
                    # scrive SOLO se lo sconto e' scattato davvero.
                    "sconto_percento INTEGER DEFAULT 0",
                    # LA SPEDIZIONE GRATIS SOPRA SOGLIA (ago 2026): la
                    # tariffa che il compratore NON ha pagato. Vale
                    # parola per parola l'avvertimento qui sopra —
                    # TESTIMONE, NON MOTORE: prezzo_sats nasce gia'
                    # senza la spedizione, e un netto_venditore(prezzo +
                    # sped_gratis_sats) svuoterebbe l'escrow di altri
                    # ordini senza che nessuna cintura se ne accorga.
                    # A differenza dello sconto qui l'aritmetica
                    # quadrerebbe anche senza (spedizione_sats=0 e' gia'
                    # tutta la verita' del conto): serve a RACCONTARE —
                    # chi confronta la scheda e la ricevuta deve poter
                    # vedere dove e' finita la tariffa — e a dare al
                    # libro mastro due invarianti veri, che
                    # spedizione_sats da solo non potrebbe avere.
                    # Si scrive SOLO quando la promessa e' scattata su
                    # una via che spediva: 0 ovunque altrove.
                    "sped_gratis_sats INTEGER DEFAULT 0",
                    # LA BUSTA DI CONSEGNA (ago 2026): sugli ordini con
                    # la via del punto di ritiro il venditore deposita
                    # il nome del destinatario e il codice di ritiro —
                    # cifrati col TRASPORTO dei contenuti digitali, MAI
                    # la sua semantica: aprire la busta non e' una
                    # ricevuta, `consegnato` e lo stato non si toccano
                    # (consegna_scelta resta 'spedizione', quindi le
                    # finestre corte del digitale non vedono mai questi
                    # ordini). L'admin non la legge MAI: in disputa
                    # vede solo SE e QUANDO (busta_il e le correzioni).
                    "busta_nome TEXT DEFAULT ''",
                    "busta_codice TEXT DEFAULT ''",
                    # il PRIMO deposito (0 = mai): e' il flag E il
                    # «quando» — le correzioni non lo riscrivono
                    "busta_il INTEGER DEFAULT 0",
                    # le correzioni si vedono (decisione di Andrea): la
                    # busta resta correggibile fino a 'dispute' — il
                    # moderatore non puo' correggerla perche' non la
                    # legge — e deve sapere che e' cambiata e quando,
                    # magari proprio dopo l'apertura della disputa.
                    # Fatti, mai il contenuto.
                    "busta_corretta_il INTEGER DEFAULT 0",
                    "busta_correzioni INTEGER DEFAULT 0",
                    # il promemoria al venditore che non deposita la
                    # busta: colonne SUE, come per le sorelle — un
                    # contatore ereditato salterebbe al tetto
                    "sollecito_busta_il INTEGER DEFAULT 0",
                    "solleciti_busta INTEGER DEFAULT 0",
                    # IL NASCONDERE DEGLI AFFARI CONCLUSI (ago 2026):
                    # NASCONDERE, mai cancellare — la riga resta nel
                    # database, perche' libro mastro, feedback, export
                    # e registro di moderazione ci poggiano sopra.
                    # DUE colonne e non una (il patto delle sorelle
                    # sollecito_*): il compratore nasconde il SUO,
                    # il venditore il suo — non si nasconde a vicenda
                    # un ordine. Il gate ammette SOLO released e
                    # refunded, gli unici stati ASSORBENTI: quindi
                    # «un nascosto che torna a muoversi» non esiste
                    # per costruzione (vedi nascondi_ordine).
                    "nascosto_compratore INTEGER DEFAULT 0",
                    "nascosto_venditore INTEGER DEFAULT 0"):
        try:
            con.execute(f"ALTER TABLE ordini ADD COLUMN {colonna}")
        except sqlite3.OperationalError:
            pass
    # Le stesse sul registro dei rimborsi d'asta: il moderatore deve
    # avere lo stesso dato ovunque, e «Da riscuotere» esce dallo
    # stesso tubo (paga_venditore) degli incassi. Qui `payout_verso`
    # e' sempre lo stesso — c'e' una strada sola — ma si tiene per
    # avere una colonna in meno da ricordare a chi legge il codice.
    for colonna in ("payout_stato TEXT DEFAULT ''",
                    "payout_hash TEXT DEFAULT ''",
                    "payout_verso TEXT DEFAULT ''"):
        try:
            con.execute(f"ALTER TABLE rimborsi_asta ADD COLUMN {colonna}")
        except sqlite3.OperationalError:
            pass
    # Backfill di disputata: questi stati esistono SOLO a valle di una
    # disputa, quindi gli ordini storici che ci si trovano sono marcabili
    # a colpo sicuro. I released passati da una disputa prima della
    # colonna sono irrecuperabili: si perdona, a favore dell'utente.
    con.execute("UPDATE ordini SET disputata=1 WHERE disputata=0 AND stato "
                "IN ('dispute','return_pending','return_shipped',"
                "'refund','refunded')")
    # Riallineamento quantita (lug 2026, idempotente a ogni avvio):
    # l'invariante venduto <=> quantita=0 vale anche sul pregresso
    # (i venduti di ieri sono nati col DEFAULT 1) e ripara gli
    # importati spenti come 'venduto' dall'import, che non conosce
    # la colonna.
    con.execute("UPDATE annunci SET quantita=0 "
                "WHERE stato='venduto' AND quantita!=0")
    # La prenotazione dello stock (lug 2026) conta gli ordini 'creato'
    # per annuncio a ogni acquisto: e' la prima query calda su ordini
    # (finora la tabella viveva senza indici).
    con.execute("CREATE INDEX IF NOT EXISTS idx_ordini_annuncio "
                "ON ordini(annuncio_id, stato)")
    # Distintivi: passata silenziosa su TUTTI gli utenti, a ogni avvio.
    # E' idempotente (INSERT OR IGNORE) e auto-riparante: fusioni,
    # rimozioni e criteri nuovi si sistemano al riavvio successivo.
    # Le notifiche 🏅 spettano solo ai ganci dal vivo, mai a questa.
    for r in con.execute("SELECT tg_id FROM utenti").fetchall():
        controlla_distintivi(con, r["tg_id"])
    con.commit()
    con.close()


