@app.get("/api/admin/leve")
def leve_admin(x_tg_init_data: str = Header(""),
               barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: con quali leve sta girando il server, adesso."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    return {"gruppi": _leve_stato()}


@app.post("/api/admin/utenti/{tg_id}/messaggio")
async def messaggio_utente_admin(tg_id: int, req: Request,
                                 x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: un messaggio a UN utente, dal bot. Nato da un caso
    vero (ago 2026): una venditrice senza username Telegram ne' npub
    scrive «contattami per i colori» — e nessuno puo' scriverle,
    moderatori compresi. Passa da notifica(), che rispetta la
    preferenza di canale e copre anche i nativi Nostr col DM cifrato.
    E' A SENSO UNICO per costruzione — il bot non ci inoltra le
    risposte — e lo dicono sia l'interfaccia del moderatore sia la
    coda del messaggio, con la strada giusta per risponderci (il
    canale del rodaggio, quello che c'e' gia': nessun secondo
    contatto da tenere aggiornato). Ogni invio resta nel registro
    moderazione con chi l'ha mandato."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    d = await leggi_json(req)
    testo = str(d.get("testo") or "").strip()
    if not testo:
        raise HTTPException(400, "Il messaggio è vuoto")
    if len(testo) > 1500:
        raise HTTPException(400, "Massimo 1500 caratteri")
    con = db()
    u = con.execute("SELECT nome FROM utenti WHERE tg_id=?",
                    (tg_id,)).fetchone()
    con.close()
    if not u:
        raise HTTPException(404, "Utente non trovato")
    # Le notifiche parlano HTML: il testo del moderatore si scappa, o
    # un «<» spegnerebbe il messaggio in silenzio (la lezione dei
    # promemoria). La coda dice al destinatario COME risponderci:
    # scrivere al bot non serve, quella strada non torna indietro.
    coda = ("\n\n<i>Questo messaggio è a senso unico: se rispondi al "
            "bot, la risposta non ci arriva.")
    if (BANNER_TEST_LINK or "").startswith("http"):
        coda += f" Per scriverci: {BANNER_TEST_LINK}"
    coda += "</i>"
    await notifica(tg_id,
                   "🛡 <b>Messaggio dai moderatori di Barattolo</b>\n\n"
                   + html.escape(testo) + coda)
    registra_moderazione("admin", "messaggio", testo, "", 0, tg_id,
                         user["id"])
    return {"ok": True}


# ---------------------- API: RICERCA AI -----------------------------

# Con centinaia di annunci il catalogo intero non entra piu' nel
# prompt: all'AI arriva una SHORTLIST — prima i match letterali sulle
# parole della richiesta, poi i piu' recenti a riempire. Compromesso
# dichiarato: un annuncio che combacia SOLO per sinonimo e non e' tra
# i piu' freschi puo' sfuggire. L'AI continua a fare la parte fine
# (sinonimi, prezzo, zona) dentro la rosa.
TETTO_CATALOGO_AI = 300

# Il freno della ricerca AI (ago 2026, audit). Era l'unica rotta dove
# UNA richiesta di un utente qualunque = UNA chiamata ad Anthropic, e
# con un prompt di dimensione massima FISSA: il catalogo si riempie
# fino a 300 annunci anche quando la domanda non trova niente, quindi
# ogni ricerca costa uguale, tanto. L'unico recinto era
# l'autenticazione — che lo passa chiunque abbia un account.
# Pattern di IMPORT_QUOTA, con l'ora al posto del giorno: dizionario
# in memoria, si azzera al riavvio e va bene cosi' (le raffiche vere
# durano meno di un riavvio).
RICERCA_QUOTA: dict[int, list] = {}     # tg_id -> [ora, ricerche]


def _ricerca_ai_concessa(tg_id: int) -> bool:
    """Consuma un gettone della quota oraria. False = si risponde col
    filtro per parole, che non costa niente e qualche risultato lo
    da' — meglio di un vicolo cieco."""
    if not TETTO_RICERCHE_AI_ORA:       # 0 = nessun freno
        return True
    ora = time.strftime("%Y-%m-%d %H")
    voce = RICERCA_QUOTA.get(tg_id)
    if not voce or voce[0] != ora:
        voce = [ora, 0]
        RICERCA_QUOTA[tg_id] = voce
    if voce[1] >= TETTO_RICERCHE_AI_ORA:
        return False
    voce[1] += 1
    return True


@app.get("/api/search")
def cerca(q: str, busta: int = 0, x_tg_init_data: str = Header(""),
                  barattolo_sessione: str = Cookie("")):
    """Ricerca in linguaggio naturale: l'AI legge la richiesta
    ("tastiera sotto i 100k vicino Milano") e seleziona gli annunci.

    `busta=1` avvolge la risposta in {annunci, ai} per dire QUANDO
    l'AI non e' stata usata (quota finita, o chiamata fallita): senza
    il parametro resta l'array di sempre, e un client vecchio in cache
    vede i risultati come li ha sempre visti — il patto della
    paginazione."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    base = ("SELECT a.*, u.nome AS venditore, u.username AS venditore_username, "
            "u.npub AS venditore_npub, "
            "u.npub_verificata AS venditore_npub_verificata, "
            "u.negozio AS venditore_negozio, u.titolo AS venditore_titolo, "
            "(CASE WHEN u.avatar_scelta='nessuna' THEN '' ELSE u.avatar END) "
            "AS venditore_avatar, "
            "(SELECT GROUP_CONCAT(b.badge_id) FROM badge_utente b "
            " WHERE b.tg_id=a.venditore_id) AS venditore_distintivi, "
            "u.rating FROM annunci a "
            "JOIN utenti u ON u.tg_id=a.venditore_id WHERE a.stato='attivo'")
    con = db()
    # Le parole "sostanziose" della richiesta (>=3 lettere, max 6)
    parole = [p for p in re.findall(r"\w+", q.lower()) if len(p) >= 3][:6]
    annunci = []
    if parole:
        cond = " OR ".join("(a.titolo LIKE ? OR a.descrizione LIKE ? "
                           "OR a.categoria LIKE ? OR a.zona LIKE ?)"
                           for _ in parole)
        par = [f"%{p}%" for p in parole for _ in range(4)]
        annunci = [dict(r) for r in con.execute(
            base + f" AND ({cond}) ORDER BY a.creato DESC LIMIT ?",
            par + [TETTO_CATALOGO_AI])]
    if len(annunci) < TETTO_CATALOGO_AI:
        # Si riempie la rosa coi piu' freschi: l'AI vede sempre un
        # catalogo pieno e puo' pescare i sinonimi che il LIKE non sa.
        ids = tuple(a["id"] for a in annunci) or (0,)
        annunci += [dict(r) for r in con.execute(
            base + f" AND a.id NOT IN ({','.join('?' * len(ids))}) "
            "ORDER BY a.creato DESC LIMIT ?",
            list(ids) + [TETTO_CATALOGO_AI - len(annunci)])]
    annunci = arricchisci_righe_vetrina(annunci)
    con.close()
    def risposta(righe, ai_usata=True):
        return {"annunci": righe, "ai": ai_usata} if busta else righe

    def filtro_semplice():
        ql = q.lower()
        return [a for a in annunci
                if ql in (a["titolo"] + a["descrizione"]).lower()]

    if not annunci:
        return risposta([])
    # Il freno PRIMA di costruire il catalogo: a quota finita non si
    # spende nemmeno il tempo di impaginare 300 annunci.
    if not _ricerca_ai_concessa(user["id"]):
        return risposta(filtro_semplice(), False)

    catalogo = "\n".join(
        f"ID {a['id']}: {a['titolo']} | {a['categoria']} | "
        f"{a['prezzo_sats']} sats"
        + (f" ({a['prezzo_eur']:.2f} EUR)" if a["valuta"] == "eur" else "")
        + (f" | {CONDIZIONI[condizione_da_mostrare(a)]}"
           if condizione_da_mostrare(a) in CONDIZIONI else "")
        + (f" | ne restano {a['quantita']}"
           if (a.get("quantita") or 1) > 1 else "")
        + f" | {a['zona']} | {a['descrizione'][:120]}"
        for a in annunci)
    try:
        r = ai.messages.create(
            model=MODELLO_RICERCA, max_tokens=200, timeout=20,
            system=("Sei il motore di ricerca di un mercatino. Data la richiesta "
                    "dell'utente e il catalogo, rispondi SOLO con un array JSON "
                    "degli ID pertinenti, dal piu' rilevante. Capisci sinonimi "
                    "(bici=mtb=bicicletta) e vincoli di prezzo/zona. "
                    "Le categorie del catalogo sono: "
                    + ", ".join(CATEGORIE) + ". Se la richiesta indica una "
                    "categoria (es. 'giochi per bambini'), privilegiala. "
                    "Nessun risultato pertinente = []"),
            messages=[{"role": "user",
                       "content": f"RICHIESTA: {q}\n\nCATALOGO:\n{catalogo}"}])
        ids = json.loads("".join(b.text for b in r.content if b.type == "text")
                         .replace("```json", "").replace("```", "").strip())
        per_id = {a["id"]: a for a in annunci}
        return risposta([per_id[i] for i in ids if i in per_id])
    except Exception as e:
        print(f"Ricerca AI fallita, uso filtro semplice: {e}")
        return risposta(filtro_semplice(), False)


# ------------------------- API: OFFERTE -----------------------------
# La contrattazione sul prezzo (lug 2026, modello Vinted): proposta ->
# risposta -> acquisto alla cifra pattuita. NON e' una chat: e' una
# macchina a stati con al massimo UNA controproposta del venditore.
# L'annuncio non si blocca mai durante la trattativa: vince chi paga
# per primo, e le offerte rimaste vive decadono con garbo. L'accordo
# riguarda il SOLO articolo: spedizione e protezione si sommano sopra
# al momento dell'acquisto, come per ogni altro ordine.

STATI_OFFERTA_VIVI = ("proposta", "controproposta", "accettata")


def _importo_accordo(off) -> tuple[int, float]:
    """La cifra pattuita: la controproposta se c'e' (solo il compratore
    puo' accettarla, quindi se c'e' l'accordo e' quello), altrimenti la
    proposta. In (sats, eur): uno dei due e' sempre 0, come in colonna."""
    if off["contro_sats"] > 0 or off["contro_eur"] > 0:
        return off["contro_sats"], off["contro_eur"]
    return off["importo_sats"], off["importo_eur"]


def _cifra_offerta(valuta: str, sats: int, eur: float) -> str:
    """«80.000 sats» oppure «15.50 €»: la valuta del listino."""
    return f"{eur:.2f} €" if valuta == "eur" else f"{_fmt_sats(sats)} sats"


# ------------------ IL CONTO D'ACQUISTO: matematica pura -------------
# (ago 2026, pagina d'acquisto). Il giudice UNICO del conto: lo usano
# compra(), _compra_set() e il preventivo della pagina d'acquisto — se
# il preventivo facesse i conti per conto suo, prima o poi direbbe una
# cifra diversa dalla invoice. La SOTTRAZIONE dello sconto carrello sta
# dentro _conto_ordine e in nessun altro posto (chi legge il conto usa
# `netto`); la DECISIONE — scatta o no — sta in _sconto_pacco, che il
# ramo mono non chiama mai, e dal cantiere del CRITERIO sta li' anche
# per il gemello in euro, che non decide piu' da solo: a valore la
# porta si apre guardando i SATS, che l'euro non ha.
# Funzioni PURE come quelle dell'asta:
# niente config, niente database, niente rete — le percentuali arrivano
# per parametro e il cambio dal chiamante, che decide anche cosa fare
# quando manca (503 in compra, strada spenta con motivo nel
# preventivo). Sono il «modulo» che prove.py estrae con pezzo() e
# tortura in CI: chi le rifattorizza le tenga autosufficienti.

def _unitario_effettivo(a, off, adesso: int, cambio: float) -> int:
    """L'unitario in sats di UN annuncio: listino, accordo accettato
    (_importo_accordo) e lampo viva col MIN — chi paga paga sempre il
    meglio dei due, mai una lampo che peggiora l'accordo. Sul listino
    EUR converte al cambio dato (che il chiamante garantisce >0 quando
    serve), max(1, round(...)): si arrotonda l'UNITARIO prima di
    moltiplicare, cosi' la divisione a ritroso di chi legge l'ordine
    e' esatta."""
    p_sats, p_eur = a["prezzo_sats"], a["prezzo_eur"]
    if off:
        p_sats, p_eur = _importo_accordo(off)
    if a["lampo_percento"] > 0 and a["lampo_scadenza"] > adesso:
        l_sats, l_eur = _prezzo_lampo(a, a["lampo_percento"])
        if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
            p_eur = min(p_eur, l_eur) if p_eur > 0 else l_eur
        else:
            p_sats = min(p_sats, l_sats)
    if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
        return max(1, round(p_eur / cambio * 100_000_000))
    return p_sats


def _eur_effettivo(a, off, adesso: int) -> float:
    """L'euro NATIVO effettivo dell'articolo (ago 2026, il giudice del
    «≈»): per un listino EUR e' la cifra su cui il ≈ NON va — la
    valuta in cui il prezzo e' nato — col MIN lampo/accordo calcolato
    sull'euro, specchio di _unitario_effettivo. Listino sats = 0.0
    (li' il nativo sono i sats, e l'euro e' sempre una conversione)."""
    if a["valuta"] != "eur" or a["prezzo_eur"] <= 0:
        return 0.0
    p_eur = a["prezzo_eur"]
    if off:
        p_eur = _importo_accordo(off)[1] or p_eur
    if a["lampo_percento"] > 0 and a["lampo_scadenza"] > adesso:
        l_eur = _prezzo_lampo(a, a["lampo_percento"])[1]
        p_eur = min(p_eur, l_eur) if p_eur > 0 else l_eur
    return round(p_eur, 2)


def _tariffa_dichiarata(a, via: str) -> tuple:
    """(sats, eur) della tariffa di spedizione per la via chiesta:
    'punto' con la dichiarazione accesa usa le colonne punto — anche
    (0, 0.0): gratis dichiarato e' gratis — altrimenti SEMPRE la
    tariffa casa. E' la retrocompat decisa da Andrea: un costo solo
    dichiarato vale per entrambe le strade finche' il venditore non
    rifinisce il secondo."""
    if via == "punto" and a["spedizione_punto_dichiarata"]:
        return a["spedizione_punto_sats"], a["spedizione_punto_eur"]
    return a["spedizione_sats"], a["spedizione_eur"]


def _sped_in_sats(sped_sats: int, sped_eur: float, cambio: float):
    """La tariffa in sats: l'euro ancorato si converte al cambio dato
    — None se il cambio manca, e decide il chiamante (503 in compra,
    strada spenta con motivo nel preventivo) — altrimenti valgono i
    sats fissi."""
    if sped_eur > 0:
        if cambio <= 0:
            return None
        return round(sped_eur / cambio * 100_000_000)
    return sped_sats


def _sped_pacco(righe: list, via: str, cambio: float) -> dict:
    """LA SPEDIZIONE DI UN ORDINE INTERO, in una riga sola:
    **la spedizione piu' cara fa da base, e ogni altro pezzo aggiunge
    il suo supplemento.**

        totale = max(base_i) + (somma qta_i x supp_i) - supp_vincitore

    `righe` = [(annuncio, quantita)] — il mono e' [(a, quanti)], e non
    e' un caso particolare da scrivere a parte: base + (q-1) x supp
    esce da sola. Fino ad ago 2026 il MAX era scritto a mano in DUE
    posti (_compra_set e _strade_preventivo) piu' una terza forma nel
    mono di compra(): tenerne tre in pari col supplemento sarebbe
    stato il modo di farli divergere, quindi qui ce n'e' UNO.

    IL PAREGGIO nel MAX si rompe su (base, supp), cioe' a parita' di
    base si assorbe il supplemento piu' GRANDE — a favore di chi
    compra. *Quale* riga vinca dipende dall'ordine della lista, il
    TOTALE no: e' quello che conta, e va detto perche' qualcuno un
    giorno vorra' aggiungere un terzo criterio «per sicurezza».

    IL MAX NON E' IL MINIMO, ED E' GIUSTO COSI'. A(base 10, supp 0) +
    B(base 9, supp 5) fa 15, non 9: partire da B darebbe meno di
    quanto costa spedire A da solo, che e' assurdo. Il primo che lo
    nota lo chiamera' bug — non lo e'.

    DUE PROPRIETA' che le prove torturano, perche' sono il patto col
    mondo di ieri: a supplementi tutti a ZERO il risultato e' identico
    al MAX di sempre, e il totale non scende MAI sotto quel MAX
    (somma qta x supp >= supp_vincitore, perche' qta >= 1). Nessun
    venditore incassa meno di prima.

    L'EURO NATIVO segue la stessa strada dei sats, e la condizione e'
    «contribuisce in sats», non «eur == 0»: una tariffa che vale ZERO
    non contribuisce e NON deve azzerare il nativo (zero e' zero in
    tutte le valute), mentre una con sats>0 nata in sats si'. Scritta
    nell'altro modo — quello che viene in mente — un supplemento a
    zero farebbe comparire il ≈ su tutti i carrelli.

    L'ARROTONDAMENTO converte PRIMA e moltiplica DOPO, il patto di
    _unitario_effettivo: qui vale doppio, perche' questo numero
    finisce dentro ordini.spedizione_sats e _righe_ordine lo sottrae.

    sats None = una tariffa e' ancorata all'euro e il cambio manca:
    decide il chiamante (503 in compra dopo aver richiesto il cambio,
    strada spenta col motivo nel preventivo)."""
    fuori = {"sats": 0, "eur": 0.0, "stima": False,
             "supplemento": 0, "pezzi": 0}
    if via not in ("casa", "punto"):
        return fuori           # ritiro e codice online non spediscono
    base, base_eur, supp_vinc, supp_vinc_eur = 0, 0.0, 0, 0.0
    extra, extra_eur, stima, pezzi = 0, 0.0, False, 0
    sats_puri = False          # una tariffa che contribuisce nata in sats
    for a, qta in righe:
        b_sats, b_eur = _tariffa_dichiarata(a, via)
        b = _sped_in_sats(b_sats, b_eur, cambio)
        s = _sped_in_sats(a["spedizione_extra_sats"],
                          a["spedizione_extra_eur"], cambio)
        s_eur = a["spedizione_extra_eur"]
        if b is None or s is None:
            return {**fuori, "sats": None}
        pezzi += qta
        extra += s * qta
        extra_eur += round(s_eur * qta, 2)
        if s > 0:
            stima, sats_puri = (stima or s_eur > 0), (sats_puri or s_eur <= 0)
        if (b, s) > (base, supp_vinc):
            base, base_eur, supp_vinc, supp_vinc_eur = b, b_eur, s, s_eur
    if base > 0:
        stima, sats_puri = (stima or base_eur > 0), (sats_puri or base_eur <= 0)
    return {"sats": base + extra - supp_vinc,
            "eur": (0.0 if sats_puri
                    else round(base_eur + extra_eur - supp_vinc_eur, 2)),
            "stima": stima, "pezzi": pezzi,
            "supplemento": extra - supp_vinc}


def _eur_interi(sats: int, cambio: float):
    """Gli euro INTERI di una cifra in sats — la MISURA delle due
    promesse di negozio (lo sconto carrello a valore e la spedizione
    gratis sopra soglia), da quando le loro soglie sono in euro.
    Lo specchio di _sped_in_sats, e ne copia la forma apposta: None
    quando il cambio non c'e', e decide il chiamante. Qui pero' il
    chiamante non alza nessun 503 — una promessa che non si sa valutare
    semplicemente non scatta, e l'ordine parte a prezzo pieno.
    PER DIFETTO, ed e' il verso giusto in cui sbagliare: 49,99 e' sotto
    una soglia da 50, e nessuna promessa deve scattare per un
    arrotondamento. Al filo esatto scatta, come _asta_viva e in_ferie.
    SI CHIAMA UNA VOLTA SOLA PER CONTO e il numero va a tutte e due le
    promesse: e' cosi' che «LE DUE PROMESSE GUARDANO LO STESSO NUMERO»
    smette di essere un patto da ricordare e diventa una proprieta'
    della struttura — con due chiamate, un giorno divergerebbero."""
    if cambio <= 0:
        return None
    return int(sats * cambio // 100_000_000)


def _sped_gratis(articolo_eur, soglia: int) -> bool:
    """LA SPEDIZIONE GRATIS SOPRA SOGLIA (ago 2026): la seconda
    promessa di negozio — «da N € di articoli la spedizione la offro
    io» — che azzera la tariffa della via scelta. Ritiro e digitale
    sono gia' a zero e non passano di qui.
    RICEVE GLI EURO, NON IL CAMBIO, ed e' cosi' che resta pura pur
    giudicando una soglia in euro: la conversione la fa _eur_interi nel
    chiamante, che il cambio ce l'ha gia'. Il None arriva fin qui e si
    ferma qui — a cambio muto la promessa NON scatta, fail-closed dentro
    il giudice come importo_invoice, invece che con un «if» da ricordare
    nei quattro percorsi del conto.
    LA MISURA E' LA STESSA DELLO SCONTO (decisione di Andrea): il LORDO
    del conto, cioe' l'articolo dopo lampo e accordo
    (_unitario_effettivo li ha gia' applicati) e PRIMA dello sconto
    carrello. Cosi' le due promesse sono INDIPENDENTI — nessuna puo'
    spegnere l'altra facendo scendere l'altra sotto la sua soglia — e
    si spiegano a chi compra in una riga sola. Conseguenza voluta,
    gemella di quella dello sconto: una lampo generosa puo' far
    scendere SOTTO soglia un carrello che a listino ci arrivava. E'
    giusto — la soglia guarda quel che si paga davvero per la merce —
    ed e' scritto nel cassetto del venditore.
    Al filo esatto la spedizione E' gratis, come _asta_viva e in_ferie:
    chi promette «da 50 €» intende «50 € compresi».
    A DIFFERENZA DELLO SCONTO VALE ANCHE SUL MONO, e non e' una scelta
    di prodotto ma una proprieta' della forma: lo sconto sottrae dal
    TOTALE senza toccare le colonne che _righe_ordine sottrae — ed e'
    per quello che il mono non sconta — mentre qui si azzera una
    TARIFFA, cioe' si scrive spedizione_sats=0, che e' lo stato di ogni
    annuncio con spedizione gratuita dichiarata. La divisione a ritroso
    dell'unitario resta esatta senza un ramo nuovo."""
    return soglia > 0 and articolo_eur is not None and articolo_eur >= soglia


def _sconto_pacco(articolo: int, articolo_eur, pezzi: int, criterio: str,
                  soglia: int, percento: int) -> int:
    """LO SCONTO CARRELLO in sats (ago 2026): la regola del negozio —
    «da N articoli, −X%» oppure «da N € di articoli, −X%» — applicata
    alla somma degli articoli. Zero quando la regola e' spenta, quando
    la soglia non e' seria o quando il carrello non la raggiunge:
    nessun ramo puo' far scattare uno sconto che il venditore non ha
    promesso, nemmeno con una riga di database scritta a mano.
    DUE UNITA' NELLA STESSA FIRMA, e la distinzione e' tutta qui:
    `articolo` sono i SATS e sono cio' che si SCONTA — la cifra che
    finisce nella invoice —, `articolo_eur` sono gli euro interi di
    _eur_interi e servono solo a MISURARE la soglia. Chi le scambia
    sconta in euro un conto che si paga in sats.
    IL CRITERIO lo sceglie il venditore, e qui cambia solo COSA si
    misura: i PEZZI (tre cose nella scatola sono tre cose, ed e' quello
    che legge chi guarda il carrello) o il VALORE degli articoli in
    euro — che e' l'unica cosa che serviva al venditore di computer per
    dare lo sconto da due pezzi e a quello di cianfrusaglie per
    chiederne venti, senza due regole diverse.
    A cambio muto `articolo_eur` arriva None e la promessa NON scatta,
    fail-closed dentro il giudice: e' un posto solo dove sbagliare
    invece di quattro «if» da ricordare nei percorsi del conto. Il
    criterio a PEZZI non guarda l'euro e continua a scattare: non ha
    mai avuto bisogno del cambio e non deve cominciare adesso.
    Il minimo e' diverso per i due, e per la stessa ragione: «da 1
    articolo» non e' uno sconto carrello ma un ribasso di listino, e
    quello si fa sul prezzo; a valore invece anche una soglia bassa e'
    una promessa legittima, e a impedire il ribasso travestito c'e' gia'
    la cintura di _regola_sconto (SCONTO_PACCO_MIN_VALORE_EUR).
    Un criterio che non conosciamo NON ripiega sui pezzi: applicherebbe
    una soglia in pezzi che il venditore non ha promesso in pezzi — e
    una colonna scritta a mano, o il rollback da un criterio futuro,
    farebbero scontare a caso. Si tace, e la promessa non scatta:
    fail-closed come `importo_invoice`.
    LA MISURA E' IL LORDO DEL CONTO, cioe' l'articolo DOPO lampo e
    accordo (_unitario_effettivo li ha gia' applicati) e PRIMA dello
    sconto — o si morderebbe la coda. Conseguenza voluta, da sapere
    perche' sembra un bug quando un venditore la nota: una lampo al
    −50% puo' far scendere SOTTO soglia un carrello che a listino ci
    arrivava. E' giusto cosi' — la soglia guarda quel che si paga
    davvero per la merce, non un listino che in quel momento non e' il
    prezzo di nessuno — e scontare ancora un carrello che la soglia non
    la raggiunge piu' sarebbe la vera incoerenza.
    L'arrotondamento e' quello di _prezzo_lampo: il NETTO col floor e
    lo sconto per DIFFERENZA — cosi' `articolo - sconto` E' il netto
    per costruzione (mai un sat di scarto fra la riga mostrata e il
    totale) e il sat di dubbio resta a CHI PAGA, come la protezione col
    suo floor. Il max(1) e' la cintura della lampo: mai gratis.
    SI CUMULA con lampo e accordo accettato, deliberatamente: e' una
    promessa di NEGOZIO scritta in vetrina, e un pezzo che non la
    mantenesse non avrebbe un posto onesto dove dirlo — servirebbe una
    riga «questo no» per riga. Il guardrail e' il tetto della leva.
    NON la chiama MAI il ramo mono: la decisione vive qui fuori dal
    conto apposta, cosi' e' una garanzia strutturale e non un «if» da
    ricordare (vedi _righe_ordine)."""
    if criterio == "valore":
        if articolo_eur is None:
            return 0    # cambio muto: una promessa in euro non si valuta
        misura, minimo = articolo_eur, 1
    elif criterio == "pezzi":
        misura, minimo = pezzi, 2
    else:
        return 0        # criterio che nessun ramo sa applicare: si tace
    if percento <= 0 or soglia < minimo or misura < soglia or articolo <= 1:
        return 0
    return articolo - max(1, articolo * (100 - min(percento, 100)) // 100)


def _sconto_pacco_eur(articolo_eur: float, percento: int) -> float:
    """Lo sconto carrello in EURO NATIVO, gemello del precedente:
    stesso arrotondamento per differenza. Si calcola in EURO e non
    convertendo i sats — un carrello nato in euro con la protezione a
    zero ha oggi un totale ESATTO, e uno sconto non deve poter
    peggiorare la QUALITA' di un numero: chi mostra il ≈ dove non serve,
    prima o poi lo toglie dove serviva. 0.0 quando l'euro nativo non
    c'e' (listino in sats o carrello misto): li' il ≈ e' suo di diritto.
    LA DECISIONE NON ABITA QUI (ago 2026, col criterio): il chiamante la
    aziona solo quando il gemello in sats ha scattato — `... if sconto
    else 0.0`. Prima la condizione era ripetuta identica nei due, e col
    criterio quella copia sarebbe diventata il posto esatto in cui i due
    possono divergere; adesso di misure da confrontare ce n'e' UNA, in
    _sconto_pacco. La cintura di _strade_preventivo (`sconto == 0 or
    sconto_eur > 0`) resta al suo posto e ne esce rafforzata."""
    if percento <= 0 or articolo_eur <= 0:
        return 0.0
    netto = max(0.01, round(articolo_eur * (100 - min(percento, 100)) / 100, 2))
    return round(articolo_eur - netto, 2)


def _conto_ordine(articolo: int, sped: int, prot_percento: int,
                  comm_percento: int, sconto: int = 0) -> dict:
    """Le righe del conto: protezione col floor (//100) sul solo
    articolo, mai un sat piu' del promesso. La commissione e' una riga
    INFORMATIVA e NON entra nel totale del compratore: oggi e' sospesa
    (leva a 0, la riga dice «in promo»), e anche accesa resta
    sottrattiva sull'incasso del venditore — il totale della invoice
    e' netto + spedizione + protezione, identico a compra().
    LO SCONTO CARRELLO (ago 2026) e' una voce di TESTATA che entra qui
    e SOLO qui: chi legge il conto usa `netto`, e nessun chiamante
    sottrae per conto suo — due sottrazioni sono uno sconto doppio, e
    la invoice nasce di la'. Protezione e commissione si calcolano sul
    NETTO: la percentuale sta sul prezzo che si paga davvero, ed e' la
    stessa strada che gia' seguono lampo e accordo, che abbassano
    l'articolo prima di arrivare qui. Il default a 0 tiene il ramo mono
    identico a ieri, byte per byte."""
    netto = max(0, articolo - max(0, sconto))
    prot = netto * prot_percento // 100
    return {"articolo": articolo, "sconto": sconto, "netto": netto,
            "spedizione": sped, "protezione": prot,
            "commissione": netto * comm_percento // 100,
            "totale": netto + sped + prot}


# Fuori dal blocco puro perche' guarda le LEVE: la regola dello sconto
# carrello, normalizzata.
def _regola_sconto(criterio, soglia_pezzi, soglia_valore_eur,
                   percento) -> tuple:
    """(criterio, soglia, percento) validi dello sconto carrello, o
    ('', 0, 0) se non c'e' una regola vera. E' il lettore UNICO: la leva
    spenta, un criterio che non sappiamo applicare, una soglia non seria
    o una percentuale a zero danno tutte lo stesso «niente sconto»,
    cosi' nessun chiamante deve ricordarsi i casi — e la `soglia` che
    esce e' GIA' quella del criterio scelto, cioe' un numero solo da
    guardare (i due parametri si chiamano per esteso proprio perche' in
    uscita il nome torna generico: l'unita' la dice il criterio —
    PEZZI a 'pezzi', EURO INTERI a 'valore').
    Prende quattro campi e non una riga — il patto di in_ferie: cosi' lo
    stesso giudice serve la riga di `utenti`, gli alias
    `venditore_sconto_*` della vetrina e la prova in CI.
    Il criterio VUOTO vale 'pezzi', ed e' la retrocompatibilita': e'
    letteralmente il mondo di ieri, quando i pezzi erano l'unica misura.
    Un criterio SCRITTO ma fuori catalogo invece spegne tutto — vedi
    _sconto_pacco per il perche' non ripiega sui pezzi.
    Il '' in uscita non e' mai un criterio scritto in tabella: e' solo
    il modo in cui questo lettore dice no.
    Il tappo sul percento e' una CINTURA contro una colonna scritta a
    mano o da un import, non il varco: l'endpoint rifiuta con un 400
    che dice la cifra (la lezione di quantita_da_payload), qui si
    limita il danno in silenzio — un conto non e' il posto dove
    protestare."""
    criterio = (str(criterio).strip().lower() if criterio else "pezzi")
    percento = int(percento or 0)
    if criterio == "valore":
        soglia = int(soglia_valore_eur or 0)
        minimo = SCONTO_PACCO_MIN_VALORE_EUR
    else:
        soglia, minimo = int(soglia_pezzi or 0), SCONTO_PACCO_MIN_SOGLIA
    if not SCONTO_PACCO_ATTIVO or criterio not in SCONTO_PACCO_CRITERI \
            or percento <= 0 or soglia < minimo:
        return "", 0, 0
    return criterio, soglia, min(percento, SCONTO_PACCO_MAX_PERCENTO)


def _regola_sped_gratis(soglia_eur) -> int:
    """La soglia valida della spedizione gratis IN EURO INTERI, o 0 se
    non c'e' una promessa vera. Gemella di _regola_sconto e per la
    stessa ragione: la leva spenta, una soglia sotto il minimo e un
    numero illeggibile danno tutti lo stesso «niente promessa», cosi'
    nessun chiamante deve ricordarsi i casi — e la normalizzazione vive
    in un posto solo invece che nelle quattro superfici che la promessa
    la mostrano.
    Prende il campo e non la riga (il patto di in_ferie): serve la riga
    di `utenti`, l'alias `venditore_sped_gratis_eur` della vetrina e la
    prova in CI."""
    try:
        soglia_eur = int(soglia_eur or 0)
    except (TypeError, ValueError):
        return 0
    if not SPED_GRATIS_ATTIVO or soglia_eur < SPED_GRATIS_MIN_EUR:
        return 0
    return soglia_eur


def _sped_gratis_pubblico(soglia_eur) -> dict:
    """La promessa della spedizione gratis COM'ESCE IN PUBBLICO.
    Finche' la soglia era in sats questo gemello di _sconto_pubblico
    NON serviva, ed era scritto qui che non era una dimenticanza: il
    campo era UNO e un client di ieri non lo conosceva affatto, quindi
    non disegnava niente — un'assenza, non una bugia.
    Col passaggio all'EURO i campi diventano due, e la nota si rovescia:
    un client rimasto in cache legge `venditore_sped_gratis` e ci
    scrive «sats», quindi servirlo col numero nuovo direbbe «spedizione
    gratis da 50 sats» — una bugia, e delle peggiori, perche' sembra
    una promessa generosissima. Esce a ZERO, e il client vecchio torna
    a non disegnare niente; il numero vero viaggia nella chiave nuova.
    E' la regola d'oro di _sconto_pubblico, parola per parola."""
    return {"soglia": 0, "eur": _regola_sped_gratis(soglia_eur)}


def _sconto_pubblico(criterio, soglia_pezzi, soglia_valore_eur,
                     percento) -> dict:
    """La regola dello sconto carrello COM'ESCE IN PUBBLICO, gia'
    retrocompatibile. Esiste per una riga sola, ed e' la regola d'oro
    del cantiere del criterio: `soglia` (i pezzi) esce maggiore di zero
    SOLO a criterio 'pezzi'. E' lei il lucchetto del client vecchio
    rimasto in cache, che di campi ne legge uno — chiede
    `soglia>0 && percento>0` prima di disegnare la promessa —: con la
    soglia a zero non disegna niente, e un'assenza non e' una bugia,
    mentre un «−10% da 100000 pezzi» lo sarebbe.
    COL PASSAGGIO ALL'EURO il lucchetto guadagna un secondo dente:
    `valore` — che il client di IERI leggeva in sats — esce sempre a
    ZERO, e il numero vero viaggia in `valore_eur`. Senza, un client
    rimasto in cache scriverebbe «da 25 sats», che non e' una promessa
    piu' avara: e' una promessa assurda, e chi la legge pensa a un
    guasto. Stessa ragione, dente nuovo.
    Vive qui e non a mano nelle due superfici (la vetrina e il profilo
    del negozio) perche' quella regola ripetuta in due posti e' una
    regola che un giorno uno dei due dimentica; e stando in una pura si
    puo' torturare in CI invece che sperarci."""
    crit, sog, pct = _regola_sconto(criterio, soglia_pezzi,
                                    soglia_valore_eur, percento)
    return {"criterio": crit,
            "soglia": sog if crit == "pezzi" else 0,
            "valore": 0,
            "valore_eur": sog if crit == "valore" else 0,
            "percento": pct}


# ---------------------- ASTE: la matematica pura ---------------------
# Il cuore dell'asta in funzioni PURE: niente config, niente database,
# niente rete — le leve arrivano per parametro e il tempo dal
# chiamante (che e' SEMPRE il server: il client mostra soltanto).
# Sono il «modulo» che prove.py estrae con pezzo() e tortura in CI
# senza chiavi: chi le rifattorizza le tenga autosufficienti.

def _asta(a) -> bool:
    """Quest'annuncio e' un'asta? (viva, gia' chiusa o deserta:
    finche' la base c'e', l'acquisto diretto resta spento)."""
    return a["asta_base_sats"] > 0


def _asta_viva(a, adesso: int) -> bool:
    """L'asta accetta puntate? Base fissata e scadenza nel futuro."""
    return a["asta_base_sats"] > 0 and a["asta_scadenza"] > adesso


def in_ferie(ferie_fino: int, adesso: int) -> bool:
    """IL NEGOZIO E' CHIUSO? (ago 2026) Gate in LETTURA sulla data di
    rientro — lo stesso patto di lampo e asta: alla scadenza il
    negozio riapre DA SOLO, senza che nessun orologio debba passare a
    girare un interruttore. La scopa scadenze_ferie e' pulizia, non
    e' lei a riaprire: se il server resta spento una settimana, al
    riavvio chi doveva riaprire e' gia' aperto.
    Prende un INT e non una riga, apposta: lo stesso giudice serve la
    riga utenti, l'alias venditore_ferie della vetrina e la prova in
    CI, senza assumere la forma del contenitore. Al filo esatto
    (ferie_fino == adesso) il negozio e' APERTO, come _asta_viva."""
    return ferie_fino > adesso


def rilancio_minimo(testa_sats: int, incremento_percento: int) -> int:
    """Il totale minimo per superare chi e' in testa: +N% arrotondato
    per difetto, ma MAI meno di 1 sat sopra — i sats sono interi, il
    5% di 10 sats fa 0 e senza il max si potrebbe pareggiare. E' LA
    funzione unica del minimo: endpoint, foglio puntata e CTA delle
    notifiche dicono tutti questo numero."""
    return testa_sats + max(1, testa_sats * incremento_percento // 100)


def nuova_scadenza(scadenza: int, saldo_ts: int, proroga_s: int) -> int:
    """L'anti-cecchino in un posto solo: un saldo negli ultimi
    proroga_s secondi sposta la scadenza a saldo+proroga. Nessun
    tetto alle proroghe, per scelta: l'asta finisce quando ci sono
    proroga_s di silenzio. Saldo a scadenza passata = tardivo, e non
    passa di qui."""
    if 0 < scadenza - saldo_ts < proroga_s:
        return saldo_ts + proroga_s
    return scadenza


def etichetta_offerente(n: int) -> str:
    """'A'..'Z', poi 'AA', 'AB'...: l'anonimato stabile degli
    offerenti, per ordine di primo saldo (n parte da 0)."""
    lettere = ""
    n += 1
    while n > 0:
        n, resto = divmod(n - 1, 26)
        lettere = chr(65 + resto) + lettere
    return lettere


def conto_chiusura(puntate: list) -> tuple:
    """Il conto della chiusura: dalle puntate sceglie la vincitrice
    (offerto piu' alto; a parita' — possibile per la corsa di due
    fatture nate sulla stessa testa — vince chi ha SALDATO prima,
    cioe' saldo_seq minore, poi id: lo stesso ordine di _leader_asta,
    o il «sei in testa» di ieri e il vincitore di oggi divergono) e
    mette tutte le altre nei rimborsi, ognuna per il suo versato e
    ognuna col suo MOTIVO. Col proxy (ago 2026) la vincitrice paga
    l'ESPOSTO, non il budget: se versato > offerto la differenza e'
    la riga 'eccedenza' — torna a lei dal registro. INVARIANTE,
    provata in CI: somma dei versati in ingresso = OFFERTO della
    vincitrice + somma dei rimborsi. Pura: righe come dict, il
    database non lo vede."""
    in_gara = [p for p in puntate
               if p["stato"] == "attiva" and p["versato_sats"] > 0]
    if not in_gara:
        return None, []
    vincitrice = min(in_gara, key=lambda p: (-p["offerto_sats"],
                                             p["saldo_seq"], p["id"]))
    rimborsi = [{"puntata_id": p["id"], "tg_id": p["tg_id"],
                 "importo_sats": p["versato_sats"], "motivo": "perdente"}
                for p in in_gara if p["id"] != vincitrice["id"]]
    eccedenza = vincitrice["versato_sats"] - vincitrice["offerto_sats"]
    if eccedenza > 0:
        rimborsi.append({"puntata_id": vincitrice["id"],
                         "tg_id": vincitrice["tg_id"],
                         "importo_sats": eccedenza,
                         "motivo": "eccedenza"})
    return vincitrice, rimborsi


def esposizioni_proxy(puntate: list, base_sats: int,
                      incremento_percento: int) -> dict:
    """Il motore delle ESPOSIZIONI (il proxy, ago 2026): dato il campo
    di gara dice quanto ogni puntata deve mostrare. Le regole:
    - la CAPACITA' che gareggia e' il versato (per le manuali coincide
      con l'esposto); il ranking e' (versato, saldo_seq, id) — lo
      stesso tie-break di _leader_asta;
    - manuale: esposto = versato, sempre;
    - proxy NON in testa: esposto = versato — il suo proxy ha provato
      e perso, il budget e' esausto e da li' e' indistinguibile da una
      manuale (ed e' la notifica «budget esaurito»);
    - proxy in testa: il minimo necessario — min(versato, max(base,
      rilancio_minimo(versato del secondo))); senza un secondo, la
      base. E' cosi' che due proxy CONVERGONO in una passata sola:
      il secondo viene esposto al suo massimo, il primo un incremento
      sopra (o al proprio cap), niente rincorsa di eventi;
    - NESSUN esposto scende MAI (max con l'attuale): l'esposto e'
      storia pubblica — ed e' il motivo per cui il ritiro di un rivale
      non richiede nessun ricalcolo (il motore e' gia' un punto fisso).
    IDEMPOTENTE per costruzione: due passate = stessa risposta. Pura:
    righe come dict, la proroga NON vive qui (decisione del cantiere:
    i rialzi automatici non prorogano mai — la convergenza e' UN
    evento contabile dentro il saldo che l'ha scatenata)."""
    in_gara = [p for p in puntate
               if p["stato"] == "attiva" and p["versato_sats"] > 0]
    ordine = sorted(in_gara, key=lambda p: (-p["versato_sats"],
                                            p["saldo_seq"], p["id"]))
    fuori = {}
    for i, p in enumerate(ordine):
        if i == 0 and p.get("proxy"):
            secondo = ordine[1]["versato_sats"] if len(ordine) > 1 else 0
            serve = rilancio_minimo(secondo, incremento_percento) \
                if secondo else base_sats
            esposto = min(p["versato_sats"], max(base_sats, serve))
        else:
            esposto = p["versato_sats"]
        fuori[p["id"]] = max(p["offerto_sats"], esposto)
    return fuori


def durata_asta_da_payload(d) -> int:
    """La durata dell'asta in SECONDI; 0 = quest'annuncio non e'
    un'asta. Giudice del payload {"asta": {"durata_giorni": N}}: qui
    si mette in gioco il denaro altrui, quindi una durata fuori
    dall'elenco e' un 400 e mai un default silenzioso. In collaudo si
    accettano anche i minuti ({"durata_minuti": M}): il ciclo intero
    si prova senza aspettare giorni."""
    asta = d.get("asta")
    if not isinstance(asta, dict):
        return 0
    if not ASTA_ABILITATA:
        raise HTTPException(400, "Le aste non sono attive")
    if MODALITA_COLLAUDO:
        try:
            minuti = int(asta.get("durata_minuti") or 0)
        except (TypeError, ValueError):
            minuti = 0
        if minuti > 0:
            return minuti * 60
    try:
        giorni = int(asta.get("durata_giorni") or 0)
    except (TypeError, ValueError):
        giorni = 0
    if giorni not in ASTA_DURATE_GIORNI:
        raise HTTPException(400, "Durata dell'asta non valida")
    return giorni * 86400


def _leader_asta(con, annuncio_id: int):
    """Il giudice unico della testa: l'offerta piu' alta fra le
    puntate in gara; a parita' — possibile per la corsa di due fatture
    nate sulla stessa testa — vince chi ha SALDATO prima. L'orario ha
    la risoluzione del secondo e non basta: decide saldo_seq, il
    numero d'ordine dei saldi. None = nessuna puntata salda."""
    return con.execute(
        "SELECT * FROM puntate WHERE annuncio_id=? AND stato='attiva' "
        "AND versato_sats>0 "
        "ORDER BY offerto_sats DESC, saldo_seq ASC, id ASC LIMIT 1",
        (annuncio_id,)).fetchone()


def _puntate_attive_salde(con, annuncio_id: int) -> int:
    """Quante puntate SALDE sono in gara: il giudice del VINCOLO
    (regola del cantiere): dalla prima puntata saldata l'asta e'
    vincolante — il venditore non la annulla ne' la modifica piu',
    solo un moderatore puo' scioglierla restituendo i sats."""
    return con.execute(
        "SELECT COUNT(*) AS n FROM puntate WHERE annuncio_id=? AND "
        "stato='attiva' AND versato_sats>0",
        (annuncio_id,)).fetchone()["n"]


# ------------------- ASTE: il motore delle puntate -------------------
# Puntare = PAGARE: la prima puntata versa l'intero importo, i rilanci
# la sola differenza fino al nuovo totale, e una puntata esiste solo
# quando la sua fattura e' SALDATA. Il client dichiara il totale che
# offre, il server calcola la differenza da versare (mai fidarsi di
# importi dal client). La corsa fra due fatture si decide al saldo —
# fa fede l'orario del SERVER — e un pagamento non si respinge mai:
# chi arriva secondo resta puntata valida non in testa.

RILANCIO_EXPIRY = 600      # fatture corte: 10 minuti
RILANCIO_STANTIO = 1200    # 2x la vita della fattura (pattern reaper)


def _stesse_chiavi_nostr(con, tg_a: int, tg_b: int) -> bool:
    """Il venditore non punta sulle proprie aste nemmeno col secondo
    account collegato alla STESSA chiave Nostr (regola del cantiere:
    controllo su tg_id E npub). Contano solo le chiavi dal possesso
    dimostrato o dichiarato sulla riga utente."""
    righe = {r["tg_id"]: r for r in con.execute(
        "SELECT tg_id, npub, npub_accesso FROM utenti WHERE tg_id IN (?,?)",
        (tg_a, tg_b))}
    a, b = righe.get(tg_a), righe.get(tg_b)
    if not a or not b:
        return False
    chiavi_a = {c for c in (a["npub"], a["npub_accesso"]) if c}
    chiavi_b = {c for c in (b["npub"], b["npub_accesso"]) if c}
    return bool(chiavi_a & chiavi_b)


@app.post("/api/aste/{annuncio_id}/punta")
async def fai_puntata(annuncio_id: int, req: Request,
                      x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    """La puntata: il compratore dichiara il TOTALE che offre e riceve
    la fattura della sola differenza rispetto a quanto ha gia' in
    cassaforte. Con proxy=1 (ago 2026) il totale e' il suo MASSIMO
    segreto: in gara il motore espone solo il necessario. La liturgia
    e' quella di compra(): guardie, UNICO await sulla invoice,
    ricontrollo, poi zero await fino al commit."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not ASTA_ABILITATA:
        # la leva spegne solo le puntate NUOVE: chiusure, ritiri e
        # riscossioni delle aste vive continuano (vedi le leve)
        raise HTTPException(400, "Le aste non sono attive")
    vuole_proxy = bool(d.get("proxy"))
    if vuole_proxy and not ASTA_PROXY_ATTIVO:
        # come sopra: la leva gatea le sole puntate proxy NUOVE, il
        # motore continua per i proxy gia' in gara
        raise HTTPException(400, "Il rilancio automatico non è attivo")
    try:
        totale = int(d.get("totale_sats") or 0)
    except (TypeError, ValueError):
        totale = 0
    if totale <= 0:
        raise HTTPException(400, "Indica il totale che offri, in sats")
    con = db()
    adesso = int(time.time())
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato='attivo'",
                    (annuncio_id,)).fetchone()
    if not a or not _asta(a):
        con.close()
        raise HTTPException(404, "Asta non trovata")
    if not _asta_viva(a, adesso):
        # il read gate: l'asta e' chiusa anche se l'orologio non e'
        # ancora passato ad aggiudicarla
        con.close()
        raise HTTPException(409, "L'asta è chiusa: niente più puntate")
    if a["venditore_id"] == user["id"] or \
            _stesse_chiavi_nostr(con, a["venditore_id"], user["id"]):
        con.close()
        raise HTTPException(400, "Non puoi puntare sulla tua stessa asta")
    # CINTURA: per costruzione non ci si arriva — un'asta viva blocca
    # la partenza per le ferie, quindi in ferie non ce ne sono. Ci va
    # lo stesso: una guardia che oggi non scatta e' quella che regge
    # domani, se la regola degli impegni aperti cambia.
    guardia_ferie(con, a["venditore_id"])
    b = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    if not b or not (b["ln_address"] or "").strip():
        # il Lightning address e' il binario del rimborso: senza, un
        # perdente resterebbe coi sats fermi in «Da riscuotere» —
        # meglio chiederlo PRIMA che i sats partano
        con.close()
        raise HTTPException(400, "Per puntare serve il tuo Lightning "
                                 "address (per l'eventuale rimborso): "
                                 "lo imposti nel Profilo, sotto "
                                 "«Incassi e pagamenti»")
    mia = con.execute("SELECT * FROM puntate WHERE annuncio_id=? AND tg_id=?",
                      (annuncio_id, user["id"])).fetchone()
    if mia and mia["stato"] == "chiusa":
        con.close()
        raise HTTPException(409, "Ti sei ritirato da questa asta: il "
                                 "ritiro è definitivo")
    if vuole_proxy and mia and con.execute(
            "SELECT 1 FROM rimborsi_asta WHERE puntata_id=? AND "
            "motivo='eccedenza_ritiro'", (mia["id"],)).fetchone():
        # «scesa l'eccedenza non risale»: chi ha ritirato l'eccedenza
        # non ricostruisce un massimo nascosto su quest'asta — i
        # rilanci normali, alla luce del sole, restano aperti
        con.close()
        raise HTTPException(400, "Hai già ritirato l'eccedenza su "
                                 "questa asta: il rilancio automatico "
                                 "qui è chiuso, restano le puntate "
                                 "normali")
    pendente = con.execute(
        "SELECT 1 FROM rilanci WHERE annuncio_id=? AND tg_id=? AND "
        "stato='creato' AND creato>=?",
        (annuncio_id, user["id"], adesso - RILANCIO_STANTIO)).fetchone()
    if pendente:
        con.close()
        raise HTTPException(400, "Hai già una fattura di puntata in "
                                 "corso: pagala o lascia che scada "
                                 "(vale 10 minuti)")
    testa = _leader_asta(con, annuncio_id)
    sono_leader = bool(testa and testa["tg_id"] == user["id"])
    if sono_leader and not vuole_proxy:
        con.close()
        raise HTTPException(400, "Sei già in testa: rilanciare su te "
                                 "stesso costerebbe sats senza motivo")
    if not sono_leader:
        # il minimo si calcola dal PUBBLICO (l'esposto della testa):
        # il massimo di un proxy e' segreto anche qui — chi entra al
        # minimo e viene subito ricoperto dal budget del leader sta
        # usando l'asta come previsto, e la notifica onesta glielo dice
        minimo = rilancio_minimo(testa["offerto_sats"],
                                 ASTA_INCREMENTO_PERCENTO) if testa \
            else a["asta_base_sats"]
        if totale < minimo:
            con.close()
            raise HTTPException(400, f"La puntata minima ora è "
                                     f"{minimo:,} sats".replace(",", " "))
    # il leader proxy che AGGIUNGE budget salta il minimo: il suo
    # esposto non cambia (il secondo non e' cambiato), sale solo il
    # massimo segreto — basta che il totale superi il versato (la
    # guardia del delta qui sotto)
    versato = mia["versato_sats"] if mia else 0
    delta = totale - versato
    if delta <= 0:
        con.close()
        raise HTTPException(400, "Hai già versato abbastanza per questo "
                                 "totale: alza la cifra")
    inv = await crea_invoice_escrow(
        delta, f"Barattolo asta #{annuncio_id}: puntata {totale} sats",
        expiry=RILANCIO_EXPIRY)
    # Il ricontrollo che fa fede (patto mono-processo: da qui al
    # commit nessun await). Durante l'attesa della invoice l'asta puo'
    # essere scaduta o la testa salita oltre il mio totale: fallito =
    # 409 e la fattura appena nata muore da sola in 10 minuti.
    fresco = con.execute("SELECT * FROM annunci WHERE id=?",
                         (annuncio_id,)).fetchone()
    if (not fresco or fresco["stato"] != "attivo"
            or not _asta_viva(fresco, int(time.time()))):
        con.close()
        raise HTTPException(409, "L'asta si è chiusa proprio adesso")
    testa2 = _leader_asta(con, annuncio_id)
    if testa2 and testa2["tg_id"] == user["id"]:
        # sono (ancora, o diventato) leader: e' un top-up del budget,
        # il minimo non si applica. Il delta e' gia' > 0; se la
        # fusione ha toccato il versato durante l'await, i conti
        # restano giusti per costruzione — il versato e' ADDITIVO,
        # ogni delta pagato si somma e il motore espone dal versato
        # vero, mai dal totale dichiarato.
        pass
    else:
        minimo2 = rilancio_minimo(testa2["offerto_sats"],
                                  ASTA_INCREMENTO_PERCENTO) if testa2 \
            else a["asta_base_sats"]
        if totale < minimo2:
            con.close()
            raise HTTPException(409, "Ti hanno superato mentre "
                                     "preparavo la fattura: serve un "
                                     + ("massimo" if vuole_proxy
                                        else "totale") + " più alto")
    if not mia:
        con.execute("INSERT OR IGNORE INTO puntate(annuncio_id,tg_id,"
                    "venditore_id,stato,creato,aggiornato) "
                    "VALUES(?,?,?,'attiva',?,?)",
                    (annuncio_id, user["id"], a["venditore_id"],
                     adesso, adesso))
        mia = con.execute("SELECT * FROM puntate WHERE annuncio_id=? AND "
                          "tg_id=?", (annuncio_id, user["id"])).fetchone()
    con.execute("INSERT INTO rilanci(puntata_id,annuncio_id,tg_id,"
                "offerto_sats,delta_sats,payment_hash,proxy,stato,"
                "creato,aggiornato) VALUES(?,?,?,?,?,?,?,'creato',?,?)",
                (mia["id"], annuncio_id, user["id"], totale, delta,
                 inv["payment_hash"], 1 if vuole_proxy else 0,
                 adesso, adesso))
    rilancio_id = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.commit()
    con.close()
    return {"rilancio_id": rilancio_id, "invoice": inv["payment_request"],
            "payment_hash": inv["payment_hash"], "delta_sats": delta,
            "totale_sats": totale, "scadenza": fresco["asta_scadenza"],
            "scadenza_invoice": RILANCIO_EXPIRY}


@app.post("/api/rilanci/{rilancio_id}/annulla")
async def annulla_rilancio(rilancio_id: int,
                           x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """Chi ha chiesto la fattura di puntata e ci ripensa (ago 2026):
    la fattura 'creato' diventa la lapide 'annullato' — mai DELETE,
    un saldo arrivato dopo deve avere una riga su cui atterrare, e
    controlla_annullati lo manda nel binario del fuori-tempo («Da
    riscuotere»). Libera subito la guardia «una fattura pendente alla
    volta»: si puo' ripuntare senza aspettare il reaper. Il gemello di
    annulla_ordine: pagamento controllato PRIMA, CAS sullo stato.
    NON e' un ritiro: la puntata resta in gara col suo versato."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    ril = con.execute("SELECT * FROM rilanci WHERE id=? AND tg_id=?",
                      (rilancio_id, user["id"])).fetchone()
    con.close()   # niente transazione aperta durante l'await
    if not ril or ril["stato"] != "creato":
        raise HTTPException(400, "Operazione non permessa")
    if await invoice_pagata(ril["payment_hash"]):
        raise HTTPException(409, "Questo pagamento risulta già arrivato: "
                                 "niente da annullare — attendi un attimo "
                                 "la verifica della puntata")
    con = db()
    cur = con.execute("UPDATE rilanci SET stato='annullato', aggiornato=? "
                      "WHERE id=? AND stato='creato'",
                      (int(time.time()), rilancio_id))
    if cur.rowcount == 0:
        con.commit()
        con.close()
        raise HTTPException(409, "Il pagamento è arrivato proprio adesso: "
                                 "la puntata è andata avanti")
    con.commit()
    con.close()
    return {"ok": True}


@app.post("/api/rilanci/{rilancio_id}/verifica")
async def verifica_rilancio(rilancio_id: int,
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Il poll del pagamento della puntata (gemello di
    verifica_pagamento, con la guardia in piu': il rilancio e' MIO).
    Il CAS sullo stato fa vincere una sola chiamata; da li' in poi
    zero await fino al commit. Fa fede l'orario di SALDO: se nel
    frattempo la testa e' salita il pagamento non si respinge — resto
    puntata valida non in testa; se l'asta e' GIA' chiusa i sats vanno
    dritti nel registro «Da riscuotere», nessun ordine, nessuna
    eccezione."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    ril = con.execute("SELECT * FROM rilanci WHERE id=? AND tg_id=?",
                      (rilancio_id, user["id"])).fetchone()
    con.close()
    if not ril:
        raise HTTPException(404, "Puntata non trovata")
    if ril["stato"] != "creato":
        return {"stato": ril["stato"]}
    if not await invoice_pagata(ril["payment_hash"]):
        return {"stato": "in_attesa"}
    con = db()
    adesso = int(time.time())
    cur = con.execute("UPDATE rilanci SET stato='saldato', saldato_il=?, "
                      "aggiornato=? WHERE id=? AND stato='creato'",
                      (adesso, adesso, rilancio_id))
    if cur.rowcount == 0:
        # un'altra chiamata (poll + «ho pagato») ha gia' fatto il lavoro
        con.commit()
        esito = con.execute("SELECT stato FROM rilanci WHERE id=?",
                            (rilancio_id,)).fetchone()["stato"]
        con.close()
        return {"stato": esito}
    # --- da qui ZERO await fino al commit ---
    a = con.execute("SELECT * FROM annunci WHERE id=?",
                    (ril["annuncio_id"],)).fetchone()
    p = con.execute("SELECT * FROM puntate WHERE id=?",
                    (ril["puntata_id"],)).fetchone()
    if (not a or a["stato"] != "attivo" or not _asta_viva(a, adesso)
            or not p or p["stato"] != "attiva"):
        # SALDO FUORI TEMPO: l'asta e' chiusa, OPPURE la puntata non
        # e' piu' in gara (ritirata). Il secondo caso non e' teorico:
        # il ritiro esige solo che non ci siano fatture FRESCHE
        # (1200s), ma una fattura puo' essere stata PAGATA nei suoi
        # 10 minuti e mai verificata — il saldo arriva dopo, su una
        # puntata 'chiusa'. In entrambi i casi i sats vanno nel
        # registro «Da riscuotere», MAI versati su una puntata fuori
        # gara; la cintura d'idempotenza e' sul rilancio_id.
        con.execute("UPDATE rilanci SET stato='tardivo', aggiornato=? "
                    "WHERE id=?", (adesso, rilancio_id))
        con.execute("INSERT OR IGNORE INTO rimborsi_asta(annuncio_id,"
                    "tg_id,puntata_id,rilancio_id,importo_sats,motivo,"
                    "stato,creato,aggiornato) "
                    "VALUES(?,?,?,?,?,'tardivo','da_riscuotere',?,?)",
                    (ril["annuncio_id"], user["id"], ril["puntata_id"],
                     rilancio_id, ril["delta_sats"], adesso, adesso))
        rid = con.execute("SELECT id FROM rimborsi_asta WHERE "
                          "rilancio_id=?", (rilancio_id,)).fetchone()["id"]
        con.commit()
        con.close()
        await notifica(user["id"],
                       "⌛ <b>Questo pagamento è arrivato fuori tempo</b> "
                       "(l'asta era chiusa, o ti eri già ritirato): i "
                       "sats sono al sicuro nel tuo «Da riscuotere», "
                       "nel Profilo.")
        # e la riscossione parte subito, sul binario di sempre
        await _paga_rimborso(rid)
        return {"stato": "tardivo", "importo_sats": ril["delta_sats"]}
    testa_prima = _leader_asta(con, ril["annuncio_id"])
    etichetta = p["etichetta"]
    if not etichetta:
        gia = con.execute("SELECT COUNT(*) AS n FROM puntate WHERE "
                          "annuncio_id=? AND etichetta!=''",
                          (ril["annuncio_id"],)).fetchone()["n"]
        etichetta = etichetta_offerente(gia)
    # il numero d'ordine del saldo: progressivo GLOBALE, assegnato nel
    # blocco senza await — e' il tie-break della testa (l'orario da
    # solo non basta, ha la risoluzione del secondo)
    seq = con.execute("SELECT COALESCE(MAX(saldo_seq),0)+1 AS s "
                      "FROM puntate").fetchone()["s"]
    # il versato si SOMMA; l'esposto non si scrive piu' qui a secco —
    # lo decide il motore, per TUTTE le puntate dell'asta. Il flag
    # proxy si alza (MAX: mai downgrade), e SOLO in questo ramo — il
    # tardivo non tocca ne' proxy ne' versato.
    con.execute("UPDATE puntate SET versato_sats=versato_sats+?, "
                "etichetta=?, saldo_seq=?, proxy=MAX(proxy,?), "
                "aggiornato=? WHERE id=?",
                (ril["delta_sats"], etichetta, seq, ril["proxy"],
                 adesso, p["id"]))
    # IL MOTORE DELLE ESPOSIZIONI: una passata sola, dentro il blocco
    # senza await — due proxy convergono QUI, come evento contabile,
    # non come rincorsa di pagamenti. Per le manuali produce l'esposto
    # di sempre (= versato).
    campo = [dict(r) for r in con.execute(
        "SELECT * FROM puntate WHERE annuncio_id=?",
        (ril["annuncio_id"],))]
    esposizioni = esposizioni_proxy(campo, a["asta_base_sats"],
                                    ASTA_INCREMENTO_PERCENTO)
    for pid, esp in esposizioni.items():
        con.execute("UPDATE puntate SET offerto_sats=? "
                    "WHERE id=? AND offerto_sats!=?", (esp, pid, esp))
    # la cifra PUBBLICA di questa fattura (cronologia): l'esposto
    # post-motore, MAI il totale dichiarato — per un rilancio proxy
    # quello e' il massimo segreto
    mio_esposto = esposizioni[p["id"]]
    con.execute("UPDATE rilanci SET esposto_sats=? WHERE id=?",
                (mio_esposto, rilancio_id))
    testa_dopo = _leader_asta(con, ril["annuncio_id"])
    era_leader = bool(testa_prima and testa_prima["tg_id"] == user["id"])
    testa_cambiata = (not testa_prima or not testa_dopo
                      or (testa_dopo["id"], testa_dopo["offerto_sats"])
                      != (testa_prima["id"], testa_prima["offerto_sats"]))
    # L'anti-cecchino, nel write path: la data di chiusura vive in UN
    # posto solo (annunci.asta_scadenza) e la sposta solo un saldo
    # negli ultimi minuti. Nessun tetto alle proroghe, per scelta.
    # CON UNA GUARDIA (il proxy, ago 2026): il top-up del leader che
    # non cambia ne' testa ne' esposto NON proroga — la sua fattura e'
    # rimborsabile per costruzione (eccedenza), quindi prorogare qui
    # sarebbe un'asta eterna a costo zero. Ogni saldo di un NON leader
    # proroga come ieri.
    scad = a["asta_scadenza"]
    if not era_leader or testa_cambiata:
        scad = nuova_scadenza(a["asta_scadenza"], adesso,
                              ASTA_PROROGA_MINUTI * 60)
        if scad != a["asta_scadenza"]:
            con.execute("UPDATE annunci SET asta_scadenza=? WHERE id=?",
                        (scad, a["id"]))
    n_offerenti = con.execute("SELECT COUNT(*) AS n FROM puntate WHERE "
                              "annuncio_id=? AND stato='attiva' AND "
                              "versato_sats>0",
                              (ril["annuncio_id"],)).fetchone()["n"]
    con.commit()
    con.close()
    in_testa = bool(testa_dopo and testa_dopo["tg_id"] == user["id"])
    minimo = rilancio_minimo(testa_dopo["offerto_sats"],
                             ASTA_INCREMENTO_PERCENTO) if testa_dopo else 0
    # --- notifiche e cortesie, a soldi gia' al sicuro ---
    try:
        # puntare mette l'asta nel barattolo da solo: le proprie gare
        # si ritrovano nei preferiti (privati come sempre; il limite
        # dei 20 non blocca questa aggiunta di servizio, come non
        # blocca la fusione)
        con = db()
        con.execute("INSERT OR IGNORE INTO preferiti(tg_id,annuncio_id,"
                    "creato) VALUES(?,?,?)",
                    (user["id"], ril["annuncio_id"], adesso))
        con.commit()
        con.close()
    except Exception:
        pass
    titolo = a["titolo"][:60]
    link = f"\n{URL_PUBBLICO}/annuncio/{ril['annuncio_id']}"
    if in_testa and testa_prima and testa_prima["tg_id"] != user["id"]:
        # il «budget esaurito»: un proxy spodestato e' stato esposto
        # al suo massimo per costruzione — e' l'unico squillo che il
        # proxy riceve (i rialzi automatici sono silenziosi: il proxy
        # esiste per non guardare l'asta)
        esaurito = (f"Il tuo «rilancia per me» ha dato tutto: il "
                    f"massimo di "
                    f"{_fmt_sats(testa_prima['versato_sats'])} sats è "
                    f"esaurito. " if testa_prima["proxy"] else "")
        await notifica(testa_prima["tg_id"],
                       f"🔨 <b>Ti hanno superato</b> su «{titolo}»: la "
                       f"testa è a {_fmt_sats(testa_dopo['offerto_sats'])} "
                       f"sats. {esaurito}Rilanci da "
                       f"{_fmt_sats(minimo)} sats — paghi solo la "
                       f"differenza — oppure puoi ritirarti.{link}")
    if not in_testa:
        mio_max = (" il tuo massimo è stato esposto per intero e "
                   "non è bastato." if ril["proxy"] or p["proxy"]
                   else " il tuo versato conta già.")
        await notifica(user["id"],
                       f"🔨 La tua puntata su «{titolo}» è al sicuro, ma "
                       f"nel frattempo ti hanno superato: la testa è a "
                       f"{_fmt_sats(testa_dopo['offerto_sats'])} sats. "
                       f"Per rilanciare servono almeno "
                       f"{_fmt_sats(minimo)} sats —{mio_max}{link}")
    if not (era_leader and not testa_cambiata):
        # il venditore sente ogni puntata che cambia qualcosa, con la
        # cifra ESPOSTA (mai il totale dichiarato: sarebbe il budget);
        # il top-up del leader e' muto — per lui non e' successo niente
        await notifica(a["venditore_id"],
                       f"🔨 <b>Nuova puntata</b> su «{titolo}»: "
                       f"{_fmt_sats(testa_dopo['offerto_sats'])} sats "
                       f"({n_offerenti} offerent{'e' if n_offerenti == 1 else 'i'}).")
    return {"stato": "saldato", "in_testa": in_testa,
            "offerto_sats": ril["offerto_sats"],
            "esposto_sats": mio_esposto, "proxy": bool(ril["proxy"]),
            "top_sats": testa_dopo["offerto_sats"] if testa_dopo else 0,
            "minimo_sats": minimo, "scadenza": scad}


@app.get("/api/aste/{annuncio_id}")
def stato_asta(annuncio_id: int, x_tg_init_data: str = Header(""),
               barattolo_sessione: str = Cookie("")):
    """La fotografia dell'asta per il dettaglio e il foglio puntata:
    testa, minimo, cronologia ANONIMA (etichette, mai nomi) e la MIA
    posizione. Autenticato: la vetrina anonima ha gia' top e conteggio
    dai campi pubblici."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=?",
                    (annuncio_id,)).fetchone()
    if not a or not _asta(a):
        con.close()
        raise HTTPException(404, "Asta non trovata")
    testa = _leader_asta(con, annuncio_id)
    cronologia = [
        # la cifra pubblica e' l'ESPOSTO al saldo (esposto_sats), MAI
        # r.offerto_sats: per una fattura proxy quello e' il massimo
        # segreto, e stamparlo qui sarebbe la fuga del budget
        {"etichetta": r["etichetta"], "offerto_sats": r["esposto_sats"],
         "quando": r["saldato_il"]}
        for r in con.execute(
            "SELECT p.etichetta, r.esposto_sats, r.saldato_il "
            "FROM rilanci r JOIN puntate p ON p.id=r.puntata_id "
            "WHERE r.annuncio_id=? AND r.stato='saldato' "
            "ORDER BY r.saldato_il DESC, r.id DESC LIMIT 20",
            (annuncio_id,))]
    mia = con.execute("SELECT * FROM puntate WHERE annuncio_id=? AND "
                      "tg_id=?", (annuncio_id, user["id"])).fetchone()
    offerenti = _puntate_attive_salde(con, annuncio_id)
    con.close()
    minimo = rilancio_minimo(testa["offerto_sats"],
                             ASTA_INCREMENTO_PERCENTO) if testa \
        else a["asta_base_sats"]
    fuori = {"base_sats": a["asta_base_sats"],
             "scadenza": a["asta_scadenza"],
             "top_sats": testa["offerto_sats"] if testa else 0,
             "puntate_n": offerenti,
             # le strade offerte: servono anche al varco del VINCITORE
             # dentro l'ordine (la scelta avviene li')
             "strade": sorted(_strade_asta(a)),
             "minimo_sats": minimo, "cronologia": cronologia,
             "incremento_percento": ASTA_INCREMENTO_PERCENTO,
             "proroga_minuti": ASTA_PROROGA_MINUTI, "mia": None}
    if mia:
        # proxy e versato (= budget) escono SOLO qui, al proprietario:
        # il residuo lo fa il client (versato - offerto)
        fuori["mia"] = {
            "stato": mia["stato"], "etichetta": mia["etichetta"],
            "versato_sats": mia["versato_sats"],
            "offerto_sats": mia["offerto_sats"],
            "proxy": bool(mia["proxy"]),
            "in_testa": bool(testa and testa["tg_id"] == user["id"])}
    return fuori


@app.get("/api/me/puntate")
def mie_puntate(x_tg_init_data: str = Header(""),
                barattolo_sessione: str = Cookie("")):
    """Le mie gare, per la scheda Ordini (gemello di /api/me/offerte):
    ogni puntata con la testa corrente e il minimo per rilanciare, piu'
    i rimborsi in «Da riscuotere». La busta porta le leve: il client
    non hardcoda mai le cifre."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    righe = [dict(r) for r in con.execute(
        "SELECT p.id, p.annuncio_id, p.stato, p.etichetta, "
        "p.versato_sats, p.offerto_sats, p.proxy, p.aggiornato, "
        "a.titolo, a.foto, a.stato AS stato_annuncio, "
        "a.asta_base_sats AS base_sats, a.asta_scadenza AS scadenza "
        "FROM puntate p JOIN annunci a ON a.id=p.annuncio_id "
        "WHERE p.tg_id=? ORDER BY p.aggiornato DESC LIMIT 30",
        (user["id"],))]
    for r in righe:
        testa = _leader_asta(con, r["annuncio_id"])
        r["top_sats"] = testa["offerto_sats"] if testa else 0
        r["in_testa"] = bool(testa and testa["id"] == r["id"])
        r["minimo_sats"] = rilancio_minimo(
            testa["offerto_sats"], ASTA_INCREMENTO_PERCENTO) if testa \
            else r["base_sats"]
    rimborsi = [dict(r) for r in con.execute(
        "SELECT r.id, r.annuncio_id, r.importo_sats, r.motivo, r.creato, "
        "a.titolo FROM rimborsi_asta r "
        "LEFT JOIN annunci a ON a.id=r.annuncio_id "
        "WHERE r.tg_id=? AND r.stato='da_riscuotere' "
        "ORDER BY r.creato DESC", (user["id"],))]
    con.close()
    return {"puntate": righe, "da_riscuotere": rimborsi,
            "leve": {"incremento_percento": ASTA_INCREMENTO_PERCENTO,
                     "proroga_minuti": ASTA_PROROGA_MINUTI,
                     "abilitata": bool(ASTA_ABILITATA),
                     "proxy_attivo": bool(ASTA_PROXY_ATTIVO)}}


# ------------------ ASTE: il binario delle riscossioni ---------------
# «Da riscuotere» e' lo STESSO binario degli incassi venditore:
# cascata invoice depositata -> Lightning address -> fermo col
# sollecito. Nessun tubo nuovo per i pagamenti in uscita; il rimborso
# e' INTEGRALE al sat (le fee di routing le paga la piattaforma, come
# per ogni uscita — la fee di prelievo e' stata valutata e scartata:
# far pagare l'uscita scoraggia le puntate).

_lucchetti_rimborso = defaultdict(asyncio.Lock)


async def _paga_rimborso(rimborso_id: int) -> dict:
    """La riscossione di un rimborso d'asta. Idempotente: lock per
    rimborso + guardia sullo stato (chi arriva a cose fatte esce a
    mani vuote); sul fallimento la invoice si azzera, lo stato RESTA
    'da_riscuotere' e NON si riprova da soli — il patto di
    _sblocca_sats: mai due pagamenti per lo stesso diritto."""
    async with _lucchetti_rimborso[rimborso_id]:
        con = db()
        r = con.execute(
            "SELECT r.*, a.titolo FROM rimborsi_asta r "
            "LEFT JOIN annunci a ON a.id=r.annuncio_id WHERE r.id=?",
            (rimborso_id,)).fetchone()
        if not r:
            con.close()
            return {"ok": False, "stato": "?"}
        if r["stato"] != "da_riscuotere":
            con.close()
            return {"ok": r["stato"] == "riscosso", "stato": r["stato"]}
        if r["payout_stato"] == "incerto":
            con.close()          # gemello di _sblocca_sats: mai due uscite
            return {"ok": False, "stato": r["stato"], "incerto": True}
        u = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                        (r["tg_id"],)).fetchone()
        importo = r["importo_sats"]      # integrale, al sat
        bolt11 = ""
        if r["payout_stato"] != "uscito":
            bolt11 = r["invoice_riscossione"]
            if not bolt11 and u and u["ln_address"]:
                bolt11 = await invoice_da_ln_address(u["ln_address"], importo)
        titolo = (r["titolo"] or "un'asta")[:60]
        esito = (PAGATO if r["payout_stato"] == "uscito"
                 else await paga_venditore(bolt11, importo) if bolt11
                 else NON_PAGATO)
        if esito == INCERTO:
            await _congela_pagamento(
                con, "rimborsi_asta", rimborso_id, bolt11, "puntatore",
                f"Riscossione del rimborso d'asta #{rimborso_id} "
                f"(«{titolo}»): <b>{importo} sats</b>.")
            return {"ok": False, "stato": r["stato"], "incerto": True}

        if esito == PAGATO:
            con.execute("UPDATE rimborsi_asta SET stato='riscosso', "
                        "aggiornato=? WHERE id=?",
                        (int(time.time()), rimborso_id))
            con.commit()
            con.close()
            await notifica(r["tg_id"],
                           f"↩️ <b>Rimborso in arrivo:</b> "
                           f"{_fmt_sats(importo)} sats da «{titolo}» "
                           f"stanno tornando sul tuo wallet. ⚡")
            return {"ok": True, "stato": "riscosso"}
        con.execute("UPDATE rimborsi_asta SET invoice_riscossione='', "
                    "aggiornato=? WHERE id=?",
                    (int(time.time()), rimborso_id))
        con.commit()
        con.close()
        await notifica(r["tg_id"],
                       f"💰 <b>Hai {_fmt_sats(importo)} sats da "
                       f"riscuotere</b> da «{titolo}»: il pagamento "
                       f"automatico non è riuscito. Controlla il tuo "
                       f"Lightning address nel Profilo, oppure incolla "
                       f"una invoice di esattamente quell'importo nella "
                       f"sezione «Da riscuotere».")
        return {"ok": False, "stato": "da_riscuotere"}


@app.post("/api/aste/{annuncio_id}/ritirati")
async def ritira_puntata(annuncio_id: int,
                         x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """Il ritiro volontario, DEFINITIVO (regola del cantiere): chi non
    e' in testa esce quando vuole — la puntata si chiude, il rimborso
    nasce nel registro NELLA STESSA transazione (niente chiave
    d'idempotenza da inventare) e in quest'asta non si rientra. Il
    leader non si ritira MAI: la sua offerta tiene in piedi la gara.
    Fuori dal gate di ASTA_ABILITATA, per scelta: uscire coi propri
    sats non dipende da una leva."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    adesso = int(time.time())
    p = con.execute("SELECT * FROM puntate WHERE annuncio_id=? AND tg_id=?",
                    (annuncio_id, user["id"])).fetchone()
    if not p or p["stato"] != "attiva" or p["versato_sats"] <= 0:
        con.close()
        raise HTTPException(400, "Non hai una puntata attiva su questa "
                                 "asta")
    testa = _leader_asta(con, annuncio_id)
    if testa and testa["id"] == p["id"]:
        con.close()
        raise HTTPException(400, "Sei in testa: chi guida l'asta non "
                                 "si ritira")
    pendente = con.execute("SELECT 1 FROM rilanci WHERE puntata_id=? AND "
                           "stato='creato' AND creato>=?",
                           (p["id"], adesso - RILANCIO_STANTIO)).fetchone()
    if pendente:
        con.close()
        raise HTTPException(400, "Hai una fattura di puntata in corso: "
                                 "pagala o lascia che scada, poi potrai "
                                 "ritirarti")
    cur = con.execute("UPDATE puntate SET stato='chiusa', aggiornato=? "
                      "WHERE id=? AND stato='attiva'", (adesso, p["id"]))
    if cur.rowcount == 0:
        con.close()
        raise HTTPException(409, "La puntata è già stata chiusa")
    con.execute("INSERT INTO rimborsi_asta(annuncio_id,tg_id,puntata_id,"
                "importo_sats,motivo,stato,creato,aggiornato) "
                "VALUES(?,?,?,?,'ritiro','da_riscuotere',?,?)",
                (annuncio_id, user["id"], p["id"], p["versato_sats"],
                 adesso, adesso))
    rid = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.commit()
    con.close()
    esito = await _paga_rimborso(rid)
    return {"ok": True, "importo_sats": p["versato_sats"],
            "riscosso": bool(esito.get("ok"))}


@app.post("/api/aste/{annuncio_id}/ritira-eccedenza")
async def ritira_eccedenza(annuncio_id: int,
                           x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """Il leader proxy ritira il budget NON esposto (ago 2026): la
    puntata torna SECCA (proxy=0, versato=offerto) e su quest'asta il
    massimo non si ricostruisce — «scesa l'eccedenza non risale», con
    la stessa definitività del ritiro; i rilanci normali restano
    aperti. UNA volta per asta: l'indice parziale su
    (puntata_id, motivo='eccedenza_ritiro') e' insieme cintura
    d'idempotenza e regola. Solo il leader: chi non e' in testa ha
    l'esposto pari al versato per costruzione (il motore lo ha gia'
    esposto tutto) e la sua strada e' il ritiro intero. Fuori dal gate
    di ASTA_ABILITATA e di ASTA_PROXY_ATTIVO, per scelta: uscire coi
    propri sats non dipende da una leva. Il gemello di ritira_puntata:
    stesse guardie, stessa transazione, riscossione post-commit."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    adesso = int(time.time())
    a = con.execute("SELECT * FROM annunci WHERE id=?",
                    (annuncio_id,)).fetchone()
    if (not a or a["stato"] != "attivo" or not _asta(a)
            or not _asta_viva(a, adesso)):
        # ad asta chiusa l'eccedenza torna da sola con la chiusura
        # (la riga 'eccedenza' del conto): niente doppie strade
        con.close()
        raise HTTPException(409, "L'asta è chiusa: l'eventuale "
                                 "eccedenza torna con la chiusura")
    p = con.execute("SELECT * FROM puntate WHERE annuncio_id=? AND tg_id=?",
                    (annuncio_id, user["id"])).fetchone()
    if not p or p["stato"] != "attiva" or not p["proxy"]:
        con.close()
        raise HTTPException(400, "Non hai un rilancio automatico su "
                                 "questa asta")
    eccedenza = p["versato_sats"] - p["offerto_sats"]
    if eccedenza <= 0:
        con.close()
        raise HTTPException(400, "Non c'è eccedenza da ritirare: il "
                                 "tuo massimo è già tutto esposto")
    testa = _leader_asta(con, annuncio_id)
    if not (testa and testa["id"] == p["id"]):
        con.close()
        raise HTTPException(400, "Non sei in testa: chi non guida "
                                 "l'asta si ritira per intero, col "
                                 "bottone di sempre")
    pendente = con.execute("SELECT 1 FROM rilanci WHERE puntata_id=? AND "
                           "stato='creato' AND creato>=?",
                           (p["id"], adesso - RILANCIO_STANTIO)).fetchone()
    if pendente:
        # un top-up in volo tra il conto dell'eccedenza e il commit
        # sballerebbe i numeri: prima si chiude quella fattura
        con.close()
        raise HTTPException(400, "Hai una fattura di puntata in corso: "
                                 "pagala o lascia che scada, poi potrai "
                                 "ritirare l'eccedenza")
    # il CAS sui VALORI oltre che sullo stato: mono-processo e zero
    # await, ma la cintura non costa niente
    cur = con.execute("UPDATE puntate SET versato_sats=offerto_sats, "
                      "proxy=0, aggiornato=? WHERE id=? AND "
                      "stato='attiva' AND versato_sats=? AND "
                      "offerto_sats=?",
                      (adesso, p["id"], p["versato_sats"],
                       p["offerto_sats"]))
    if cur.rowcount == 0:
        con.close()
        raise HTTPException(409, "La puntata è cambiata proprio "
                                 "adesso: riprova")
    con.execute("INSERT OR IGNORE INTO rimborsi_asta(annuncio_id,tg_id,"
                "puntata_id,importo_sats,motivo,stato,creato,aggiornato) "
                "VALUES(?,?,?,?,'eccedenza_ritiro','da_riscuotere',?,?)",
                (annuncio_id, user["id"], p["id"], eccedenza,
                 adesso, adesso))
    if con.execute("SELECT changes() AS n").fetchone()["n"] == 0:
        # l'indice parziale ha parlato: era gia' stata ritirata
        con.rollback()
        con.close()
        raise HTTPException(409, "L'eccedenza si ritira una volta sola")
    rid = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.commit()
    con.close()
    esito = await _paga_rimborso(rid)
    return {"ok": True, "importo_sats": eccedenza,
            "riscosso": bool(esito.get("ok"))}


@app.post("/api/rimborsi/{rimborso_id}/invoice")
async def deposita_invoice_rimborso(rimborso_id: int, req: Request,
                                    x_tg_init_data: str = Header(""),
                                    barattolo_sessione: str = Cookie("")):
    """Il ripiego del binario (gemello di deposita_invoice sugli
    ordini): chi non ha — o non ha piu' — un Lightning address incolla
    una invoice dell'importo ESATTO e la riscossione riparte subito."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    bolt11 = (d.get("invoice") or "").strip()
    if not bolt11.lower().startswith("ln"):
        raise HTTPException(400, "Questa non sembra una invoice Lightning")
    con = db()
    r = con.execute("SELECT * FROM rimborsi_asta WHERE id=? AND tg_id=?",
                    (rimborso_id, user["id"])).fetchone()
    if not r or r["stato"] != "da_riscuotere":
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    importo_sats = await importo_invoice(bolt11)
    if importo_sats is None:
        con.close()
        raise HTTPException(400, "Invoice non valida o illeggibile")
    if importo_sats != r["importo_sats"]:
        con.close()
        raise HTTPException(400,
            f"Importo sbagliato: la invoice è di {importo_sats} sats, "
            f"deve essere esattamente {r['importo_sats']} sats "
            f"(rimborso integrale)")
    con.execute("UPDATE rimborsi_asta SET invoice_riscossione=?, "
                "aggiornato=? WHERE id=?",
                (bolt11, int(time.time()), rimborso_id))
    con.commit()
    con.close()
    return await _paga_rimborso(rimborso_id)


# ----------------------- ASTE: la chiusura ---------------------------
# L'asta finisce esattamente dove oggi inizia un ordine: la puntata in
# testa diventa un ordine GIA' pagato (crea_ordine_pagato), i perdenti
# vanno nel registro «Da riscuotere», e da li' in poi e' il ciclo di
# vita di sempre. La chiusura puo' morire a meta' ed essere rilanciata
# senza doppioni: ogni asta e' UNA transazione, e il commit la porta
# fuori dalla SELECT in un colpo.

def _strade_asta(a) -> set:
    """Le strade che l'asta offre al vincitore (tutte a costo zero,
    per regola: la spedizione e' inclusa nel prezzo). La scelta
    avviene DENTRO l'ordine, dal varco esistente. NIENTE via del
    punto di ritiro, dichiarato (ago 2026, busta di consegna): qui il
    vincitore sceglie solo la STRADA e scegli_consegna_ordine non
    scrive mai via_punto, quindi gli ordini d'asta non hanno mai la
    busta — se un giorno servira', e' un cantiere suo (via e punto
    dentro la scelta del vincitore)."""
    strade = set()
    if a["consegna"] in ("spedizione", "entrambe"):
        strade.add("spedizione")
    if a["consegna"] in ("ritiro", "entrambe"):
        strade.add("ritiro")
    if a["consegna"] == "digitale" or a["anche_digitale"]:
        strade.add("digitale")
    return strade


def _chiudi_una_asta(annuncio_id: int, cambio: float):
    """La chiusura di UNA asta, in UNA transazione senza await.
    Il RICONTROLLO della scadenza sta DENTRO (decisione di Andrea):
    una proroga puo' arrivare tra la SELECT del giro e questa
    lavorazione, e l'asta prorogata si salva — la riprendera' il giro
    giusto. Idempotente: crash prima del commit = rollback e si rifa';
    crash dopo = le righe 'da_riscuotere' le recuperano riscossioni,
    scandaglio e solleciti (mai perse, non istantanee — dichiarato).
    Ritorna il racconto per le notifiche, None = niente da fare."""
    adesso = int(time.time())
    con = db()
    con.execute("BEGIN IMMEDIATE")
    a = con.execute("SELECT * FROM annunci WHERE id=?",
                    (annuncio_id,)).fetchone()
    if (not a or a["stato"] != "attivo" or a["asta_base_sats"] <= 0
            or a["asta_scadenza"] == 0 or a["asta_scadenza"] > adesso):
        con.rollback()
        con.close()
        return None
    puntate = [dict(r) for r in con.execute(
        "SELECT * FROM puntate WHERE annuncio_id=?", (annuncio_id,))]
    vincitrice, rimborsi = conto_chiusura(puntate)
    if not vincitrice:
        # DESERTA: torna in mano al venditore — scadenza azzerata,
        # base intatta. Non comprabile finche' non decide (_asta()
        # tiene spento l'acquisto): rilancia o converte a prezzo
        # fisso, dalla sua scheda.
        con.execute("UPDATE annunci SET asta_scadenza=0, "
                    "asta_avvisata_1h=0 WHERE id=?", (annuncio_id,))
        con.commit()
        con.close()
        return {"tipo": "deserta", "annuncio": dict(a)}
    ultimo = con.execute(
        "SELECT payment_hash FROM rilanci WHERE puntata_id=? AND "
        "stato='saldato' ORDER BY saldato_il DESC, id DESC LIMIT 1",
        (vincitrice["id"],)).fetchone()
    payment_hash = ultimo["payment_hash"] if ultimo else \
        f"asta-{annuncio_id}-{vincitrice['tg_id']}"
    strade = _strade_asta(a)
    scelta = strade.pop() if len(strade) == 1 else ""
    # il vincitore paga l'ESPOSTO, mai il budget (il proxy, ago 2026):
    # l'eventuale eccedenza e' una riga del conto e torna dal registro
    ordine_id = crea_ordine_pagato(con, a, vincitrice["tg_id"],
                                   vincitrice["offerto_sats"],
                                   payment_hash, scelta, cambio)
    con.execute("UPDATE puntate SET stato='vincitrice', aggiornato=? "
                "WHERE id=?", (adesso, vincitrice["id"]))
    for rmb in rimborsi:
        # INSERT OR IGNORE: la cintura d'idempotenza (indici parziali
        # su puntata_id, uno per motivo) para anche il doppio giro
        con.execute("INSERT OR IGNORE INTO rimborsi_asta(annuncio_id,"
                    "tg_id,puntata_id,importo_sats,motivo,stato,creato,"
                    "aggiornato) VALUES(?,?,?,?,?,"
                    "'da_riscuotere',?,?)",
                    (annuncio_id, rmb["tg_id"], rmb["puntata_id"],
                     rmb["importo_sats"], rmb["motivo"], adesso, adesso))
    con.execute("UPDATE puntate SET stato='chiusa', aggiornato=? "
                "WHERE annuncio_id=? AND stato='attiva' AND id!=?",
                (adesso, annuncio_id, vincitrice["id"]))
    # invariante di sempre: venduto <=> quantita 0. asta_scadenza
    # resta com'e' (storico); lo stato 'venduto' toglie l'asta dalla
    # SELECT della chiusura. Niente Nostr e niente canale: quest'asta
    # non e' mai stata in piazza.
    con.execute("UPDATE annunci SET stato='venduto', quantita=0, "
                "asta_avvisata_1h=0 WHERE id=?", (annuncio_id,))
    perdenti = [dict(r) for r in con.execute(
        "SELECT id, tg_id FROM rimborsi_asta WHERE annuncio_id=? AND "
        "motivo='perdente' AND stato='da_riscuotere'", (annuncio_id,))]
    # l'eccedenza della vincitrice (se il suo budget superava
    # l'esposto): si racconta e si paga a parte — non e' una perdente
    ecc = con.execute(
        "SELECT id, tg_id, importo_sats FROM rimborsi_asta WHERE "
        "puntata_id=? AND motivo='eccedenza' AND stato='da_riscuotere'",
        (vincitrice["id"],)).fetchone()
    con.commit()
    con.close()
    return {"tipo": "vinta", "annuncio": dict(a), "ordine_id": ordine_id,
            "vincitrice": dict(vincitrice), "perdenti": perdenti,
            "eccedenza": dict(ecc) if ecc else None, "scelta": scelta}


async def _racconta_chiusura(esito: dict):
    """Notifiche e riscossioni DOPO il commit, mai dentro."""
    a = esito["annuncio"]
    titolo = a["titolo"][:60]
    if esito["tipo"] == "deserta":
        await notifica(a["venditore_id"],
            f"🔨 <b>L'asta «{titolo}» si è chiusa senza offerte.</b> "
            f"L'annuncio è tornato a te: dalla sua scheda puoi "
            f"rilanciare l'asta o convertirlo a prezzo fisso alla base "
            f"({_fmt_sats(a['asta_base_sats'])} sats).")
        return
    v = esito["vincitrice"]
    # il prezzo raccontato e' l'ESPOSTO (= il prezzo dell'ordine), mai
    # il versato: col proxy il versato e' il budget, e il racconto non
    # deve contraddire l'ordine ne' dire il massimo di nessuno
    ecc = esito.get("eccedenza")
    await notifica(v["tg_id"],
        f"🏆 <b>Hai vinto l'asta!</b> «{titolo}» è tuo per "
        f"{_fmt_sats(v['offerto_sats'])} sats — già pagati, al sicuro "
        f"nel deposito di garanzia. "
        + (f"I {_fmt_sats(ecc['importo_sats'])} sats non esposti del "
           f"tuo budget tornano indietro adesso. " if ecc else "")
        + ("Apri l'ordine e scegli come riceverlo."
           if not esito["scelta"] else
           "Il venditore prepara la consegna: segui l'ordine come "
           "sempre."))
    await notifica(a["venditore_id"],
        f"🔨 <b>Asta conclusa!</b> «{titolo}» è stato aggiudicato a "
        f"{_fmt_sats(v['offerto_sats'])} sats "
        f"(ordine #{esito['ordine_id']}). "
        + ("Il vincitore sta scegliendo come riceverlo: ti avviso io "
           "appena decide." if not esito["scelta"] else
           "Prepara la consegna dal pannello dell'ordine."))
    await polso_ordini_admin(
        f"🔨 <b>Asta conclusa:</b> «{titolo}» — "
        f"{_fmt_sats(v['offerto_sats'])} sats in cassaforte "
        f"(ordine #{esito['ordine_id']}). "
        f"Restano {{aperti}} ordini aperti.")
    for rmb in esito["perdenti"]:
        try:
            await notifica(rmb["tg_id"],
                f"🔨 L'asta «{titolo}» si è conclusa a "
                f"{_fmt_sats(v['offerto_sats'])} sats: non hai vinto. "
                f"Il tuo versato torna indietro adesso.")
        except Exception:
            pass
        await _paga_rimborso(rmb["id"])   # racconta da solo l'esito
    if ecc:
        # la riscossione dell'eccedenza del vincitore: gia' annunciata
        # nel suo 🏆, qui parte e basta
        await _paga_rimborso(ecc["id"])


async def chiudi_aste():
    """Il lavoro pianificato della chiusura (stesso telaio dei timer
    di auto-sblocco): trova le scadute e le chiude una a una, ognuna
    nella SUA transazione. Gira ANCHE a leva spenta: le aste vive non
    restano ostaggio di ASTA_ABILITATA. Il jitter del tick (10 min)
    ritarda solo l'aggiudicazione: i rilanci tardivi li ferma il read
    gate, mai l'orologio."""
    adesso = int(time.time())
    con = db()
    scadute = [r["id"] for r in con.execute(
        "SELECT id FROM annunci WHERE stato='attivo' AND "
        "asta_base_sats>0 AND asta_scadenza>0 AND asta_scadenza<=?",
        (adesso,))]
    con.close()
    if scadute:
        # il cambio UNA volta, PRIMA delle transazioni (mai un await
        # dentro): diventa il cambio_ordine dell'ordine gia' pagato
        cambio = await cambio_btc_eur()
        for aid in scadute:
            esito = _chiudi_una_asta(aid, cambio)
            if esito:
                try:
                    await _racconta_chiusura(esito)
                except Exception as e:
                    print(f"⚠️ Racconto chiusura asta #{aid} saltato: {e}")
    await _avvisa_aste_in_scadenza()


async def _avvisa_aste_in_scadenza():
    """L'avviso «si chiude tra un'ora» ai partecipanti: il timbro
    asta_avvisata_1h si scrive PRIMA delle notifiche (il pattern del
    cooldown del colpo) e non si ripete mai; col tick da 10 minuti
    arriva a 60±10 minuti dalla fine. Una proroga oltre l'ora NON
    riarma l'avviso: dichiarato."""
    adesso = int(time.time())
    con = db()
    aste = [dict(r) for r in con.execute(
        "SELECT id, titolo, asta_scadenza FROM annunci WHERE "
        "stato='attivo' AND asta_base_sats>0 AND asta_avvisata_1h=0 "
        "AND asta_scadenza>? AND asta_scadenza<=?",
        (adesso, adesso + 3600))]
    if not aste:
        con.close()
        return
    avvisi = []
    for a in aste:
        con.execute("UPDATE annunci SET asta_avvisata_1h=1 WHERE id=?",
                    (a["id"],))
        for p in con.execute("SELECT tg_id FROM puntate WHERE "
                             "annuncio_id=? AND stato='attiva' AND "
                             "versato_sats>0", (a["id"],)):
            avvisi.append((p["tg_id"], a))
    con.commit()
    con.close()
    for tg, a in avvisi:
        try:
            await notifica(tg,
                f"⏳ <b>L'asta «{a['titolo'][:60]}» si chiude tra circa "
                f"un'ora.</b> Controlla la tua posizione: un rilancio "
                f"all'ultimo prolunga la gara di {ASTA_PROROGA_MINUTI} "
                f"minuti.\n{URL_PUBBLICO}/annuncio/{a['id']}")
        except Exception as e:
            print(f"⚠️ Avviso scadenza asta saltato: {e}")


@app.post("/api/aste/{annuncio_id}/rilancia")
async def rilancia_asta_deserta(annuncio_id: int, req: Request,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """La deserta torna in gara: solo il venditore, solo su un'asta
    ferma (base intatta, scadenza a zero), con le durate di sempre e
    il tetto delle aste vive. Registro e puntate chiuse restano
    storia."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    secondi = durata_asta_da_payload({"asta": d})
    if not secondi:
        raise HTTPException(400, "Indica la durata dell'asta")
    con = db()
    adesso = int(time.time())
    a = con.execute("SELECT * FROM annunci WHERE id=? AND venditore_id=? "
                    "AND stato='attivo'", (annuncio_id, user["id"])).fetchone()
    if not a or a["asta_base_sats"] <= 0 or a["asta_scadenza"] != 0:
        con.close()
        raise HTTPException(400, "Si rilancia solo un'asta chiusa senza "
                                 "offerte")
    # Rimettere in gara e' aprire un'asta nuova: stessa guardia.
    guardia_ferie_venditore(con, user["id"], "rilancerai l'asta")
    vive = con.execute(
        "SELECT COUNT(*) AS n FROM annunci WHERE venditore_id=? "
        "AND stato IN ('attivo','revisione') AND asta_base_sats>0 "
        "AND asta_scadenza>?", (user["id"], adesso)).fetchone()["n"]
    if vive >= ASTA_MAX_ATTIVE_VENDITORE:
        con.close()
        raise HTTPException(400, f"Hai già {ASTA_MAX_ATTIVE_VENDITORE} "
                                 f"aste in corso: chiudine una prima di "
                                 f"aprirne un'altra")
    con.execute("UPDATE annunci SET asta_scadenza=?, asta_creato=?, "
                "asta_avvisata_1h=0 WHERE id=?",
                (adesso + secondi, adesso, annuncio_id))
    con.commit()
    con.close()
    return {"ok": True, "asta_scadenza": adesso + secondi}


@app.post("/api/aste/{annuncio_id}/converti")
async def converti_asta(annuncio_id: int,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Da asta a prezzo fisso, alla base: la deserta sempre, l'asta
    ancora viva solo SENZA puntate salde (regola del cantiere: senza
    puntate il venditore puo' annullarla — convertirla e' l'annullo
    che conserva l'annuncio). Con puntate salde: vincolante."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=? AND venditore_id=? "
                    "AND stato='attivo'", (annuncio_id, user["id"])).fetchone()
    if not a or a["asta_base_sats"] <= 0:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if _puntate_attive_salde(con, annuncio_id):
        con.close()
        raise HTTPException(400, "L'asta ha già delle puntate ed è "
                                 "vincolante: si chiude da sola alla "
                                 "scadenza")
    con.execute("UPDATE annunci SET asta_base_sats=0, asta_scadenza=0, "
                "asta_creato=0, asta_avvisata_1h=0 WHERE id=?",
                (annuncio_id,))
    con.commit()
    con.close()
    return {"ok": True, "prezzo_sats": a["prezzo_sats"]}


@app.post("/api/admin/aste/{annuncio_id}/annulla")
async def annulla_asta_admin(annuncio_id: int,
                             x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN (il caso moderazione): l'annullo d'asta scioglie la
    gara — tutte le puntate salde finiscono in «Da riscuotere» — e
    azzera le colonne asta; l'annuncio resta, e se va rimosso passa
    dalla rimozione ordinaria (che ora non trova piu' puntate)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    con.execute("BEGIN IMMEDIATE")
    adesso = int(time.time())
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato IN "
                    "('attivo','revisione')", (annuncio_id,)).fetchone()
    if not a or a["asta_base_sats"] <= 0:
        con.rollback()
        con.close()
        raise HTTPException(400, "Asta non trovata (o già chiusa)")
    salde = [dict(r) for r in con.execute(
        "SELECT id, tg_id, versato_sats FROM puntate WHERE annuncio_id=? "
        "AND stato='attiva' AND versato_sats>0", (annuncio_id,))]
    for p in salde:
        con.execute("INSERT OR IGNORE INTO rimborsi_asta(annuncio_id,"
                    "tg_id,puntata_id,importo_sats,motivo,stato,creato,"
                    "aggiornato) VALUES(?,?,?,?,'annullo_admin',"
                    "'da_riscuotere',?,?)",
                    (annuncio_id, p["tg_id"], p["id"], p["versato_sats"],
                     adesso, adesso))
    con.execute("UPDATE puntate SET stato='chiusa', aggiornato=? "
                "WHERE annuncio_id=? AND stato='attiva'",
                (adesso, annuncio_id))
    con.execute("UPDATE annunci SET asta_base_sats=0, asta_scadenza=0, "
                "asta_creato=0, asta_avvisata_1h=0 WHERE id=?",
                (annuncio_id,))
    rimborsi = [dict(r) for r in con.execute(
        "SELECT id, tg_id, importo_sats FROM rimborsi_asta WHERE "
        "annuncio_id=? AND motivo='annullo_admin' AND "
        "stato='da_riscuotere'", (annuncio_id,))]
    con.commit()
    con.close()
    registra_moderazione("admin", "asta_annullata", "", a["titolo"],
                         annuncio_id, a["venditore_id"], user["id"])
    titolo = a["titolo"][:60]
    await notifica(a["venditore_id"],
                   f"🛡 <b>L'asta «{titolo}» è stata annullata dai "
                   f"moderatori.</b> I puntatori vengono rimborsati; "
                   f"l'annuncio resta a prezzo fisso.")
    for rmb in rimborsi:
        try:
            await notifica(rmb["tg_id"],
                f"🛡 L'asta «{titolo}» è stata annullata dai "
                f"moderatori: il tuo versato torna indietro adesso.")
        except Exception:
            pass
        await _paga_rimborso(rmb["id"])
    return {"ok": True, "rimborsati": len(rimborsi)}


@app.post("/api/admin/aste/{annuncio_id}/chiudi-ora")
async def chiudi_asta_ora(annuncio_id: int,
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """SOLO COLLAUDO: chiude l'asta adesso, passando dalla STESSA
    chiusura dell'orologio — per provare il ciclo intero senza
    aspettare giorni."""
    if not MODALITA_COLLAUDO:
        raise HTTPException(404, "Non esiste")
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    cur = con.execute("UPDATE annunci SET asta_scadenza=? WHERE id=? "
                      "AND stato='attivo' AND asta_base_sats>0 AND "
                      "asta_scadenza>0", (int(time.time()) - 1,
                                          annuncio_id))
    con.commit()
    con.close()
    if cur.rowcount == 0:
        raise HTTPException(400, "Nessuna asta viva da chiudere qui")
    cambio = await cambio_btc_eur()
    esito = _chiudi_una_asta(annuncio_id, cambio)
    if esito:
        await _racconta_chiusura(esito)
    return {"ok": True, "esito": esito["tipo"] if esito else "niente"}


@app.post("/api/orders/{ordine_id}/consegna")
async def scegli_consegna_ordine(ordine_id: int, req: Request,
                                 x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """Il vincitore dell'asta sceglie la strada DENTRO l'ordine (dal
    varco esistente): solo il compratore, solo su 'locked' con la
    scelta ancora vuota, solo fra le strade che l'annuncio offre.
    Finche' non sceglie, il venditore vede «in attesa della scelta»
    e non puo' spedire ne' consegnare: nessuna finestra di tutela
    parte prima della scelta (decisione di Andrea)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelta = (d.get("consegna") or "").strip()
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato='locked'", (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if o["consegna_scelta"]:
        con.close()
        raise HTTPException(400, "La strada di consegna è già scelta")
    a = con.execute("SELECT * FROM annunci WHERE id=?",
                    (o["annuncio_id"],)).fetchone()
    if not a or a["asta_base_sats"] <= 0:
        # gli ordini STORICI con consegna '' restano il flusso di
        # sempre: questa porta e' solo del vincitore d'asta
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if scelta not in _strade_asta(a):
        con.close()
        raise HTTPException(400, "Questa strada non è offerta "
                                 "dall'annuncio")
    con.execute("UPDATE ordini SET consegna_scelta=?, aggiornato=? "
                "WHERE id=?", (scelta, int(time.time()), ordine_id))
    con.commit()
    con.close()
    NOMI = {"spedizione": "spedizione (inclusa nel prezzo)",
            "ritiro": "ritiro in zona", "digitale": "codice online"}
    await notifica(a["venditore_id"],
                   f"📦 <b>Il vincitore ha scelto: "
                   f"{NOMI.get(scelta, scelta)}.</b> «{a['titolo'][:60]}» "
                   f"— prepara la consegna dal pannello dell'ordine "
                   f"#{ordine_id}.")
    return {"ok": True, "consegna": scelta}


@app.post("/api/listings/{annuncio_id}/offerta")
async def fai_offerta(annuncio_id: int, req: Request,
                      x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    """Il compratore propone la sua cifra, nella valuta del listino.
    Qui il cambio non serve mai: offerta e listino si confrontano
    nella stessa valuta (la conversione, per i listini EUR, avviene
    solo alla creazione della invoice, come sempre)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato='attivo'",
                    (annuncio_id,)).fetchone()
    if not a:
        con.close()
        raise HTTPException(404, "Annuncio non disponibile")
    if a["venditore_id"] == user["id"]:
        con.close()
        raise HTTPException(400, "Non puoi fare un'offerta sul tuo "
                                 "stesso annuncio")
    # In ferie non si tratta: il venditore non e' li' a rispondere, e
    # un'offerta che scade da sola in 48 ore sarebbe solo un'attesa.
    guardia_ferie(con, a["venditore_id"])
    if _asta(a):
        con.close()
        raise HTTPException(400, "Questo oggetto è all'asta: l'offerta "
                                 "giusta è una puntata 🔨")
    # Gli importati da Nostr sono trattabili come tutti: il venditore
    # solo-Nostr riceve l'offerta via DM NIP-17 col link all'annuncio,
    # entra col login Nostr e risponde da qui.
    # La cifra, nella valuta del listino (EUR con la virgola tradotta)
    grezzo = str(d.get("importo", "")).strip()
    imp_sats, imp_eur = 0, 0.0
    if a["valuta"] == "eur":
        try:
            imp_eur = round(float(grezzo.replace(",", ".")), 2)
        except ValueError:
            imp_eur = 0.0
        importo, listino = imp_eur, a["prezzo_eur"]
    else:
        try:
            imp_sats = int(float(grezzo))
        except ValueError:
            imp_sats = 0
        importo, listino = imp_sats, a["prezzo_sats"]
    if importo <= 0:
        con.close()
        raise HTTPException(400, "Importo non valido")
    if importo >= listino:
        con.close()
        raise HTTPException(400, "La tua offerta è pari o superiore al "
                                 "prezzo dell'annuncio: puoi comprare "
                                 "direttamente 🙂")
    # Il paletto anti-offerte-insulto: sotto la soglia non si parte.
    # Sui sats il minimo si arrotonda per ECCESSO (mai un'offerta
    # ammessa sotto la percentuale promessa al venditore).
    if a["valuta"] == "eur":
        minimo = round(listino * OFFERTA_MINIMA_PERCENTO / 100, 2)
    else:
        minimo = (listino * OFFERTA_MINIMA_PERCENTO + 99) // 100
    if importo < minimo:
        con.close()
        raise HTTPException(400, "Le offerte per questo annuncio partono "
                                 f"da {_cifra_offerta(a['valuta'], minimo, minimo)}")
    # Le due guardie di conteggio: una offerta attiva alla volta, e un
    # numero chiuso di tentativi totali. Niente await tra i COUNT e
    # l'INSERT: nel server mono-processo il blocco e' atomico (il
    # patto anti-doppione di pubblica e del barattolo).
    attive = con.execute(
        "SELECT COUNT(*) AS n FROM offerte WHERE annuncio_id=? AND "
        "compratore_id=? AND stato IN ('proposta','controproposta',"
        "'accettata')", (annuncio_id, user["id"])).fetchone()["n"]
    if attive:
        con.close()
        raise HTTPException(400, "Hai già un'offerta in corso su questo "
                                 "annuncio: aspetta la risposta del "
                                 "venditore")
    totali = con.execute(
        "SELECT COUNT(*) AS n FROM offerte WHERE annuncio_id=? AND "
        "compratore_id=?", (annuncio_id, user["id"])).fetchone()["n"]
    if totali >= MAX_OFFERTE_ANNUNCIO:
        con.close()
        raise HTTPException(400, f"Hai già fatto {MAX_OFFERTE_ANNUNCIO} "
                                 "offerte su questo annuncio: è il "
                                 "momento del prezzo pieno 🙂")
    adesso = int(time.time())
    scadenza = adesso + ORE_RISPOSTA_OFFERTA * 3600
    con.execute(
        "INSERT INTO offerte(annuncio_id,compratore_id,venditore_id,"
        "valuta,importo_sats,importo_eur,stato,scadenza,creato,aggiornato) "
        "VALUES(?,?,?,?,?,?,?,?,?,?)",
        (annuncio_id, user["id"], a["venditore_id"], a["valuta"],
         imp_sats, imp_eur, "proposta", scadenza, adesso, adesso))
    con.commit()
    offerta_id = con.execute(
        "SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.close()
    # La notifica DOPO il commit, come sempre
    await notifica(a["venditore_id"],
        f"💰 <b>Hai ricevuto un'offerta!</b> Qualcuno ti offre "
        f"{_cifra_offerta(a['valuta'], imp_sats, imp_eur)} per "
        f"«{a['titolo'][:60]}» (listino "
        f"{_cifra_offerta(a['valuta'], a['prezzo_sats'], a['prezzo_eur'])}). "
        f"Rispondi dalla scheda Ordini: puoi accettare, rifiutare o fare "
        f"una controproposta. Senza risposta entro "
        f"{ORE_RISPOSTA_OFFERTA} ore l'offerta scade da sola."
        f"\n{URL_PUBBLICO}/annuncio/{annuncio_id}")
    return {"ok": True, "offerta_id": offerta_id, "scadenza": scadenza}


@app.get("/api/me/offerte")
def mie_offerte(x_tg_init_data: str = Header(""),
                barattolo_sessione: str = Cookie("")):
    """Le offerte in cui sono una delle parti, dalle piu' fresche.
    La busta porta anche le leve: il client non hardcoda mai le cifre."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    righe = con.execute(
        "SELECT o.*, a.titolo, a.foto, a.stato AS stato_annuncio, "
        "a.prezzo_sats AS listino_sats, a.prezzo_eur AS listino_eur, "
        "a.consegna, uc.nome AS compratore_nome, uv.nome AS venditore_nome "
        "FROM offerte o "
        "JOIN annunci a ON a.id = o.annuncio_id "
        "LEFT JOIN utenti uc ON uc.tg_id = o.compratore_id "
        "LEFT JOIN utenti uv ON uv.tg_id = o.venditore_id "
        "WHERE o.compratore_id=? OR o.venditore_id=? "
        "ORDER BY o.aggiornato DESC LIMIT 30",
        (user["id"], user["id"])).fetchall()
    con.close()
    return {"offerte": [dict(r) for r in righe],
            "minima_percento": OFFERTA_MINIMA_PERCENTO,
            "ore_risposta": ORE_RISPOSTA_OFFERTA,
            "ore_pagamento": ORE_PAGAMENTO_OFFERTA,
            "max_offerte": MAX_OFFERTE_ANNUNCIO}


@app.post("/api/offerte/{offerta_id}/rispondi")
async def rispondi_offerta(offerta_id: int, req: Request,
                           x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """La mossa sull'offerta. Su una proposta muove il VENDITORE
    (accetta, rifiuta o fa la sua UNICA controproposta); su una
    controproposta muove il COMPRATORE (accetta o rifiuta, il
    ping-pong finisce qui). Accettare apre la finestra di pagamento —
    ma non riserva l'oggetto: l'annuncio resta in vetrina."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    azione = d.get("azione", "")
    con = db()
    off = con.execute(
        "SELECT o.*, a.stato AS stato_annuncio, a.titolo, "
        "a.prezzo_sats AS listino_sats, a.prezzo_eur AS listino_eur "
        "FROM offerte o JOIN annunci a ON a.id = o.annuncio_id "
        "WHERE o.id=?", (offerta_id,)).fetchone()
    if not off:
        con.close()
        raise HTTPException(404, "Offerta non trovata")
    adesso = int(time.time())
    # La scadenza si controlla anche qui, non solo nell'orologio: chi
    # risponde a un'offerta gia' morta merita un no onesto subito.
    if off["stato"] in STATI_OFFERTA_VIVI and 0 < off["scadenza"] < adesso:
        con.execute("UPDATE offerte SET stato='scaduta', aggiornato=? "
                    "WHERE id=?", (adesso, offerta_id))
        con.commit()
        con.close()
        raise HTTPException(400, "Questa offerta è scaduta")
    # Chi puo' fare cosa dipende dallo stato: il protocollo e' rigido
    # apposta (non e' una chat).
    if off["stato"] == "proposta":
        chi_muove, ammesse = off["venditore_id"], ("accetta", "rifiuta",
                                                   "contro")
    elif off["stato"] == "controproposta":
        chi_muove, ammesse = off["compratore_id"], ("accetta", "rifiuta")
    else:
        con.close()
        raise HTTPException(400, "Questa offerta è già chiusa")
    if user["id"] != chi_muove or azione not in ammesse:
        con.close()
        raise HTTPException(400, "Operazione non permessa")

    titolo = off["titolo"][:60]
    link = f"\n{URL_PUBBLICO}/annuncio/{off['annuncio_id']}"
    cifra_proposta = _cifra_offerta(off["valuta"], off["importo_sats"],
                                    off["importo_eur"])

    if azione == "accetta":
        # L'annuncio deve essere ancora in vetrina: su uno gia' venduto
        # o rimosso l'accordo non ha piu' oggetto.
        if off["stato_annuncio"] != "attivo":
            con.execute("UPDATE offerte SET stato='decaduta', aggiornato=? "
                        "WHERE id=?", (adesso, offerta_id))
            con.commit()
            con.close()
            raise HTTPException(400, "L'annuncio non è più disponibile")
        # CINTURA: per costruzione non ci si arriva — le offerte vive
        # decadono quando il negozio chiude, e in ferie non se ne
        # aprono di nuove. Ma un accordo stretto verso un negozio
        # chiuso sarebbe impagabile, ed e' il tipo di trappola che
        # vale una riga in piu'.
        guardia_ferie(con, off["venditore_id"])
        con.execute("UPDATE offerte SET stato='accettata', scadenza=?, "
                    "aggiornato=? WHERE id=?",
                    (adesso + ORE_PAGAMENTO_OFFERTA * 3600, adesso,
                     offerta_id))
        con.commit()
        con.close()
        if off["stato"] == "proposta":
            await notifica(off["compratore_id"],
                f"🎉 <b>Offerta accettata!</b> Puoi comprare «{titolo}» a "
                f"{cifra_proposta}: hai {ORE_PAGAMENTO_OFFERTA} ore per "
                f"pagare dalla scheda Ordini. I tuoi sats finiscono nel "
                f"deposito di garanzia, come sempre. Occhio: l'annuncio "
                f"resta in vetrina, se qualcuno paga il prezzo pieno prima "
                f"di te l'offerta decade.{link}")
        else:
            contro = _cifra_offerta(off["valuta"], off["contro_sats"],
                                    off["contro_eur"])
            await notifica(off["venditore_id"],
                f"🤝 La tua controproposta di {contro} per «{titolo}» è "
                f"stata accettata: l'acquirente ha "
                f"{ORE_PAGAMENTO_OFFERTA} ore per pagare. Ti avvisiamo "
                f"appena i sats sono nel deposito di garanzia.")
        return {"ok": True, "stato": "accettata"}

    if azione == "rifiuta":
        con.execute("UPDATE offerte SET stato='rifiutata', scadenza=0, "
                    "aggiornato=? WHERE id=?", (adesso, offerta_id))
        con.commit()
        con.close()
        if off["stato"] == "proposta":
            await notifica(off["compratore_id"],
                f"Il venditore ha rifiutato la tua offerta di "
                f"{cifra_proposta} per «{titolo}». Se vuoi puoi riprovare "
                f"con una cifra diversa, o comprare a prezzo pieno.{link}")
        else:
            await notifica(off["venditore_id"],
                f"L'acquirente ha rifiutato la tua controproposta per "
                f"«{titolo}». L'annuncio resta in vetrina come sempre.")
        return {"ok": True, "stato": "rifiutata"}

    # Controproposta: la cifra del venditore, sopra l'offerta ricevuta
    # e mai sopra il listino (a quel punto tanto vale il prezzo pieno).
    grezzo = str(d.get("importo", "")).strip()
    contro_sats, contro_eur = 0, 0.0
    if off["valuta"] == "eur":
        try:
            contro_eur = round(float(grezzo.replace(",", ".")), 2)
        except ValueError:
            contro_eur = 0.0
        contro, offerto, listino = (contro_eur, off["importo_eur"],
                                    off["listino_eur"])
    else:
        try:
            contro_sats = int(float(grezzo))
        except ValueError:
            contro_sats = 0
        contro, offerto, listino = (contro_sats, off["importo_sats"],
                                    off["listino_sats"])
    if contro <= offerto:
        con.close()
        raise HTTPException(400, "La controproposta deve superare "
                                 "l'offerta ricevuta — altrimenti "
                                 "accettala 🙂")
    if contro > listino:
        con.close()
        raise HTTPException(400, "La controproposta non può superare il "
                                 "prezzo dell'annuncio")
    con.execute("UPDATE offerte SET stato='controproposta', contro_sats=?, "
                "contro_eur=?, scadenza=?, aggiornato=? WHERE id=?",
                (contro_sats, contro_eur,
                 adesso + ORE_RISPOSTA_OFFERTA * 3600, adesso, offerta_id))
    con.commit()
    con.close()
    await notifica(off["compratore_id"],
        f"🤝 <b>Controproposta!</b> Per «{titolo}» il venditore ti propone "
        f"{_cifra_offerta(off['valuta'], contro_sats, contro_eur)} (avevi "
        f"offerto {cifra_proposta}). Accetta o rifiuta dalla scheda Ordini "
        f"entro {ORE_RISPOSTA_OFFERTA} ore.{link}")
    return {"ok": True, "stato": "controproposta"}


# ------------------------ API: OFFERTA LAMPO ------------------------
# Lo sconto a tempo su TUTTO l'annuncio (modello Vinted «sconto ai
# follower»): pubblico — chiunque compri nella finestra paga scontato —
# ma l'avviso arriva solo a chi ha l'annuncio nel barattolo, senza che
# il venditore sappia mai chi ne' quanti. Non tocca mai il listino:
# prezzo_sats/prezzo_eur restano pieni (e il NIP-99 con loro), lo
# sconto vive nelle colonne lampo_* e si applica alla invoice.

def _prezzo_lampo(a, percento: int):
    """Il prezzo scontato nella valuta del listino: (sats, eur), uno
    dei due a zero come nelle offerte. Mai sotto 1 sat / 0.01 €."""
    if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
        return 0, max(0.01, round(a["prezzo_eur"] * (100 - percento) / 100, 2))
    return max(1, a["prezzo_sats"] * (100 - percento) // 100), 0.0


def _quando_scade(ts: int) -> str:
    """«alle 18:30», «alle 18:30 di domani», «alle 18:30 del 02/08»:
    l'ora della scadenza detta come la direbbe una persona."""
    s = time.localtime(ts)
    oggi = time.localtime()
    ora = time.strftime("%H:%M", s)
    if (s.tm_year, s.tm_yday) == (oggi.tm_year, oggi.tm_yday):
        return f"alle {ora}"
    domani = time.localtime(time.time() + 86400)
    if (s.tm_year, s.tm_yday) == (domani.tm_year, domani.tm_yday):
        return f"alle {ora} di domani"
    return f"alle {ora} del {time.strftime('%d/%m', s)}"


async def _avvisa_savers_lampo(a: dict, percento: int, scadenza: int,
                               savers: list):
    """L'avviso ai barattoli: uno per uno e con calma, mai i nomi —
    nessuno sa chi altro ce l'ha nel barattolo. Fail-open: un errore
    qui non tocca la lampo, che e' gia' in vetrina."""
    try:
        s_sats, s_eur = _prezzo_lampo(a, percento)
        vecchio = _cifra_offerta(a["valuta"], a["prezzo_sats"],
                                 a["prezzo_eur"])
        nuovo = _cifra_offerta(a["valuta"], s_sats, s_eur)
        for tg in savers:
            await notifica(tg, (
                f"⚡ <b>L'annuncio nel tuo barattolo è in sconto!</b>\n"
                f"«{html.escape(a['titolo'][:60])}»: <s>{vecchio}</s> → "
                f"<b>{nuovo}</b> (−{percento}%)\n"
                f"Hai tempo fino {_quando_scade(scadenza)}.\n"
                f"{URL_PUBBLICO}/annuncio/{a['id']}"))
            await asyncio.sleep(0.2)
    except Exception as e:
        print(f"⚠️ Avvisi lampo saltati: {e}")


@app.post("/api/listings/{annuncio_id}/lampo")
async def lancia_lampo(annuncio_id: int, req: Request,
                       x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """Il venditore lancia lo sconto: percentuale e durata dalle
    opzioni del config. L'annuncio non si blocca e il listino non
    cambia; alla scadenza il prezzo torna pieno da solo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not LAMPO_ATTIVE:
        raise HTTPException(400, "Le offerte lampo non sono attive")
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato='attivo'",
                    (annuncio_id,)).fetchone()
    if not a:
        con.close()
        raise HTTPException(404, "Annuncio non disponibile")
    if a["venditore_id"] != user["id"]:
        con.close()
        raise HTTPException(403, "Solo il venditore può lanciare "
                                 "un'offerta lampo")
    # Uno sconto a tempo su una bottega chiusa e' una promessa che la
    # vetrina non mantiene: chi lo vede non puo' comprare.
    guardia_ferie_venditore(con, user["id"], "lancerai un'offerta lampo")
    if _asta(a):
        con.close()
        raise HTTPException(400, "Questo annuncio è all'asta: il prezzo "
                                 "lo fanno le puntate, niente sconti di "
                                 "mezzo")
    # Vale anche per gli importati da Nostr: lo sconto e' locale (le
    # colonne lampo_*, mai il listino), l'evento sui relay resta col
    # prezzo pieno e l'import orario non tocca la lampo.
    try:
        percento = int(d.get("percento", 0))
        ore = int(d.get("ore", 0))
    except (TypeError, ValueError):
        percento, ore = 0, 0
    if not (LAMPO_MIN_PERCENTO <= percento <= LAMPO_MAX_PERCENTO):
        con.close()
        raise HTTPException(400, f"Lo sconto va dal {LAMPO_MIN_PERCENTO}% "
                                 f"al {LAMPO_MAX_PERCENTO}%")
    if ore not in ORE_LAMPO_OPZIONI:
        con.close()
        raise HTTPException(400, "Durata non valida")
    adesso = int(time.time())
    if a["lampo_scadenza"] > adesso:
        con.close()
        raise HTTPException(400, "C'è già un'offerta lampo in corso su "
                                 "questo annuncio")
    # Il freno delle trattative: con un accordo gia' stretto (offerta
    # accettata in attesa di pagamento) niente lampo — il compratore
    # dell'accordo pagherebbe comunque il meglio dei due (compra() fa
    # il minimo), ma il venditore non deve potersi rimangiare la
    # stretta di mano cambiando le carte in tavola.
    accordo = con.execute(
        "SELECT COUNT(*) AS n FROM offerte WHERE annuncio_id=? AND "
        "stato='accettata' AND scadenza>?", (annuncio_id, adesso)).fetchone()["n"]
    if accordo:
        con.close()
        raise HTTPException(400, "C'è una trattativa accettata in corso: "
                                 "aspetta che si concluda o scada")
    # Il tetto settimanale: count-guard senza await (patto anti-doppione).
    lanci = con.execute(
        "SELECT COUNT(*) AS n FROM offerte_lampo WHERE annuncio_id=? AND "
        "creato>=?", (annuncio_id, adesso - 7 * 86400)).fetchone()["n"]
    if lanci >= MAX_LAMPO_SETTIMANA:
        con.close()
        raise HTTPException(400, f"Hai già lanciato {MAX_LAMPO_SETTIMANA} "
                                 "offerte lampo su questo annuncio negli "
                                 "ultimi 7 giorni: riprova più avanti")
    scadenza = adesso + ore * 3600
    con.execute("UPDATE annunci SET lampo_percento=?, lampo_scadenza=?, "
                "lampo_creato=? WHERE id=?",
                (percento, scadenza, adesso, annuncio_id))
    con.execute("INSERT INTO offerte_lampo(annuncio_id,venditore_id,"
                "percento,scadenza,creato) VALUES(?,?,?,?,?)",
                (annuncio_id, user["id"], percento, scadenza, adesso))
    con.commit()
    # I destinatari si leggono ORA (la lista e' gia' vera), l'invio va
    # in create_task: i relay Nostr sono lenti e la risposta no.
    savers = [r["tg_id"] for r in con.execute(
        "SELECT tg_id FROM preferiti WHERE annuncio_id=? AND tg_id!=?",
        (annuncio_id, user["id"]))]
    con.close()
    if savers:
        asyncio.create_task(
            _avvisa_savers_lampo(dict(a), percento, scadenza, savers))
    return {"ok": True, "percento": percento, "scadenza": scadenza}


@app.post("/api/listings/{annuncio_id}/lampo/annulla")
def annulla_lampo(annuncio_id: int, x_tg_init_data: str = Header(""),
                  barattolo_sessione: str = Cookie("")):
    """Il ripensamento del venditore: il prezzo torna pieno subito.
    Nessun avviso ai barattoli (sarebbe solo rumore) e il lancio resta
    nello storico: annullare non restituisce il gettone del tetto
    settimanale, altrimenti lancia-e-annulla sarebbe spam gratis."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    a = con.execute("SELECT venditore_id, lampo_scadenza FROM annunci "
                    "WHERE id=?", (annuncio_id,)).fetchone()
    if not a:
        con.close()
        raise HTTPException(404, "Annuncio non trovato")
    if a["venditore_id"] != user["id"]:
        con.close()
        raise HTTPException(403, "Solo il venditore può annullare")
    if a["lampo_scadenza"] <= int(time.time()):
        con.close()
        raise HTTPException(400, "Non c'è nessuna offerta lampo in corso")
    con.execute("UPDATE annunci SET lampo_percento=0, lampo_scadenza=0 "
                "WHERE id=?", (annuncio_id,))
    con.commit()
    con.close()
    return {"ok": True}


# ---------------------- API: ORDINI / ESCROW ------------------------

def _righe_ordine(con, o) -> list:
    """Le righe merceologiche dell'ordine, in UNA forma sola:
    [{annuncio_id, quantita, unitario_sats, titolo}]. Per i set
    (annuncio_id=0 in testata) le righe vere dalla tabella; per i
    mono UNA riga sintetizzata dalla testata — unitario =
    (prezzo - spedizione - protezione) / quantita, divisione esatta
    per costruzione (il patto della colonna quantita). Ogni punto che
    deve ciclare sugli oggetti dell'ordine passa da qui: nessuno
    puo' dimenticarsi dei set."""
    # Lo sconto carrello e' del SET e non passa MAI di qui: il mono non
    # ne ha (decisione di Andrea), ed e' anche il motivo per cui non ne
    # ha — uno sconto di testata romperebbe questa divisione in
    # silenzio, sbagliando l'unitario nell'ordine, nelle notifiche e
    # nel CSV. Se un giorno il mono lo avesse, qui va
    # (prezzo - spedizione - protezione + sconto_sats) // qta.
    if o["annuncio_id"]:
        t = con.execute("SELECT titolo FROM annunci WHERE id=?",
                        (o["annuncio_id"],)).fetchone()
        qta = o["quantita"] or 1
        unitario = (o["prezzo_sats"] - o["spedizione_sats"]
                    - o["protezione_sats"]) // qta
        return [{"annuncio_id": o["annuncio_id"], "quantita": qta,
                 "unitario_sats": unitario,
                 "titolo": t["titolo"] if t else "?"}]
    return [dict(r) for r in con.execute(
        "SELECT annuncio_id, quantita, unitario_sats, titolo "
        "FROM ordine_righe WHERE ordine_id=? ORDER BY id",
        (o["id"],)).fetchall()]


def _titolo_ordine(righe: list) -> str:
    """Il titolo di cortesia dell'ordine (notifiche, CSV, solleciti):
    quello dell'annuncio per i mono, «primo pezzo + N altri» per i
    set. Niente emoji: il 🫙 e' dei preferiti."""
    if not righe:
        return "?"
    if len(righe) == 1:
        return righe[0]["titolo"]
    return f"{righe[0]['titolo'][:40]} + {len(righe) - 1} altri"


def _ordini_vivi_annuncio(con, annuncio_id: int, stati: tuple,
                          esclusi: bool = False) -> int:
    """Il giudice unico delle guardie «affare in corso»: conta gli
    ordini che toccano l'annuncio come testata mono O come riga di
    un set — cosi' nessuna guardia puo' dimenticarsi delle righe.
    Con esclusi=True la tupla elenca gli stati TERMINALI da ignorare
    (la forma della guardia di modifica), altrimenti quelli vivi."""
    segnaposto = ",".join("?" * len(stati))
    verso = "NOT IN" if esclusi else "IN"
    return con.execute(
        f"SELECT COUNT(*) AS n FROM ordini WHERE stato {verso} "
        f"({segnaposto}) AND (annuncio_id=? OR id IN "
        f"(SELECT ordine_id FROM ordine_righe WHERE annuncio_id=?))",
        (*stati, annuncio_id, annuncio_id)).fetchone()["n"]


def _impegni_aperti(con, tg_id: int) -> list:
    """NON SI CHIUDE CON IMPEGNI APERTI (ago 2026): le cinque cose che
    fermano la partenza per le ferie, ognuna con la sua VIA D'USCITA
    scritta accanto — restituisce righe leggibili e non un booleano,
    perche' il messaggio deve dire COSA manca, non che «qualcosa»
    manca. Nessun automatismo: la lampo non si annulla da sola, il
    venditore ha gia' il suo bottone.
    Il LEFT JOIN su annunci NON e' un dettaglio: i SET hanno
    annuncio_id=0 e con l'INNER sparirebbero in silenzio — un ordine
    pagato che non blocca le ferie e' esattamente il buco che questa
    funzione esiste per chiudere. E' la lezione gia' pagata due volte
    (sollecita_incassi, sollecita_venditori_fermi), qui alla terza."""
    adesso = int(time.time())
    voci = []
    # 1) Merce pagata e mai partita: e' il caso piu' grave — i sats di
    #    qualcuno sono in cassaforte e aspettano lui.
    for o in con.execute(
            "SELECT o.id, o.annuncio_id, o.consegna_scelta, a.titolo "
            "FROM ordini o LEFT JOIN annunci a ON a.id = o.annuncio_id "
            "WHERE o.venditore_id=? AND o.stato='locked' ORDER BY o.id",
            (tg_id,)):
        titolo = o["titolo"]
        if not o["annuncio_id"]:      # un SET: il titolo lo sintetizziamo
            titolo = _titolo_ordine([dict(x) for x in con.execute(
                "SELECT titolo, quantita FROM ordine_righe "
                "WHERE ordine_id=? ORDER BY id", (o["id"],))])
        cosa = ("consegna il codice" if o["consegna_scelta"] == "digitale"
                else "segna la spedizione")
        voci.append(f"ordine #{o['id']} «{(titolo or '?')[:40]}»: {cosa}")
    # 2) Le aste vive sono VINCOLANTI: chi ha versato sta gareggiando.
    #    Stessa query del tetto per venditore in pubblica().
    for a in con.execute(
            "SELECT id, titolo, asta_scadenza FROM annunci WHERE "
            "venditore_id=? AND stato IN ('attivo','revisione') AND "
            "asta_base_sats>0 AND asta_scadenza>? ORDER BY asta_scadenza",
            (tg_id, adesso)):
        voci.append(f"asta «{a['titolo'][:40]}»: si chiude il "
                    f"{data_ferie(a['asta_scadenza'])}")
    # 3) Una stretta di mano gia' data: il compratore ha le sue ore
    #    per pagare, e in ferie non potrebbe. Scade da sola.
    for o in con.execute(
            "SELECT o.id, o.scadenza, a.titolo FROM offerte o "
            "JOIN annunci a ON a.id = o.annuncio_id "
            "WHERE o.venditore_id=? AND o.stato='accettata' "
            "ORDER BY o.scadenza", (tg_id,)):
        voci.append(f"offerta accettata su «{o['titolo'][:40]}»: "
                    f"l'accordo scade da solo entro "
                    f"{ORE_PAGAMENTO_OFFERTA} ore")
    # 4) Un pagamento gia' in viaggio: verifica_pagamento non passa
    #    dai gate di compra(), quindi senza questa riga nascerebbe un
    #    'locked' proprio durante le ferie. Dura al massimo mezz'ora
    #    (la soglia di _riservati: vita della invoice + reaper).
    n = con.execute(
        "SELECT COUNT(*) AS n FROM ordini WHERE venditore_id=? AND "
        "stato='creato' AND creato>=?",
        (tg_id, adesso - 1800)).fetchone()["n"]
    if n:
        voci.append(f"{n} pagament{'o' if n == 1 else 'i'} in corso: "
                    f"aspetta qualche minuto e riprova")
    # 5) Uno sconto pubblico a tempo e' una promessa in vetrina.
    for a in con.execute(
            "SELECT id, titolo FROM annunci WHERE venditore_id=? AND "
            "lampo_percento>0 AND lampo_scadenza>? ORDER BY id",
            (tg_id, adesso)):
        voci.append(f"offerta lampo su «{a['titolo'][:40]}»: annullala "
                    f"dal suo annuncio")
    return voci


def _riservati(con, annuncio_id: int) -> int:
    """Pezzi prenotati: la somma degli ordini 'creato' freschi.

    La prenotazione E' la riga stessa dell'ordine non ancora pagato:
    niente contatore da tenere allineato (il DELETE del reaper o
    dell'annullamento la libera per costruzione), e la finestra di 30
    minuti — la stessa soglia di pulisci_ordini_fantasma — rende
    innocue le righe stantie anche quando il reaper pigro non e' mai
    girato. I 30 minuti coprono la vita della invoice (15): un
    pagamento non puo' atterrare a prenotazione scaduta.
    I set (lug 2026) prenotano come i mono: la seconda somma pesca
    le righe dei set 'creato' freschi — due query e non una UNION,
    cosi' la prima resta sull'indice caldo idx_ordini_annuncio."""
    soglia = int(time.time()) - 1800
    mono = con.execute(
        "SELECT COALESCE(SUM(quantita),0) AS n FROM ordini "
        "WHERE annuncio_id=? AND stato='creato' AND creato>=?",
        (annuncio_id, soglia)).fetchone()["n"]
    nei_set = con.execute(
        "SELECT COALESCE(SUM(r.quantita),0) AS n FROM ordine_righe r "
        "JOIN ordini o ON o.id=r.ordine_id "
        "WHERE r.annuncio_id=? AND o.stato='creato' AND o.creato>=?",
        (annuncio_id, soglia)).fetchone()["n"]
    return mono + nei_set


async def _compra_set(user: dict, d: dict) -> dict:
    """Il ramo SET di compra() (lug 2026, «Riempi il barattolo»):
    piu' annunci DIVERSI dello stesso venditore in UN ordine solo —
    una invoice escrow, UNA spedizione (il MAX dei costi dichiarati:
    il pacco e' uno solo), una conferma. Solo strade FISICHE:
    il digitale ha la colonna unica del contenuto e le sue finestre
    corte, resta fuori dal set per costruzione; gli annunci senza
    modalita' ('' — gli storici, e gli importati che non la
    dichiarano) non dicono un costo di spedizione e restano fuori
    anche loro. Dall'import aperto (lug 2026) un annuncio arrivato da
    Nostr PUO' dichiararla, col tag `delivery`: in quel caso entra nei
    set come tutti, ed e' giusto — il catalogo e' uno solo, cambia
    solo chi firma l'evento. Stessa liturgia del mono:
    fail-fast di cortesia, poi la invoice, poi il ricontrollo che fa
    fede — per OGNI riga — senza await fino all'INSERT."""
    # --- Le righe richieste: 2..MAX, annunci distinti, quantita sane
    grezze = d.get("righe") or []
    if not isinstance(grezze, list) or len(grezze) < 2:
        raise HTTPException(400, "Un set ha almeno due oggetti diversi: "
                                 "per uno solo c'è l'acquisto di sempre")
    if len(grezze) > MAX_RIGHE_SET:
        raise HTTPException(400, f"Un set può avere al massimo "
                                 f"{MAX_RIGHE_SET} oggetti diversi")
    richieste = {}      # annuncio_id -> quantita (l'ordine di arrivo conta)
    offerte_chieste = {}  # annuncio_id -> offerta_id
    for r in grezze:
        try:
            aid = int(r.get("annuncio_id") or 0)
            qta = max(1, int(r.get("quantita") or 1))
            off_id = int(r.get("offerta_id") or 0)
        except (TypeError, ValueError, AttributeError):
            raise HTTPException(400, "Righe del set non leggibili")
        if aid <= 0:
            raise HTTPException(400, "Righe del set non leggibili")
        if aid in richieste:
            raise HTTPException(400, "Lo stesso oggetto compare due volte "
                                     "nel set: alza la quantità invece")
        richieste[aid] = qta
        if off_id:
            offerte_chieste[aid] = off_id

    con = db()
    seg = ",".join("?" * len(richieste))
    tutti = {a["id"]: a for a in con.execute(
        f"SELECT * FROM annunci WHERE id IN ({seg})",
        tuple(richieste)).fetchall()}
    for aid in richieste:
        a = tutti.get(aid)
        if not a or a["stato"] != "attivo":
            con.close()
            titolo = a["titolo"][:40] if a else "Uno degli oggetti"
            raise HTTPException(404, f"«{titolo}» non è più disponibile: "
                                     f"toglilo dal set e riprova")
        if _asta(a):
            con.close()
            raise HTTPException(400, f"«{a['titolo'][:40]}» è all'asta: "
                                     f"si aggiudica da solo, fuori dal set")
    venditori = {a["venditore_id"] for a in tutti.values()}
    if len(venditori) > 1:
        con.close()
        raise HTTPException(400, "Un set contiene solo oggetti dello "
                                 "stesso venditore")
    venditore_id = venditori.pop()
    if venditore_id == user["id"]:
        con.close()
        raise HTTPException(400, "Non puoi comprare i tuoi stessi annunci")
    # Il carrello e' di UN venditore alla volta, quindi una guardia
    # sola copre tutte le righe: se e' in ferie, non se ne compra
    # nessuna. Qui, prima della invoice.
    guardia_ferie(con, venditore_id)
    # STESSO VENDITORE VERO, non solo stessa RIGA di utenti (lug 2026,
    # dopo il caso dell'account fantasma). `venditore_id` dice a chi
    # vanno i sats, ed e' giusto che il conto lo segua; ma non dice da
    # DOVE arriva la merce, e un account che raccogliesse roba di piu'
    # persone passerebbe la guardia con un id solo — come e' successo.
    # L'origine di un annuncio e' `contatto_nostr`: '' = nato qui,
    # altrimenti la chiave che l'ha firmato. Un set deve avere UNA
    # origine sola, e non e' pignoleria da inventario: cio' che e'
    # nato qui e cio' che vive su una chiave altrove non sta nello
    # stesso scatolone nemmeno nella vita vera.
    # ATTENZIONE a cosa NON fa: non avrebbe fermato il fantasma, che
    # aveva una chiave sola. A fermare quello e' il tappo
    # (chiave_di_casa + il controllo dell'autore nell'import); questa
    # e' la cintura che regge se un giorno il tappo salta.
    origini = {(a["contatto_nostr"] or "") for a in tutti.values()}
    if len(origini) > 1:
        con.close()
        raise HTTPException(400, "Questi oggetti non arrivano tutti dallo "
                                 "stesso posto: si comprano uno per volta")

    # --- Le strade del set: l'INTERSEZIONE delle strade fisiche.
    # Un solo-ritiro e un solo-spedizione non viaggiano insieme.
    strade = {"spedizione", "ritiro"}
    for a in tutti.values():
        sue = set()
        if a["consegna"] in ("spedizione", "entrambe"):
            sue.add("spedizione")
        if a["consegna"] in ("ritiro", "entrambe"):
            sue.add("ritiro")
        if not sue:
            con.close()
            if a["consegna"] == "digitale":
                raise HTTPException(400, f"«{a['titolo'][:40]}» si consegna "
                    f"solo come codice online: si compra da solo, "
                    f"fuori dal set")
            raise HTTPException(400, f"«{a['titolo'][:40]}» non dichiara "
                f"una modalità di consegna: si compra da solo, "
                f"fuori dal set")
        strade &= sue
    if not strade:
        con.close()
        raise HTTPException(400, "Questi oggetti non viaggiano insieme: "
                                 "uno si consegna solo a mano e un altro "
                                 "solo con la spedizione")
    scelta = d.get("consegna", "")
    if scelta not in strade:
        if scelta:
            con.close()
            raise HTTPException(400, "Il set non prevede questa modalità "
                                     "di consegna")
        scelta = "spedizione" if "spedizione" in strade else "ritiro"

    # La VIA della spedizione, come nel mono (il venditore del set e'
    # UNO: una SELECT sola per lo spedizioniere). Lettura prima della
    # invoice: il patto del ricontrollo senza await non si tocca.
    via = (str(d.get("spedizione_via") or "casa")).strip().lower()
    if via not in ("casa", "punto"):
        con.close()
        raise HTTPException(400, "Strada di spedizione sconosciuta")
    punto = " ".join(str(d.get("punto_ritiro") or "").split())[:120]
    if via == "punto":
        if scelta != "spedizione":
            con.close()
            raise HTTPException(400, "Il punto di ritiro vale solo con "
                                     "la spedizione")
        # QUARTO giro (decisione di Andrea, rovescia il terzo): il
        # punto si sceglie SEMPRE in pagina, prima di «Paga» — la
        # regola vive nel CLIENT. Qui il 400 resta SOLO con la rete
        # dichiarata: il client di ieri senza rete non ha il campo, e
        # un 400 senza campo sarebbe un vicolo cieco. Il residuo
        # (ordine nato senza punto) lo coprono il campo dell'ordine e
        # il gate di segna_spedito — la SELECT e' una lettura prima
        # della invoice, il patto del ricontrollo non si tocca.
        sp = con.execute("SELECT spedizioniere FROM utenti WHERE tg_id=?",
                         (venditore_id,)).fetchone()
        if sp and sp["spedizioniere"] and not punto:
            con.close()
            raise HTTPException(400, "Indica il punto di ritiro (nome o "
                                     "indirizzo del punto)")
    else:
        punto = ""
    via_punto = 1 if via == "punto" else 0

    # --- Fail-fast di cortesia sullo stock, riga per riga (quello
    # che fa fede e' il ricontrollo dopo la invoice, come nel mono)
    for aid, qta in richieste.items():
        a = tutti[aid]
        disponibile = a["quantita"] - _riservati(con, aid)
        if qta > disponibile:
            con.close()
            if disponibile < 1:
                raise HTTPException(409, f"Qualcun altro sta già pagando "
                    f"«{a['titolo'][:40]}»: togli quel pezzo dal set o "
                    f"riprova tra pochi minuti")
            raise HTTPException(400, f"Di «{a['titolo'][:40]}» ne restano "
                                     f"solo {disponibile}: scegli una "
                                     f"quantità più piccola")

    # --- Le offerte accettate entrano nel set riga per riga, con le
    # stesse quattro guardie del mono (il DML dell'offerta scaduta
    # committa e solleva SUBITO: il patto del ricontrollo resta vero)
    offerte = {}    # annuncio_id -> riga offerta
    for aid, off_id in offerte_chieste.items():
        off = con.execute(
            "SELECT * FROM offerte WHERE id=? AND compratore_id=? AND "
            "annuncio_id=? AND stato='accettata'",
            (off_id, user["id"], aid)).fetchone()
        if not off:
            con.close()
            raise HTTPException(404, "Offerta non trovata o non più valida")
        adesso = int(time.time())
        if 0 < off["scadenza"] < adesso:
            con.execute("UPDATE offerte SET stato='scaduta', aggiornato=? "
                        "WHERE id=?", (adesso, off["id"]))
            con.commit()
            con.close()
            raise HTTPException(400, f"Il tempo per pagare l'offerta su "
                                     f"«{tutti[aid]['titolo'][:40]}» è "
                                     f"finito: l'offerta è scaduta")
        if off["ordine_id"]:
            viva = con.execute(
                "SELECT id FROM ordini WHERE id=? AND stato='creato'",
                (off["ordine_id"],)).fetchone()
            if viva:
                con.close()
                raise HTTPException(400, "C'è già una invoice in corso "
                                         "per una di queste offerte: "
                                         "pagala, oppure annulla "
                                         "quell'ordine e riprova")
        offerte[aid] = off

    # --- La regola dello sconto carrello del venditore, letta QUI:
    # prima dell'unico await, cosi' il conto si fissa sull'istante in
    # cui nasce la fattura. Cambiarla mentre qualcuno ha il carrello
    # aperto e' lecito e non ha guardie — vale il conto del momento
    # dell'acquisto, come per il prezzo e per la lampo — e da questo
    # punto in poi la cifra e' congelata nell'ordine.
    ven = con.execute("SELECT sconto_pacco_criterio, sconto_pacco_soglia, "
                      "sconto_pacco_valore_eur, sconto_pacco_percento, "
                      "sped_gratis_soglia_eur "
                      "FROM utenti WHERE tg_id=?", (venditore_id,)).fetchone()
    crit, sog, pct = _regola_sconto(
        ven["sconto_pacco_criterio"] if ven else "",
        ven["sconto_pacco_soglia"] if ven else 0,
        ven["sconto_pacco_valore_eur"] if ven else 0,
        ven["sconto_pacco_percento"] if ven else 0)
    sog_gratis = _regola_sped_gratis(
        ven["sped_gratis_soglia_eur"] if ven else 0)

    # --- Il cambio, UNA volta per tutto il set (prima della invoice:
    # da li' in poi niente await). Serve se un listino e' in EUR, se
    # la tariffa DELLA VIA scelta e' ancorata all'euro, o se una
    # PROMESSA IN EURO e' accesa — da quando le due soglie parlano
    # euro, il conto ha bisogno del cambio anche su un carrello
    # tutto-sats. Solo se serve davvero: un negozio senza promesse non
    # lo chiede, esattamente come ieri.
    # DUE bisogni diversi, e tenerli distinti E' la regola: senza il
    # cambio un listino in euro o una tariffa ancorata non si sanno
    # convertire e l'ordine NON puo' nascere (503, come sempre); una
    # promessa in euro invece non si sa solo VALUTARE, e allora non
    # scatta e basta — far fallire un acquisto perche' non si riesce a
    # regalare uno sconto sarebbe curare un male causandone uno peggiore.
    serve_cambio_duro = any(
        (a["valuta"] == "eur" and a["prezzo_eur"] > 0)
        or (scelta == "spedizione"
            and (_tariffa_dichiarata(a, via)[1] > 0
                 # il supplemento ancorato all'euro conta come la
                 # tariffa: se lo si dimentica qui, _sped_pacco torna
                 # None e il max() di ieri dava un TypeError, cioe' un
                 # 500 invece di un 503 onesto
                 or a["spedizione_extra_eur"] > 0))
        for a in tutti.values())
    # DUE variabili e non una: `cambio_ordine` finisce in colonna e
    # dichiara «0 = nessuna conversione», quindi resta zero quando non
    # si e' convertito niente; `cambio_misura` e' solo il metro delle
    # promesse. Sono lo stesso numero quando servono entrambe (la
    # funzione ha una cache): a cambiare e' cosa si racconta al database.
    cambio_ordine = 0.0
    cambio_misura = 0.0
    if serve_cambio_duro or crit == "valore" or sog_gratis > 0:
        cambio_misura = await cambio_btc_eur()
        if serve_cambio_duro:
            if cambio_misura <= 0:
                con.close()
                raise HTTPException(503, "Il cambio euro non è disponibile "
                                         "in questo momento: riprova tra "
                                         "qualche minuto")
            cambio_ordine = cambio_misura

    # --- Il conto, riga per riga: unitario gia' col MIN tra lampo e
    # accordo (il patto del mono: si arrotonda PRIMA di moltiplicare,
    # cosi' la divisione a ritroso di chi legge l'ordine e' esatta).
    # La spedizione la dice _sped_pacco: il MAX dei costi dichiarati
    # (il pacco e' uno — compromesso dichiarato del v1) piu' il
    # supplemento di ogni pezzo oltre il primo.
    adesso = int(time.time())
    righe, articolo, pezzi = [], 0, 0
    for aid, qta in richieste.items():
        a = tutti[aid]
        # La matematica e' quella delle pure del conto (il patto del
        # mono): unitario col MIN tra lampo e accordo, arrotondato
        # PRIMA di moltiplicare.
        unitario = _unitario_effettivo(a, offerte.get(aid), adesso,
                                       cambio_ordine)
        if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
            # Il tetto di rodaggio con +20% di tolleranza, sull'unitario
            # della riga (e' un vincolo del listino, come nel mono)
            if TETTO_SATS_ANNUNCIO and unitario > TETTO_SATS_ANNUNCIO * 1.2:
                con.close()
                await notifica(a["venditore_id"],
                    f"📈 Il cambio si è mosso troppo: il tuo annuncio "
                    f"«{a['titolo'][:60]}» ({a['prezzo_eur']:.2f} EUR) "
                    f"supera ora il tetto di {TETTO_SATS_ANNUNCIO} sats e "
                    f"gli acquisti sono in pausa. Ritocca il prezzo per "
                    f"riaprirli.")
                raise HTTPException(409, f"Il cambio è cambiato troppo per "
                                         f"«{a['titolo'][:40]}»: il "
                                         f"venditore deve ritoccare il "
                                         f"prezzo")
        articolo += unitario * qta
        pezzi += qta
        righe.append({"annuncio_id": aid, "quantita": qta,
                      "unitario_sats": unitario, "titolo": a["titolo"]})

    # La spedizione dell'ordine intero, dalla pura che serve anche il
    # preventivo. `sats` non puo' essere None: serve_cambio_duro nomina
    # TUTTE le tariffe ancorabili all'euro, e una prova in CI incrocia
    # quell'elenco con le colonne `spedizione*_eur` di annunci — la
    # quarta tariffa che qualcuno aggiungera' lo sentira' dalla CI e
    # non da un TypeError (che qui era `max(sped, None)`, cioe' un 500
    # col database aperto).
    sp = _sped_pacco([(tutti[aid], q) for aid, q in richieste.items()],
                     via if scelta == "spedizione" else "", cambio_ordine)
    sped = sp["sats"]

    # La MISURA delle due promesse, contata UNA volta sola: e' cosi'
    # che «guardano lo stesso numero» resta vero per costruzione invece
    # che per disciplina. None a cambio muto, e le due pure lo sanno.
    misura_eur = _eur_interi(articolo, cambio_misura)
    # Lo sconto carrello, sulla somma degli articoli e mai sulla
    # spedizione. Il tetto di rodaggio qui sopra ha gia' giudicato il
    # LORDO, ed e' l'ordine giusto: e' un vincolo del listino, non del
    # checkout — altrimenti si pubblicherebbe sopra il tetto e ci si
    # rientrerebbe dietro una regola di sconto.
    sconto = _sconto_pacco(articolo, misura_eur, pezzi, crit, sog, pct)
    # La spedizione gratis sopra soglia, sullo STESSO lordo dello
    # sconto: le due promesse sono indipendenti apposta, e
    # l'ordine fra queste due righe non conta — nessuna delle due
    # guarda il risultato dell'altra. Si azzera dopo aver contato la
    # tariffa (il MAX qui sopra), che e' anche il punto in cui decide
    # _strade_preventivo: preventivo e invoice devono dire la stessa
    # cifra per costruzione.
    sped_gratis_sats, supplemento = 0, sp["supplemento"]
    if sped and _sped_gratis(misura_eur, sog_gratis):
        # la promessa offre la spedizione INTERA, supplemento compreso
        sped_gratis_sats, sped, supplemento = sped, 0, 0
    conto = _conto_ordine(articolo, sped, PROTEZIONE_PERCENTO,
                          COMMISSIONE_PERCENTO, sconto)
    prot, totale = conto["protezione"], conto["totale"]

    primo = righe[0]["titolo"]
    inv = await crea_invoice_escrow(
        totale, f"Barattolo escrow set: {primo[:25]} +{len(righe) - 1} "
                f"({len(righe)} oggetti)")
    # Il ricontrollo che fa fede, per OGNI riga (il patto del mono:
    # da qui all'INSERT nessun await, e nessun DML prima — l'offerta
    # scaduta qui sopra committa e solleva subito). Fallita una riga,
    # fallisce il set: la invoice muore da sola in 15 minuti e il 409
    # NOMINA il pezzo, cosi' il compratore sa cosa togliere.
    for aid, qta in richieste.items():
        fresco = con.execute("SELECT stato, quantita FROM annunci "
                             "WHERE id=?", (aid,)).fetchone()
        if (not fresco or fresco["stato"] != "attivo"
                or qta > fresco["quantita"] - _riservati(con, aid)):
            con.close()
            raise HTTPException(409, f"«{tutti[aid]['titolo'][:40]}» ti è "
                                     f"stato soffiato mentre componevi il "
                                     f"set: toglilo e riprova")
    adesso = int(time.time())
    con.execute(
        "INSERT INTO ordini(annuncio_id,compratore_id,venditore_id,"
        "prezzo_sats,stato,payment_hash,invoice,creato,aggiornato,"
        "cambio_ordine,consegna_scelta,punto_ritiro,via_punto,"
        "spedizione_sats,protezione_sats,quantita,"
        "sconto_sats,sconto_percento,sped_gratis_sats) "
        "VALUES(0,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (user["id"], venditore_id, totale, "creato", inv["payment_hash"],
         inv["payment_request"], adesso, adesso, cambio_ordine, scelta,
         punto, via_punto, sped, prot, pezzi,
         # la percentuale si fotografa SOLO se lo sconto e' scattato,
         # o la ricevuta di un ordine sotto soglia dichiarerebbe uno
         # sconto che non c'e'
         sconto, pct if sconto else 0, sped_gratis_sats))
    ordine_id = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    for r in righe:
        con.execute(
            "INSERT INTO ordine_righe(ordine_id,annuncio_id,quantita,"
            "unitario_sats,titolo) VALUES(?,?,?,?,?)",
            (ordine_id, r["annuncio_id"], r["quantita"],
             r["unitario_sats"], r["titolo"]))
    for off in offerte.values():
        # Il legame ordine-offerta nella STESSA transazione (il patto
        # del mono): nessuna finestra in cui l'uno esiste senza l'altro
        con.execute("UPDATE offerte SET ordine_id=?, aggiornato=? "
                    "WHERE id=?", (ordine_id, adesso, off["id"]))
    con.commit()
    con.close()
    # La taglia stimata del pacco unico: informativa, solo con la
    # spedizione (il ritiro non fa pacchi)
    stima = (stima_taglia_set([(tutti[aid]["taglia_pacco"], qta)
                               for aid, qta in richieste.items()])
             if scelta == "spedizione" else "")
    # prezzo_sats resta il TOTALE, come sempre; le righe sono in piu'
    # (i totali parlano anche ai client che il set non lo conoscono)
    return {"ordine_id": ordine_id, "invoice": inv["payment_request"],
            "payment_hash": inv["payment_hash"], "prezzo_sats": totale,
            # articolo_sats e' il NETTO, come nel preventivo: lordo e
            # sconto sono chiavi in piu' e si sommano da sole
            "articolo_sats": conto["netto"],
            "articolo_lordo_sats": articolo,
            "sconto_sats": sconto, "sconto_percento": pct if sconto else 0,
            # il criterio e' la fotografia di COSA e' scattato, gemella
            # della percentuale: su un ordine sotto soglia direbbe
            # qualcosa che non c'e'
            "sconto_criterio": crit if sconto else "",
            "spedizione_sats": sped,
            # la parte per-pezzo, e i pezzi: sono le due chiavi con cui
            # il paySheet tiene la riga «spedizione per N pezzi» che la
            # pagina d'acquisto mostrava un istante prima. Senza, quella
            # riga sparirebbe sullo stesso schermo e si leggerebbe come
            # «il prezzo e' cambiato» — un attimo prima di pagare.
            "supplemento_sats": supplemento, "pezzi": pezzi,
            # la tariffa risparmiata: colonna TESTIMONE, e qui e' la
            # chiave che permette al compratore di ritrovarla
            "sped_gratis_sats": sped_gratis_sats,
            "protezione_sats": prot, "consegna": scelta,
            "punto_ritiro": punto, "via_punto": via_punto,
            "quantita": pezzi, "set": True, "taglia_stimata": stima,
            "righe": [{"annuncio_id": r["annuncio_id"],
                       "titolo": r["titolo"], "quantita": r["quantita"],
                       "unitario_sats": r["unitario_sats"]}
                      for r in righe]}


# La soglia della ripresa (ago 2026): la invoice vive 900s, ma
# ripresentarne una con pochi secondi di vita sarebbe una beffa —
# sotto i ~3 minuti restanti si rinnova e basta.
RIPRESA_INVOICE_S = 720


def _strade_preventivo(righe: list, articolo: int, cambio: float,
                       disponibili: set, articolo_eur: float = 0.0,
                       sconto: int = 0, sconto_eur: float = 0.0,
                       sped_gratis: bool = False) -> list:
    """Le strade del preventivo coi loro totali, nell'ordine FISSO
    ritiro → casa → punto → digitale. `disponibili` le decide il
    CHIAMANTE — per il mono le strade dell'annuncio, per il set
    l'INTERSEZIONE delle fisiche: rifarle qui dall'unione direbbe una
    strada che il set non offre. `righe` sono le [(annuncio, qta)] su
    cui contare la spedizione — e la QUANTITA' non e' un dettaglio:
    finche' qui arrivavano i soli annunci, il mono col supplemento
    avrebbe detto la spedizione di UN pezzo e la invoice quella di
    dieci (col supplemento a zero i due numeri coincidono, ed e'
    esattamente il motivo per cui il buco poteva restare a lungo
    invisibile). La via 'punto' c'e'
    SEMPRE dove c'e' la spedizione — anche senza spedizioniere
    dichiarato (secondo giro, la decisione che SUPERA il gate: meglio
    l'accordo in chat che la porta chiusa; la rete, se dichiarata, la
    dice il campo `spedizioniere` della risposta).
    Una tariffa ancorata all'euro senza cambio = strada che esce con
    `cambio_assente` e senza numeri: si spegne col motivo, le altre
    restano comprabili — mai un 503 che spegne anche il ritiro.
    Ogni strada porta anche l'euro NATIVO dove esiste (`spedizione_
    eur` = la tariffa com'e' nata, `totale_eur` = solo quando e'
    ESATTO: articolo nato in euro, tariffa in euro o zero, protezione
    zero, e — dallo sconto carrello — sconto zero o scontato anche in
    euro) — e' il dato del giudice del ≈ nel client: il ≈ sta sulla
    valuta convertita, mai su quella nativa, e un totale misto non
    ha una valuta nativa e resta ≈ in tutte e due le viste.
    `articolo` resta il LORDO e `sconto` gli viaggia accanto: la
    sottrazione la fa _conto_ordine, una volta sola.
    `sped_gratis` lo decide il CHIAMANTE sullo stesso LORDO (e' una
    proprieta' dell'ordine, non della via) e qui azzera la tariffa di
    casa e punto, dicendo in `sped_gratis_sats` quella che si sarebbe
    pagata. La decisione arriva DOPO il conto della tariffa, ed e'
    deliberato: dev'essere lo stesso identico punto di compra() e
    _compra_set, o la pagina direbbe «gratuita» dove la invoice
    risponde 503. Il prezzo dichiarato e' che una tariffa ancorata
    all'euro col cambio muto spegne la strada anche quando la
    spedizione sarebbe gratis — raro e transitorio, e il verso giusto
    in cui sbagliare."""
    fuori = []

    def _entra(v, sped, stima_sped, sped_eur=0.0, extra=None):
        conto = _conto_ordine(articolo, sped, PROTEZIONE_PERCENTO,
                              COMMISSIONE_PERCENTO, sconto)
        tot_eur = 0.0
        # LA RIGA PIU' DELICATA DEL CANTIERE SCONTO: l'euro esatto
        # vuole anche uno sconto NATIVO. Se i sats fossero scontati e
        # l'euro no, questo numero direbbe una cifra piu' ALTA di
        # quella che si paga — e senza il ≈ davanti, cioe' una
        # precisione falsa. I due gemelli scattano insieme per
        # costruzione: questa e' la cintura per il giorno in cui uno
        # dei due cambiasse.
        if (articolo_eur > 0 and conto["protezione"] == 0
                and (sped == 0 or sped_eur > 0)
                and (sconto == 0 or sconto_eur > 0)):
            tot_eur = round(articolo_eur - sconto_eur
                            + (sped_eur if sped else 0.0), 2)
        e = {"via": v, "spedizione_sats": sped,
             "spedizione_eur": sped_eur if sped else 0.0,
             "totale_sats": conto["totale"], "totale_eur": tot_eur,
             "stima": stima_sped}
        if extra:
            e.update(extra)
        fuori.append(e)

    if "ritiro" in disponibili:
        _entra("ritiro", 0, False)
    if "spedizione" in disponibili:
        # la via punto c'e' SEMPRE dove c'e' la spedizione (secondo
        # giro, decisione di Andrea che SUPERA il gate dello
        # spedizioniere) — senza rete il punto arriva dopo, dal campo
        # dell'ordine (terzo giro); la tariffa e' il fallback casa
        for v in ("casa", "punto"):
            # il MAX (e il supplemento per pezzo) li fa la pura, la
            # stessa da cui passano compra() e _compra_set: qui non si
            # ricalcola niente, o sarebbero due conti da tenere in pari
            p = _sped_pacco(righe, v, cambio)
            sped, sped_eur, stima_sped = p["sats"], p["eur"], p["stima"]
            extra = ({"fallback_casa": not any(
                a["spedizione_punto_dichiarata"] for a, _ in righe)}
                if v == "punto" else None)
            # i due campi che raccontano la riga breve «spedizione per
            # N pezzi»: il client non li calcola, li riceve
            extra = {**(extra or {}), "supplemento_sats": p["supplemento"],
                     "pezzi": p["pezzi"]}
            # LA PROMESSA DEL NEGOZIO, qui e non prima: la tariffa si
            # azzera dopo essere stata contata, cosi' questo punto e'
            # lo stesso di compra() e la pagina non puo' promettere una
            # cifra che la invoice poi non fa. `sped_gratis_sats` esce
            # comunque (0 quando non scatta): e' la cifra che l'ordine
            # fotografera' e che rende confrontabili preventivo e
            # invoice.
            risparmio = 0
            if sped_gratis and sped:
                risparmio, sped, sped_eur, stima_sped = sped, 0, 0.0, False
                # il supplemento se ne va col resto: la promessa offre
                # la spedizione INTERA, e senza questa riga la pagina
                # direbbe «gratuita» e sotto «spedizione per 10 pezzi»
                extra["supplemento_sats"] = 0
            extra = {**(extra or {}), "sped_gratis_sats": risparmio}
            if sped is None:
                e = {"via": v, "cambio_assente": True}
                if extra:
                    e.update(extra)
                fuori.append(e)
            else:
                _entra(v, sped, stima_sped, sped_eur, extra)
    if "digitale" in disponibili:
        _entra("digitale", 0, False)
    if not fuori:
        # Annuncio storico senza modalita': il flusso di sempre, una
        # pseudo-strada '' — il client non disegna la scelta e il body
        # di compra non porta consegna.
        _entra("", 0, False)
    return fuori


@app.post("/api/orders/preventivo")
async def preventivo_ordine(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Il conto della pagina d'acquisto (ago 2026), PER OGNI strada
    disponibile in una chiamata sola. Stesso body di compra (mono o
    righe), ma NON CREA NULLA: niente invoice, niente INSERT, nessun
    DML — nemmeno il timbro dell'offerta scaduta, che spetta a compra.
    La matematica e' quella delle pure del conto: preventivo e invoice
    devono dire la stessa cifra per costruzione. I listini EUR sono
    una stima al cambio di adesso (`stima`): il totale vero si fissa
    con la invoice, come sempre."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not d.get("annuncio_id") and isinstance(d.get("righe"), list):
        return await _preventivo_set(user, d)
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato='attivo'",
                    (d.get("annuncio_id"),)).fetchone()
    if not a:
        con.close()
        raise HTTPException(404, "Annuncio non disponibile")
    if a["venditore_id"] == user["id"]:
        con.close()
        raise HTTPException(400, "Non puoi comprare il tuo stesso annuncio")
    # Anche il preventivo si ferma: la pagina d'acquisto non deve
    # nemmeno nascere per un negozio chiuso (il client lo sa gia' dal
    # campo di vetrina, questa e' la cintura).
    guardia_ferie(con, a["venditore_id"])
    if _asta(a):
        con.close()
        raise HTTPException(400, "Questo oggetto è all'asta: si "
                                 "aggiudica puntando, non si compra a "
                                 "prezzo fisso")
    try:
        richiesti = max(1, int(d.get("quantita") or 1))
    except (TypeError, ValueError):
        richiesti = 1
    # Il fail-fast dello stock, di cortesia come in compra: la pagina
    # avvisa subito, e il ricontrollo vero resta quello della invoice.
    disponibile = a["quantita"] - _riservati(con, a["id"])
    if richiesti > disponibile:
        con.close()
        if disponibile < 1:
            raise HTTPException(409, "Qualcun altro sta già pagando questo "
                                     "oggetto: se il suo pagamento non va "
                                     "in porto tornerà disponibile tra "
                                     "pochi minuti")
        raise HTTPException(400, f"Ne restano solo {disponibile}: scegli "
                                 f"una quantità più piccola")
    # L'offerta accettata, con le guardie di compra ma SENZA il DML
    # della scaduta (quel timbro spetta a compra: qui solo un 400
    # con lo stesso testo).
    off = None
    if d.get("offerta_id"):
        off = con.execute(
            "SELECT * FROM offerte WHERE id=? AND compratore_id=? AND "
            "annuncio_id=? AND stato='accettata'",
            (d["offerta_id"], user["id"], a["id"])).fetchone()
        if not off:
            con.close()
            raise HTTPException(404, "Offerta non trovata o non più valida")
        if 0 < off["scadenza"] < int(time.time()):
            con.close()
            raise HTTPException(400, "Il tempo per pagare questa offerta "
                                     "è finito: l'offerta è scaduta")
    # la riga del venditore: lo spedizioniere e la promessa della
    # spedizione gratis, dalla SELECT che c'era gia' — zero query in
    # piu' (il patto del ramo set con lo sconto)
    sp = con.execute("SELECT spedizioniere, sped_gratis_soglia_eur "
                     "FROM utenti WHERE tg_id=?",
                     (a["venditore_id"],)).fetchone()
    spedizioniere = sp["spedizioniere"] if sp else ""
    sog_gratis = _regola_sped_gratis(
        sp["sped_gratis_soglia_eur"] if sp else 0)
    con.close()
    # Il cambio, UNA volta: obbligatorio per il listino EUR (503 come
    # in compra), facoltativo per le sole tariffe ancorate (la strada
    # esce spenta col motivo, le altre vivono) e per la PROMESSA in
    # euro (che senza cambio non si valuta e semplicemente non scatta).
    listino_eur = a["valuta"] == "eur" and a["prezzo_eur"] > 0
    cambio = 0.0
    if (listino_eur or a["spedizione_eur"] > 0
            or a["spedizione_punto_eur"] > 0
            or a["spedizione_extra_eur"] > 0 or sog_gratis > 0):
        cambio = await cambio_btc_eur()
        if listino_eur and cambio <= 0:
            raise HTTPException(503, "Il cambio euro non è disponibile in "
                                     "questo momento: riprova tra qualche "
                                     "minuto")
    adesso = int(time.time())
    unitario = _unitario_effettivo(a, off, adesso, cambio)
    if (listino_eur and TETTO_SATS_ANNUNCIO
            and unitario > TETTO_SATS_ANNUNCIO * 1.2):
        # Il tetto di rodaggio, col 409 di compra ma SENZA la notifica
        # al venditore: questa e' un'anteprima, non un acquisto.
        raise HTTPException(409, "Il cambio è cambiato troppo da quando "
                                 "l'annuncio è stato pubblicato: il "
                                 "venditore deve ritoccare il prezzo")
    articolo = unitario * richiesti
    # l'euro NATIVO dell'articolo (0 = nato in sats): il giudice del ≈
    # del client mostra LUI in vista €, esatto, invece della doppia
    # conversione col suo falso ≈
    unitario_eur = _eur_effettivo(a, off, adesso)
    articolo_eur = round(unitario_eur * richiesti, 2) if unitario_eur else 0.0
    conto = _conto_ordine(articolo, 0, PROTEZIONE_PERCENTO,
                          COMMISSIONE_PERCENTO)
    disponibili = set()
    if a["consegna"] in ("spedizione", "entrambe"):
        disponibili.add("spedizione")
    if a["consegna"] in ("ritiro", "entrambe"):
        disponibili.add("ritiro")
    if a["consegna"] == "digitale" or a["anche_digitale"]:
        disponibili.add("digitale")
    # La spedizione gratis del negozio: sul mono vale come sul set (la
    # forma lo permette, vedi _sped_gratis), e la MISURA e' lo stesso
    # lordo in euro che la soglia dello sconto confronta di la'. Da non
    # confondere con `articolo_eur` qui sopra, che e' l'euro NATIVO del
    # listino (0 quando il prezzo e' nato in sats) e serve al ≈:
    # `misura_eur` invece c'e' sempre, purche' il cambio ci sia.
    # `mancano_sped_eur` lo conta il server anche se il client potrebbe:
    # e' esattamente il numero dove vive un off-by-one (mancano_pezzi).
    misura_eur = _eur_interi(articolo, cambio)
    gratis = _sped_gratis(misura_eur, sog_gratis)
    return {"set": False, "quantita": richiesti,
            "articolo_sats": articolo, "articolo_unitario_sats": unitario,
            "articolo_eur": articolo_eur,
            "articolo_unitario_eur": unitario_eur,
            "protezione_sats": conto["protezione"],
            "commissione_sats": conto["commissione"],
            "stima": listino_eur,
            "spedizioniere": spedizioniere,
            # la chiave VECCHIA esce a zero: un client rimasto in cache
            # la legge in sats e scriverebbe «gratis da 50 sats» (vedi
            # _sped_gratis_pubblico). Il numero vero sta in quella nuova
            "sped_gratis_soglia": 0,
            "sped_gratis_eur": sog_gratis,
            "mancano_sped_sats": 0,
            "mancano_sped_eur": (max(0, sog_gratis - misura_eur)
                                 if sog_gratis and misura_eur is not None
                                 else 0),
            # il motivo, mai un silenzio: a cambio muto le promesse del
            # negozio non si sanno valutare e la pagina lo dice invece
            # di far sparire una riga senza spiegazione
            "promesse_sospese": sog_gratis > 0 and misura_eur is None,
            # [(annuncio, QUANTI)]: la quantita' e' la meta' del conto
            # della spedizione, e passarla e' l'unico modo di dire la
            # stessa cifra che dira' la invoice
            "strade": _strade_preventivo([(a, richiesti)], articolo, cambio,
                                         disponibili, articolo_eur,
                                         sped_gratis=gratis)}


async def _preventivo_set(user: dict, d: dict) -> dict:
    """Il ramo SET del preventivo: le guardie di _compra_set in sola
    lettura, il conto dalle stesse pure. Le strade del set restano
    quelle FISICHE (intersezione), col punto in piu' se lo
    spedizioniere e' dichiarato."""
    grezze = d.get("righe") or []
    if not isinstance(grezze, list) or len(grezze) < 2:
        raise HTTPException(400, "Un set ha almeno due oggetti diversi: "
                                 "per uno solo c'è l'acquisto di sempre")
    if len(grezze) > MAX_RIGHE_SET:
        raise HTTPException(400, f"Un set può avere al massimo "
                                 f"{MAX_RIGHE_SET} oggetti diversi")
    richieste, offerte_chieste = {}, {}
    for r in grezze:
        try:
            aid = int(r.get("annuncio_id") or 0)
            qta = max(1, int(r.get("quantita") or 1))
            off_id = int(r.get("offerta_id") or 0)
        except (TypeError, ValueError, AttributeError):
            raise HTTPException(400, "Righe del set non leggibili")
        if aid <= 0 or aid in richieste:
            raise HTTPException(400, "Righe del set non leggibili")
        richieste[aid] = qta
        if off_id:
            offerte_chieste[aid] = off_id
    con = db()
    seg = ",".join("?" * len(richieste))
    tutti = {a["id"]: a for a in con.execute(
        f"SELECT * FROM annunci WHERE id IN ({seg})",
        tuple(richieste)).fetchall()}
    for aid in richieste:
        a = tutti.get(aid)
        if not a or a["stato"] != "attivo":
            con.close()
            titolo = a["titolo"][:40] if a else "Uno degli oggetti"
            raise HTTPException(404, f"«{titolo}» non è più disponibile: "
                                     f"toglilo dal set e riprova")
        if _asta(a):
            con.close()
            raise HTTPException(400, f"«{a['titolo'][:40]}» è all'asta: "
                                     f"si aggiudica da solo, fuori dal set")
    venditori = {a["venditore_id"] for a in tutti.values()}
    if len(venditori) > 1:
        con.close()
        raise HTTPException(400, "Un set contiene solo oggetti dello "
                                 "stesso venditore")
    venditore_id = venditori.pop()
    if venditore_id == user["id"]:
        con.close()
        raise HTTPException(400, "Non puoi comprare i tuoi stessi annunci")
    guardia_ferie(con, venditore_id)   # il gemello di _compra_set
    origini = {(a["contatto_nostr"] or "") for a in tutti.values()}
    if len(origini) > 1:
        con.close()
        raise HTTPException(400, "Questi oggetti non arrivano tutti dallo "
                                 "stesso posto: si comprano uno per volta")
    # L'intersezione delle strade fisiche, coi 400 di _compra_set
    strade = {"spedizione", "ritiro"}
    for a in tutti.values():
        sue = set()
        if a["consegna"] in ("spedizione", "entrambe"):
            sue.add("spedizione")
        if a["consegna"] in ("ritiro", "entrambe"):
            sue.add("ritiro")
        if not sue:
            con.close()
            if a["consegna"] == "digitale":
                raise HTTPException(400, f"«{a['titolo'][:40]}» si consegna "
                    f"solo come codice online: si compra da solo, "
                    f"fuori dal set")
            raise HTTPException(400, f"«{a['titolo'][:40]}» non dichiara "
                f"una modalità di consegna: si compra da solo, "
                f"fuori dal set")
        strade &= sue
    if not strade:
        con.close()
        raise HTTPException(400, "Questi oggetti non viaggiano insieme: "
                                 "uno si consegna solo a mano e un altro "
                                 "solo con la spedizione")
    for aid, qta in richieste.items():
        a = tutti[aid]
        disponibile = a["quantita"] - _riservati(con, aid)
        if qta > disponibile:
            con.close()
            if disponibile < 1:
                raise HTTPException(409, f"Qualcun altro sta già pagando "
                    f"«{a['titolo'][:40]}»: togli quel pezzo dal set o "
                    f"riprova tra pochi minuti")
            raise HTTPException(400, f"Di «{a['titolo'][:40]}» ne restano "
                                     f"solo {disponibile}: scegli una "
                                     f"quantità più piccola")
    offerte = {}
    for aid, off_id in offerte_chieste.items():
        off = con.execute(
            "SELECT * FROM offerte WHERE id=? AND compratore_id=? AND "
            "annuncio_id=? AND stato='accettata'",
            (off_id, user["id"], aid)).fetchone()
        if not off:
            con.close()
            raise HTTPException(404, "Offerta non trovata o non più valida")
        if 0 < off["scadenza"] < int(time.time()):
            con.close()
            raise HTTPException(400, f"Il tempo per pagare l'offerta su "
                                     f"«{tutti[aid]['titolo'][:40]}» è "
                                     f"finito: l'offerta è scaduta")
        offerte[aid] = off
    # la riga del venditore: lo spedizioniere e la regola dello sconto
    # carrello, dalla SELECT che c'era gia' — zero query in piu'
    sp = con.execute("SELECT spedizioniere, sconto_pacco_criterio, "
                     "sconto_pacco_soglia, sconto_pacco_valore_eur, "
                     "sconto_pacco_percento, sped_gratis_soglia_eur "
                     "FROM utenti WHERE tg_id=?",
                     (venditore_id,)).fetchone()
    spedizioniere = sp["spedizioniere"] if sp else ""
    crit, sog, pct = _regola_sconto(
        sp["sconto_pacco_criterio"] if sp else "",
        sp["sconto_pacco_soglia"] if sp else 0,
        sp["sconto_pacco_valore_eur"] if sp else 0,
        sp["sconto_pacco_percento"] if sp else 0)
    sog_gratis = _regola_sped_gratis(
        sp["sped_gratis_soglia_eur"] if sp else 0)
    con.close()
    listino_eur = any(a["valuta"] == "eur" and a["prezzo_eur"] > 0
                      for a in tutti.values())
    cambio = 0.0
    # ...e le due PROMESSE in euro: senza cambio non si valutano, e
    # allora non scattano — mai un 503, che qui non si sta convertendo
    # un prezzo ma decidendo se regalare qualcosa
    if (listino_eur or crit == "valore" or sog_gratis > 0
            or any(a["spedizione_eur"] > 0
                   or a["spedizione_punto_eur"] > 0
                   or a["spedizione_extra_eur"] > 0
                   for a in tutti.values())):
        cambio = await cambio_btc_eur()
        if listino_eur and cambio <= 0:
            raise HTTPException(503, "Il cambio euro non è disponibile in "
                                     "questo momento: riprova tra qualche "
                                     "minuto")
    adesso = int(time.time())
    righe, articolo = [], 0
    pezzi = 0
    for aid, qta in richieste.items():
        a = tutti[aid]
        unitario = _unitario_effettivo(a, offerte.get(aid), adesso, cambio)
        if (a["valuta"] == "eur" and a["prezzo_eur"] > 0
                and TETTO_SATS_ANNUNCIO
                and unitario > TETTO_SATS_ANNUNCIO * 1.2):
            raise HTTPException(409, f"Il cambio è cambiato troppo per "
                                     f"«{a['titolo'][:40]}»: il "
                                     f"venditore deve ritoccare il "
                                     f"prezzo")
        articolo += unitario * qta
        pezzi += qta
        righe.append({"annuncio_id": aid, "titolo": a["titolo"],
                      "quantita": qta, "unitario_sats": unitario})
    # l'euro NATIVO del set esiste solo se OGNI riga e' nata in euro:
    # un set misto non ha una valuta nativa e resta ≈ in tutte e due
    # le viste (il giudice del ≈ nel client)
    eur_righe = [_eur_effettivo(tutti[aid], offerte.get(aid), adesso)
                 for aid in richieste]
    articolo_eur = (round(sum(round(e * q, 2) for e, q
                              in zip(eur_righe, richieste.values())), 2)
                    if all(e > 0 for e in eur_righe) else 0.0)
    # La MISURA delle due promesse, contata una volta sola. Da non
    # confondere con `articolo_eur` qui sopra, che e' l'euro NATIVO del
    # set (0 se una riga sola e' nata in sats) e serve al ≈: questa
    # invece c'e' sempre, purche' il cambio ci sia.
    misura_eur = _eur_interi(articolo, cambio)
    sconto = _sconto_pacco(articolo, misura_eur, pezzi, crit, sog, pct)
    # il gemello in euro si aziona SOLO dietro al fratello in sats: la
    # decisione e' una sola, e sta di la' (vedi _sconto_pacco_eur)
    sconto_eur = _sconto_pacco_eur(articolo_eur, pct) if sconto else 0.0
    conto = _conto_ordine(articolo, 0, PROTEZIONE_PERCENTO,
                          COMMISSIONE_PERCENTO, sconto)
    # `articolo_sats` e' il NETTO — ha sempre voluto dire «quanto paghi
    # per la merce», ed e' la cifra che con spedizione e protezione FA
    # il totale: cosi' un client fermo a ieri somma comunque giusto, e
    # gli manca solo la riga del risparmio (un'assenza, non una bugia).
    # Il lordo e lo sconto sono chiavi IN PIU', e le tre si sommano da
    # sole: lordo − sconto = netto, senza fidarsi di nessuno.
    return {"set": True, "quantita": pezzi,
            "articolo_sats": conto["netto"],
            "articolo_lordo_sats": articolo,
            "sconto_sats": sconto,
            "articolo_eur": (round(articolo_eur - sconto_eur, 2)
                             if articolo_eur else 0.0),
            "articolo_lordo_eur": articolo_eur,
            "sconto_eur": sconto_eur,
            # la REGOLA esce anche quando non e' scattata: e' cosi' che
            # il carrello puo' dire «aggiungine 1 e risparmi il 10%».
            # Quanto MANCA lo conta il server anche se il client
            # potrebbe: e' esattamente il numero dove vive un off-by-one.
            # Le coppie sono speculari e si spengono a vicenda — la
            # soglia in pezzi non esce mai a criterio valore, e
            # viceversa — cosi' nessuno puo' leggere degli euro come se
            # fossero pezzi (la regola d'oro di _sconto_pubblico).
            # `mancano_eur` misura il LORDO, lo stesso numero che la
            # soglia confronta. Le chiavi in SATS (`sconto_valore`,
            # `mancano_sats`) escono a ZERO per sempre: un client
            # rimasto in cache le legge in sats, e col numero nuovo
            # scriverebbe «da 25 sats», che non e' una promessa avara —
            # e' una promessa assurda, e sembra un guasto.
            "sconto_percento": pct,
            "sconto_criterio": crit,
            "sconto_soglia": sog if crit == "pezzi" else 0,
            "sconto_valore": 0,
            "sconto_valore_eur": sog if crit == "valore" else 0,
            "mancano_pezzi": (max(0, sog - pezzi)
                              if crit == "pezzi" else 0),
            "mancano_sats": 0,
            "mancano_eur": (max(0, sog - misura_eur)
                            if crit == "valore" and misura_eur is not None
                            else 0),
            "protezione_sats": conto["protezione"],
            "commissione_sats": conto["commissione"],
            "stima": listino_eur,
            "spedizioniere": spedizioniere,
            # la seconda promessa del negozio, che guarda lo STESSO
            # lordo della prima: le due sono indipendenti
            # per costruzione, e nessuna delle due misura l'altra
            "sped_gratis_soglia": 0,
            "sped_gratis_eur": sog_gratis,
            "mancano_sped_sats": 0,
            "mancano_sped_eur": (max(0, sog_gratis - misura_eur)
                                 if sog_gratis and misura_eur is not None
                                 else 0),
            # il motivo, mai un silenzio: a cambio muto le promesse in
            # euro non si sanno valutare, e la pagina lo dice invece di
            # far sparire una riga senza spiegazione
            "promesse_sospese": ((crit == "valore" or sog_gratis > 0)
                                 and misura_eur is None),
            # si cammina su `richieste`, MAI zippando tutti.values() con
            # richieste.values(): l'ordine di `tutti` viene dalla SELECT
            # ... IN (...), non da `richieste`, e le quantita' si
            # appaierebbero all'annuncio sbagliato in silenzio
            "strade": _strade_preventivo([(tutti[aid], q) for aid, q
                                          in richieste.items()], articolo,
                                         cambio, strade, articolo_eur,
                                         sconto, sconto_eur,
                                         _sped_gratis(misura_eur, sog_gratis)),
            "righe": righe}


@app.post("/api/orders")
async def compra(req: Request, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """L'acquirente avvia l'acquisto: creiamo la invoice escrow."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    # Il SET (lug 2026): col body a righe si passa dal ramo dedicato;
    # con annuncio_id tutto e' l'acquisto di sempre, byte per byte.
    if not d.get("annuncio_id") and isinstance(d.get("righe"), list):
        return await _compra_set(user, d)
    con = db()
    a = con.execute("SELECT * FROM annunci WHERE id=? AND stato='attivo'",
                    (d["annuncio_id"],)).fetchone()
    if not a:
        raise HTTPException(404, "Annuncio non disponibile")
    if a["venditore_id"] == user["id"]:
        raise HTTPException(400, "Non puoi comprare il tuo stesso annuncio")
    # Il negozio in ferie non vende: qui, ben prima della invoice —
    # l'annuncio resta in vetrina, ma i sats non si muovono.
    guardia_ferie(con, a["venditore_id"])
    if _asta(a):
        # Vale anche per la deserta (base>0, scadenza 0): finche' il
        # venditore non la converte a prezzo fisso, l'acquisto diretto
        # resta spento. Niente gemello nel ricontrollo post-invoice:
        # un annuncio senza base non puo' DIVENTARE un'asta durante
        # l'await — l'asta nasce solo alla pubblicazione, e il
        # «Rilancia» della deserta esige una base gia' presente.
        con.close()
        raise HTTPException(400, "Questo oggetto è all'asta: si "
                                 "aggiudica puntando, non si compra a "
                                 "prezzo fisso")

    # La quantita' richiesta: assente o storta = 1 (i client di ieri).
    try:
        richiesti = max(1, int(d.get("quantita") or 1))
    except (TypeError, ValueError):
        richiesti = 1

    # La scelta della consegna, validata contro le STRADE che
    # l'annuncio offre davvero (dal lug 2026 anche in combinazione:
    # anche_digitale affianca il codice a una modalita' fisica). Il
    # compratore non puo' chiedere cio' che il venditore non offre;
    # le TUTELE dell'ordine seguono la scelta, non l'annuncio.
    # Annuncio senza modalita' ('') = flusso storico, la scelta si
    # ignora; scelta assente o sconosciuta (client vecchio in cache)
    # = la strada FISICA — quella che quel client conosce, e nessuna
    # sorpresa perche' mostra comunque i sats veri della risposta.
    # (Il blocco sta PRIMA del fail-fast dello stock dal ago 2026:
    # la ripresa qui sotto confronta la scelta con l'ordine pendente.)
    disponibili = set()
    if a["consegna"] in ("spedizione", "entrambe"):
        disponibili.add("spedizione")
    if a["consegna"] in ("ritiro", "entrambe"):
        disponibili.add("ritiro")
    if a["consegna"] == "digitale" or a["anche_digitale"]:
        disponibili.add("digitale")
    scelta = d.get("consegna", "")
    if not disponibili:
        scelta = ""
    elif scelta not in disponibili:
        if scelta:
            con.close()
            raise HTTPException(400, "Questo annuncio non prevede questa "
                                     "modalità di consegna")
        # default: prima la fisica ('spedizione' batte 'ritiro',
        # com'era per 'entrambe'), il digitale solo se e' l'unica
        scelta = ("spedizione" if "spedizione" in disponibili
                  else "ritiro" if "ritiro" in disponibili
                  else "digitale")

    # La VIA della spedizione (ago 2026, pagina d'acquisto): 'casa' e'
    # il default — i client di ieri non mandano il campo e per loro
    # nulla cambia — 'punto' e' la spedizione a un punto di ritiro,
    # che esige DUE cose: la spedizione scelta e il punto scritto.
    # (Il gate sullo spedizioniere e' durato un giro: la decisione
    # nuova di Andrea lo SUPERA — la via si offre sempre, senza rete
    # dichiarata ci si accorda in chat.) Il punto e' testo libero del
    # compratore: strip, spazi collassati, tetto 120 — e NON va mai
    # interpolato nell'HTML delle notifiche (si legge nell'ordine,
    # dove il client lo passa da esc()).
    via = (str(d.get("spedizione_via") or "casa")).strip().lower()
    if via not in ("casa", "punto"):
        con.close()
        raise HTTPException(400, "Strada di spedizione sconosciuta")
    punto = " ".join(str(d.get("punto_ritiro") or "").split())[:120]
    if via == "punto":
        if scelta != "spedizione":
            con.close()
            raise HTTPException(400, "Il punto di ritiro vale solo con "
                                     "la spedizione")
        # QUARTO giro, il patto del set (rovescia il terzo): il punto
        # si sceglie SEMPRE in pagina — la regola vive nel CLIENT, e
        # il 400 resta SOLO con la rete dichiarata: tolleranza per il
        # client di ieri, che senza rete non ha il campo. Il residuo
        # lo coprono il campo dell'ordine e il gate di segna_spedito.
        # (Lettura prima della invoice: il patto del ricontrollo.)
        sp = con.execute("SELECT spedizioniere FROM utenti WHERE tg_id=?",
                         (a["venditore_id"],)).fetchone()
        if sp and sp["spedizioniere"] and not punto:
            con.close()
            raise HTTPException(400, "Indica il punto di ritiro (nome o "
                                     "indirizzo del punto)")
    else:
        punto = ""
    via_punto = 1 if via == "punto" else 0

    # LA RIPRESA (ago 2026): il compratore pentito che RITENTA non e'
    # un rivale — il messaggio d'attesa resta SOLO per gli altri, che
    # e' l'anti-doppio-acquisto e va bene cosi'. Se ha gia' un ordine
    # 'creato' su questo annuncio: fattura ancora viva e richiesta
    # identica = gli si RIPRESENTA la sua (mai ordini gemelli, mai due
    # invoice vive dello stesso compratore sullo stesso oggetto — e la
    # vita della fattura E' il lock del prezzo, la ripresa la rispetta);
    # vecchia, o richiesta diversa = lapide sull'ordine di prima e
    # flusso di sempre. La fattura gia' PAGATA non si annulla mai: si
    # incassa qui, e il compratore scopre che l'oggetto e' gia' suo.
    mio = con.execute(
        "SELECT * FROM ordini WHERE annuncio_id=? AND compratore_id=? "
        "AND stato='creato' ORDER BY id DESC LIMIT 1",
        (a["id"], user["id"])).fetchone()
    if mio:
        legame = con.execute("SELECT id FROM offerte WHERE ordine_id=?",
                             (mio["id"],)).fetchone()
        stessa = (mio["quantita"] == richiesti
                  and mio["consegna_scelta"] == scelta
                  # anche il punto: cambiarlo (o passare casa<->punto)
                  # e' una richiesta diversa — la tariffa puo' cambiare
                  and (mio["punto_ritiro"] or "") == punto
                  and (mio["via_punto"] or 0) == via_punto
                  and (legame["id"] if legame else 0)
                  == int(d.get("offerta_id") or 0))
        viva = mio["creato"] >= int(time.time()) - RIPRESA_INVOICE_S
        if stessa and viva and mio["invoice"]:
            con.close()
            art = (mio["prezzo_sats"] - mio["spedizione_sats"]
                   - mio["protezione_sats"])
            return {"ordine_id": mio["id"], "invoice": mio["invoice"],
                    "payment_hash": mio["payment_hash"],
                    "prezzo_sats": mio["prezzo_sats"],
                    "articolo_sats": art,
                    "spedizione_sats": mio["spedizione_sats"],
                    "protezione_sats": mio["protezione_sats"],
                    "consegna": mio["consegna_scelta"],
                    "punto_ritiro": mio["punto_ritiro"],
                    "via_punto": mio["via_punto"] or 0,
                    "quantita": mio["quantita"],
                    "articolo_unitario_sats": art // (mio["quantita"] or 1),
                    "offerta_id": legame["id"] if legame else 0,
                    "ripresa": True}
        # Rinnovo: prima il controllo del pagamento — e l'await impone
        # di chiudere la connessione (niente transazioni in attesa)
        con.close()
        if mio["payment_hash"] and await invoice_pagata(mio["payment_hash"]):
            await _incassa_ordine(mio["id"])
            raise HTTPException(409, "Il tuo pagamento precedente è appena "
                                     "stato confermato: l'oggetto è già "
                                     "tuo, lo trovi nei tuoi Ordini")
        con = db()
        con.execute("UPDATE ordini SET stato='annullato', aggiornato=? "
                    "WHERE id=? AND stato='creato'",
                    (int(time.time()), mio["id"]))
        con.execute("UPDATE offerte SET ordine_id=0 WHERE ordine_id=?",
                    (mio["id"],))
        con.commit()   # committa subito: il patto del ricontrollo tiene

    # La prenotazione dello stock (lug 2026): i pezzi con una invoice
    # viva in mano ad altri non si rivendono — prima di questa guardia
    # due compratori potevano pagare ENTRAMBI lo stesso annuncio.
    # Questo e' il fail-fast di cortesia (niente invoice inutile);
    # quello che fa fede e' il ricontrollo dopo crea_invoice_escrow.
    disponibile = a["quantita"] - _riservati(con, a["id"])
    if richiesti > disponibile:
        con.close()
        if disponibile < 1:
            raise HTTPException(409, "Qualcun altro sta già pagando questo "
                                     "oggetto: se il suo pagamento non va "
                                     "in porto tornerà disponibile tra "
                                     "pochi minuti")
        raise HTTPException(400, f"Ne restano solo {disponibile}: scegli "
                                 f"una quantità più piccola")

    # L'acquisto alla cifra pattuita: con offerta_id nel body il prezzo
    # dell'articolo diventa quello dell'accordo. L'offerta deve essere
    # MIA, su QUESTO annuncio, accettata e ancora nei tempi.
    off = None
    if d.get("offerta_id"):
        off = con.execute(
            "SELECT * FROM offerte WHERE id=? AND compratore_id=? AND "
            "annuncio_id=? AND stato='accettata'",
            (d["offerta_id"], user["id"], a["id"])).fetchone()
        if not off:
            con.close()
            raise HTTPException(404, "Offerta non trovata o non più valida")
        adesso = int(time.time())
        if 0 < off["scadenza"] < adesso:
            con.execute("UPDATE offerte SET stato='scaduta', aggiornato=? "
                        "WHERE id=?", (adesso, off["id"]))
            con.commit()
            con.close()
            raise HTTPException(400, "Il tempo per pagare questa offerta "
                                     "è finito: l'offerta è scaduta")
        if off["ordine_id"]:
            # Una invoice viva c'e' gia'? Pagare quella VECCHIA
            # bloccherebbe un ordine che nessun gancio riconduce piu'
            # all'offerta: meglio un no adesso. (Se l'ordine pendente
            # era MIO su questo annuncio, la ripresa qui sopra l'ha
            # gia' ripresentato o rinnovato: qui non ci si arriva.)
            viva = con.execute(
                "SELECT id FROM ordini WHERE id=? AND stato='creato'",
                (off["ordine_id"],)).fetchone()
            if viva:
                con.close()
                raise HTTPException(400, "C'è già una invoice in corso "
                                         "per questa offerta: pagala, "
                                         "oppure annulla quell'ordine e "
                                         "riprova")

    # Per gli annunci in EUR i sats si decidono ADESSO, al cambio
    # corrente: la invoice vive 15 minuti, e quella e' la durata del
    # prezzo bloccato. Se scade, il prossimo tentativo riconverte.
    # Articolo e spedizione si convertono INSIEME, allo stesso cambio;
    # un annuncio tutto-sats non dipende mai dal cambio. La MATEMATICA
    # vive nelle pure del conto (_unitario_effettivo, _tariffa_
    # dichiarata, _sped_in_sats, _conto_ordine): compra, set e
    # preventivo devono dire la stessa cifra per costruzione. Qui
    # restano cambio, 503 e tetto — hanno await e HTTPException.
    adesso = int(time.time())
    t_eur = (_tariffa_dichiarata(a, via)[1]
             if scelta == "spedizione" else 0.0)
    cambio_ordine = 0.0
    # LA PROMESSA DEL VENDITORE SI LEGGE QUI, e la posizione e' il solo
    # riordino di questo cantiere: da quando la soglia e' in EURO e' il
    # suo valore a dire se serve il cambio, quindi deve arrivare PRIMA
    # del blocco qui sotto. E' una LETTURA e nessun DML — il vincolo
    # «niente DML fra le guardie e il ricontrollo» resta intatto, ed e'
    # la stessa ragione per cui era lecita dove stava prima.
    # LA GUARDIA E' LA SCELTA, NON LA CIFRA (ago 2026, bug trovato col
    # cantiere del supplemento). Qui c'era «if sped:», cioe' i soli
    # sats: su un listino in SATS con la tariffa ancorata all'EURO
    # (spedizione_sats=0, spedizione_eur=5.00) t_sats e' 0, quindi la
    # promessa non si leggeva NEMMENO e la spedizione si pagava —
    # mentre preventivo_ordine la legge senza quel gate e la pagina
    # scriveva «gratuita». Preventivo e invoice divergevano in
    # silenzio, sul mono; _compra_set non aveva il difetto perche' la
    # regola la legge sempre. Guardare la STRADA e non il suo prezzo
    # e' anche cio' che tiene la riga vera quando la tariffa e' 0.
    sog_gratis = 0
    if scelta == "spedizione":
        vg = con.execute("SELECT sped_gratis_soglia_eur FROM utenti "
                         "WHERE tg_id=?", (a["venditore_id"],)).fetchone()
        sog_gratis = _regola_sped_gratis(
            vg["sped_gratis_soglia_eur"] if vg else 0)
    # Spedizione ANCORATA all'euro su listino sats (tariffa in euro
    # piena): i sats si decidono ADESSO, col cambio corrente. Senza
    # cambio l'ordine con spedizione non puo' partire — 503 onesto,
    # SOLO per questa scelta: il ritiro resta sempre acquistabile e
    # l'articolo in sats non dipende mai dal cambio.
    if (scelta == "spedizione" and a["valuta"] != "eur"
            and (t_eur > 0 or a["spedizione_extra_eur"] > 0)):
        cambio_ordine = await cambio_btc_eur()
        if cambio_ordine <= 0:
            con.close()
            raise HTTPException(503, "La spedizione di questo annuncio ha "
                                     "il prezzo in euro e il cambio non è "
                                     "disponibile in questo momento: "
                                     "riprova tra poco")
    if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
        cambio_ordine = await cambio_btc_eur()
        if cambio_ordine <= 0:
            con.close()
            raise HTTPException(503, "Il cambio euro non è disponibile in "
                                     "questo momento: riprova tra qualche "
                                     "minuto")
    # Il cambio serve anche solo per SAPERE se la promessa scatta, su
    # un annuncio che di suo non ne avrebbe bisogno. In una variabile
    # SUA e non in cambio_ordine: quella colonna dichiara «0 = nessuna
    # conversione», e qui non si converte niente — ci si limita a
    # misurare. NIENTE 503: se il cambio non risponde la promessa non
    # scatta e l'ordine parte a prezzo pieno, che far fallire un
    # acquisto perche' non si riesce a regalare la spedizione sarebbe
    # curare un male causandone uno peggiore.
    cambio_misura = cambio_ordine
    if sog_gratis > 0 and cambio_misura <= 0:
        cambio_misura = await cambio_btc_eur()
    # Il conto lavora sull'UNITARIO (offerte e lampo parlano il prezzo
    # del singolo pezzo, come il listino) e moltiplica alla fine:
    # arrotondare PRIMA di moltiplicare rende esatta la divisione a
    # ritroso di chi legge l'ordine (unitario = articolo / quantita).
    unitario = _unitario_effettivo(a, off, adesso, cambio_ordine)
    if a["valuta"] == "eur" and a["prezzo_eur"] > 0:
        # Il tetto di rodaggio con +20% di tolleranza: la volatilita'
        # ordinaria passa, un crollo del cambio no — e il venditore
        # si ripara da solo ritoccando il prezzo (la modifica
        # riconvalida al cambio di oggi). Il tetto guarda l'UNITARIO:
        # e' un vincolo del listino, come alla pubblicazione — tre
        # pezzi regolari non devono dare 409.
        if TETTO_SATS_ANNUNCIO and unitario > TETTO_SATS_ANNUNCIO * 1.2:
            con.close()
            await notifica(a["venditore_id"],
                f"📈 Il cambio si è mosso troppo: il tuo annuncio "
                f"«{a['titolo'][:60]}» ({a['prezzo_eur']:.2f} EUR) supera "
                f"ora il tetto di {TETTO_SATS_ANNUNCIO} sats e gli acquisti "
                f"sono in pausa. Ritocca il prezzo per riaprirli.")
            raise HTTPException(409, "Il cambio è cambiato troppo da quando "
                                     "l'annuncio è stato pubblicato: il "
                                     "venditore deve ritoccare il prezzo")

    articolo = unitario * richiesti
    # La protezione acquisti: percentuale sul SOLO articolo, per
    # difetto (mai un sat piu' del promesso), anche sul ritiro in zona
    # (copre il deposito di garanzia, non il trasporto). Oggi la leva
    # e' a 0: il ramo esiste ma non scatta. Il compratore paga il
    # TOTALE nel deposito; al rilascio il venditore riceve
    # articolo+spedizione e la protezione resta alla piattaforma.
    # La spedizione la dice _sped_pacco, la stessa pura del set e del
    # preventivo: la tariffa UNA volta sola piu' il supplemento di ogni
    # pezzo oltre il primo — con la colonna vuota e' la tariffa e basta,
    # cioe' il conto di sempre. Qui `sats` non puo' essere None: il
    # blocco del cambio qui sopra nomina TUTTE le tariffe che possono
    # essere ancorate all'euro, e una prova in CI incrocia quell'elenco
    # con le colonne `spedizione*_eur` di annunci — chi ne aggiungera'
    # una quarta lo sentira' dalla CI invece che da un 500.
    sp = _sped_pacco([(a, richiesti)],
                     via if scelta == "spedizione" else "", cambio_ordine)
    sped = sp["sats"]
    # LA SPEDIZIONE GRATIS SOPRA SOGLIA, e qui c'e' anche sul MONO —
    # lo sconto carrello no, ed e' la forma a deciderlo, non il gusto:
    # azzerare una tariffa scrive spedizione_sats=0, cioe' uno stato
    # che _righe_ordine gia' sottrae, mentre uno sconto di testata
    # romperebbe la sua divisione a ritroso (vedi _sped_gratis).
    # La regola l'ha gia' letta il blocco del cambio qui sopra (e' lei
    # a dire se il cambio serviva); qui resta la sola decisione. Si
    # azzera DOPO aver contato la tariffa, lo stesso punto di
    # _strade_preventivo — preventivo e invoice devono dire la stessa
    # cifra per costruzione.
    misura_eur = _eur_interi(articolo, cambio_misura)
    sped_gratis_sats, supplemento = 0, sp["supplemento"]
    if sped and _sped_gratis(misura_eur, sog_gratis):
        # intera, supplemento compreso: e' quello che il venditore
        # promette quando dice «la spedizione la offro io»
        sped_gratis_sats, sped, supplemento = sped, 0, 0
    conto = _conto_ordine(articolo, sped, PROTEZIONE_PERCENTO,
                          COMMISSIONE_PERCENTO)
    prot, totale = conto["protezione"], conto["totale"]

    # La leva anti-frode del digitale (SPENTA di serie, come il tetto
    # di rodaggio): un compratore senza acquisti conclusi non compra
    # beni digitali sopra il tetto. Il caso del codice riscattato-e-
    # negato non si risolve, si rende antieconomico: la prima truffa
    # non puo' valere piu' del tetto. Vale sull'articolo TOTALE
    # (unitario x pezzi): il rischio e' la cifra, non il listino.
    if (scelta == "digitale" and TETTO_DIGITALE_NUOVI
            and articolo > TETTO_DIGITALE_NUOVI):
        storia = con.execute("SELECT acquisti_ok FROM utenti WHERE tg_id=?",
                             (user["id"],)).fetchone()
        if not storia or not storia["acquisti_ok"]:
            con.close()
            raise HTTPException(400,
                f"Per il tuo primo acquisto i beni digitali sopra "
                f"{TETTO_DIGITALE_NUOVI:,} sats non sono disponibili: "
                f"concludi prima un acquisto qualsiasi".replace(",", " "))

    inv = await crea_invoice_escrow(
        totale, f"Barattolo escrow #{a['id']}: {a['titolo'][:40]}")
    # Il ricontrollo che fa fede (patto mono-processo: da qui all'INSERT
    # nessun await, il blocco e' atomico). Durante l'attesa della
    # invoice un altro pagamento puo' aver preso l'ultimo pezzo, o il
    # venditore aver ritoccato lo stock: si rilegge TUTTO — stato,
    # quantita' e prenotazioni. Fallito = 409 e la invoice appena nata
    # muore da sola in 15 minuti. VINCOLO da preservare: niente DML su
    # questa connessione prima di questo punto (una transazione aperta
    # congelerebbe la lettura; oggi l'unico DML sopra — l'offerta
    # scaduta — committa e solleva subito).
    fresco = con.execute("SELECT stato, quantita FROM annunci WHERE id=?",
                         (a["id"],)).fetchone()
    if (not fresco or fresco["stato"] != "attivo"
            or richiesti > fresco["quantita"] - _riservati(con, a["id"])):
        con.close()
        raise HTTPException(409, "Qualcun altro ti ha preceduto su questo "
                                 "annuncio: riprova tra qualche minuto")
    con.execute(
        "INSERT INTO ordini(annuncio_id,compratore_id,venditore_id,prezzo_sats,"
        "stato,payment_hash,invoice,creato,aggiornato,cambio_ordine,"
        "consegna_scelta,punto_ritiro,via_punto,spedizione_sats,"
        "protezione_sats,quantita,sped_gratis_sats) "
        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (a["id"], user["id"], a["venditore_id"], totale,
         "creato", inv["payment_hash"], inv["payment_request"],
         int(time.time()), int(time.time()),
         cambio_ordine, scelta, punto, via_punto, sped, prot, richiesti,
         sped_gratis_sats))
    ordine_id = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    if off:
        # Il legame ordine-offerta nella STESSA transazione: nessuna
        # finestra in cui l'uno esiste senza l'altro.
        con.execute("UPDATE offerte SET ordine_id=?, aggiornato=? "
                    "WHERE id=?", (ordine_id, int(time.time()), off["id"]))
    con.commit()
    con.close()
    # prezzo_sats resta il TOTALE (i client di ieri leggono quello);
    # le quote scomposte sono in piu', per il conto in chiaro.
    return {"ordine_id": ordine_id, "invoice": inv["payment_request"],
            "payment_hash": inv["payment_hash"], "prezzo_sats": totale,
            "articolo_sats": articolo, "spedizione_sats": sped,
            # la parte per-pezzo e i pezzi: le due chiavi che tengono
            # viva nel paySheet la riga «spedizione per N pezzi» gia'
            # vista nella pagina d'acquisto (sparire li' si legge come
            # «il prezzo e' cambiato», un attimo prima di pagare)
            "supplemento_sats": supplemento, "pezzi": sp["pezzi"],
            # la tariffa risparmiata (0 = nessuna promessa scattata):
            # colonna TESTIMONE, e la chiave che la fa ritrovare
            "sped_gratis_sats": sped_gratis_sats,
            "protezione_sats": prot, "consegna": scelta,
            "punto_ritiro": punto, "via_punto": via_punto,
            "quantita": richiesti, "articolo_unitario_sats": unitario,
            "offerta_id": off["id"] if off else 0}


def crea_ordine_pagato(con, a, compratore_id: int, totale_sats: int,
                       payment_hash: str, consegna_scelta: str = "",
                       cambio: float = 0) -> int:
    """LA PRIMITIVA «ordine gia' pagato» (ago 2026, nata col cantiere
    aste): i sats sono GIA' in cassaforte — oggi un'asta aggiudicata,
    domani la pagina d'acquisto che incassa prima di creare — e
    l'ordine nasce direttamente 'locked', senza invoice da attendere.
    Scrive DENTRO la transazione del chiamante (nessun commit qui:
    l'atomicita' la decide chi invoca). Da qui in poi e' un ordine
    come tutti gli altri: spedizione, conferma, dispute, auto-sblocco,
    feedback — il ciclo di vita non si tocca. consegna_scelta puo'
    nascere vuota (il vincitore d'asta sceglie DENTRO l'ordine, dal
    varco): finche' e' vuota il venditore non spedisce e nessuna
    finestra di tutela parte."""
    adesso = int(time.time())
    con.execute(
        "INSERT INTO ordini(annuncio_id,compratore_id,venditore_id,"
        "prezzo_sats,stato,payment_hash,creato,aggiornato,cambio_ordine,"
        "consegna_scelta,spedizione_sats,protezione_sats,quantita) "
        "VALUES(?,?,?,?,'locked',?,?,?,?,?,0,0,1)",
        (a["id"], compratore_id, a["venditore_id"], totale_sats,
         payment_hash, adesso, adesso, cambio, consegna_scelta))
    return con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]


@app.post("/api/orders/{ordine_id}/verifica-pagamento")
async def verifica_pagamento(ordine_id: int, x_tg_init_data: str = Header(""),
                                             barattolo_sessione: str = Cookie("")):
    """La Mini App chiama questo endpoint dopo il pagamento:
    se la invoice risulta pagata, i sats sono in cassaforte -> LOCKED.
    Il lavoro vero sta in _incassa_ordine (estratto ago 2026): da qui
    ci passa il poll della Mini App, da controlla_annullati il saldo
    arrivato su un ordine annullato nella corsa.

    L'ORDINE E' MIO (ago 2026, audit): era l'unica rotta
    /api/orders/{id}/… che l'utente lo verificava e poi lo buttava
    via, leggendo l'ordine per solo id — mentre il gemello dei
    rilanci la guardia ce l'aveva, e il suo commento la nominava pure.
    Non si rubavano sats (senza la invoice pagata non parte niente),
    ma gli id sono progressivi: chiamando 1, 2, 3… si leggeva lo
    STATO di ogni ordine del mercatino, e si poteva innescare in
    anticipo il flusso di un altro — notifiche al suo venditore, ai
    moderatori, agli offerenti che decadono, e il «venduto» su Nostr
    e sul canale. Il 400 e' quello degli altri fratelli, ed e' anche
    quello che non distingue «non e' tuo» da «stato sbagliato»: chi
    enumera non impara niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT stato, payment_hash FROM ordini "
                    "WHERE id=? AND compratore_id=?",
                    (ordine_id, user["id"])).fetchone()
    con.close()
    if not o:
        raise HTTPException(400, "Operazione non permessa")
    if o["stato"] != "creato":
        return {"stato": o["stato"]}
    if not await invoice_pagata(o["payment_hash"]):
        return {"stato": "in_attesa"}
    return await _incassa_ordine(ordine_id)


async def _incassa_ordine(ordine_id: int) -> dict:
    """I sats sono in cassaforte: l'ordine passa a LOCKED, lo stock
    scala, le offerte si chiudono, le notifiche partono. Estratto da
    verifica_pagamento (ago 2026) perche' ora ci passa anche il
    riacciuffo dei pagamenti arrivati su un ordine annullato
    (controlla_annullati). NON ricontrolla la invoice: il chiamante
    l'ha appena fatto — e tra il CAS e il commit niente await.

    Passaggio ATOMICO: la Mini App chiama in polling e coi bottoni
    "ho pagato", quindi qui possono arrivare piu' chiamate insieme.
    Vince solo chi flippa DAVVERO la riga da 'creato' a 'locked':
    gli altri escono senza rinotificare il venditore."""
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
    if not o or o["stato"] != "creato":
        stato = o["stato"] if o else "annullato"
        con.close()
        return {"stato": stato}
    cur = con.execute(
        "UPDATE ordini SET stato='locked', aggiornato=? "
        "WHERE id=? AND stato='creato'",
        (int(time.time()), ordine_id))
    if cur.rowcount == 0:
        con.commit()
        con.close()
        return {"stato": "locked"}
    # Lo stock scala dei pezzi dell'ordine, RIGA per riga: il set
    # ha piu' annunci, il mono e' una riga sintetizzata — stessa
    # strada per entrambi. MAX para il corner raro dell'ordine
    # pagato ma verificato dopo i 30 minuti della prenotazione:
    # mai un numero negativo in vetrina.
    pezzi = o["quantita"] or 1
    righe = _righe_ordine(con, o)
    e_set = not o["annuncio_id"]
    a = None
    esauriti, taglie = [], []
    for r in righe:
        con.execute("UPDATE annunci SET quantita=MAX(quantita-?,0) "
                    "WHERE id=?", (r["quantita"], r["annuncio_id"]))
        a = con.execute("SELECT contatto_nostr, titolo, quantita, "
                        "taglia_pacco FROM annunci WHERE id=?",
                        (r["annuncio_id"],)).fetchone()
        taglie.append((a["taglia_pacco"] if a else "", r["quantita"]))
        # L'esaurimento: solo quando l'ULTIMO pezzo se ne va
        # l'annuncio diventa 'venduto' (l'invariante venduto <=>
        # quantita=0). Con pezzi ancora in vetrina niente sold,
        # niente ✅ sul canale e le trattative altrui restano VIVE:
        # c'e' ancora da comprare. Nel set si giudica riga per
        # riga: la vendita di un pezzo non spegne gli altri.
        if not a or a["quantita"] <= 0:
            con.execute("UPDATE annunci SET stato='venduto' WHERE id=?",
                        (r["annuncio_id"],))
            esauriti.append({"annuncio_id": r["annuncio_id"],
                             "titolo": a["titolo"] if a else r["titolo"],
                             "nostr": bool(a and a["contatto_nostr"])})
    # L'offerta che ha generato l'ordine si conclude col pagamento;
    # le ALTRE ancora vive decadono solo all'esaurimento del LORO
    # annuncio — l'annuncio non si e' mai bloccato, e ha vinto chi
    # ha pagato. (La UPDATE su ordine_id copre in un colpo anche
    # le offerte per-riga di un set.)
    adesso = int(time.time())
    con.execute("UPDATE offerte SET stato='conclusa', aggiornato=? "
                "WHERE ordine_id=? AND stato='accettata'",
                (adesso, ordine_id))
    decadute = []
    for e in esauriti:
        vive = con.execute(
            "SELECT id, compratore_id FROM offerte WHERE annuncio_id=? "
            "AND stato IN ('proposta','controproposta','accettata')",
            (e["annuncio_id"],)).fetchall()
        if vive:
            con.execute(
                "UPDATE offerte SET stato='decaduta', aggiornato=? "
                "WHERE annuncio_id=? AND stato IN "
                "('proposta','controproposta','accettata')",
                (adesso, e["annuncio_id"]))
            decadute += [{"compratore_id": v["compratore_id"],
                          "titolo": e["titolo"]} for v in vive]
    con.commit()
    for e in esauriti:
        # Anche la piazza Nostr deve sapere che l'oggetto e' andato
        asyncio.create_task(annuncio_su_nostr(e["annuncio_id"], "sold",
                                              solo_aggiornamento=True))
        # ...e il post nel canale si aggiorna col ✅ Venduto
        asyncio.create_task(promo_venduto(e["annuncio_id"]))
    if e_set:
        msg = (f"🔒 <b>Hai venduto un set di {len(righe)} oggetti"
               + (f" ({pezzi} pezzi)" if pezzi > len(righe) else "")
               + "!</b> I sats dell'acquirente sono bloccati nel "
               "deposito di garanzia. Prepara un pacco solo e segna "
               "l'ordine come spedito nella Mini App. 📦\n")
        for r in righe:
            msg += (f"\n• {r['titolo'][:40]}"
                    + (f" × {r['quantita']}" if r["quantita"] > 1
                       else ""))
        # La taglia stimata del pacco unico: un aiuto, non una
        # promessa — e' il venditore che prepara il pacco vero
        stima = (stima_taglia_set(taglie)
                 if o["consegna_scelta"] == "spedizione" else "")
        if stima:
            msg += (f"\n\n📦 Pacco stimato: <b>{stima}</b> — "
                    f"verifica tu prima di spedire.")
        promemoria = [e["titolo"][:40] for e in esauriti if e["nostr"]]
        if promemoria:
            msg += ("\n\n🟣 Su <b>Nostr</b> ricordati di segnare come "
                    "<b>venduto (sold)</b> dal tuo client: "
                    + ", ".join(f"«{t}»" for t in promemoria))
    else:
        esaurito = bool(esauriti)
        msg = ("🔒 <b>Hai venduto!</b> " if pezzi == 1 else
               f"🔒 <b>Hai venduto {pezzi} pezzi!</b> ")
        msg += ("I sats dell'acquirente sono bloccati nel deposito di "
                "garanzia. "
                "Spedisci l'oggetto e segna l'ordine come spedito nella Mini App. 📦")
        if not esaurito:
            msg += (f"\n\n🏷 L'annuncio resta in vetrina: "
                    f"{a['quantita']} ancora {'disponibile' if a['quantita'] == 1 else 'disponibili'}.")
        if esaurito and a and a["contatto_nostr"]:
            msg += ("\n\n🟣 Questo annuncio è pubblicato anche su <b>Nostr</b>: "
                    "ricordati di segnarlo come <b>venduto (sold)</b> dal tuo "
                    "client, così nessun altro proverà a comprarlo lì.")
    if o["punto_ritiro"]:
        # Coda STATICA, mai il testo del compratore dentro l'HTML
        # della notifica (parse_mode HTML: un «<» la spegnerebbe).
        # Il punto scritto si legge nell'ordine, dove passa da esc().
        msg += ("\n\n📦 Il compratore ha scelto la <b>spedizione a un "
                "punto di ritiro</b>: trovi il punto nell'ordine.")
    elif o["via_punto"]:
        # Il residuo del quarto giro: via scelta senza punto — solo
        # ordini nati da un client di ieri (il server tollera il
        # punto assente senza rete). Va detto SUBITO, e con la via
        # d'uscita: la chat, se serve accordarsi.
        msg += ("\n\n📦 Il compratore vuole la <b>spedizione a un punto "
                "di ritiro</b>: indicherà il punto nell'ordine — se "
                "serve, accordatevi in chat sul corriere.")
    await notifica(o["venditore_id"], msg)
    # Il polso dei moderatori: e' nato un ordine, sats in cassaforte
    await polso_ordini_admin(
        f"🛒 <b>Nuovo ordine:</b> «{_titolo_ordine(righe)[:60]}» — "
        f"{o['prezzo_sats']} sats. Ordini aperti: {{aperti}}")
    # Il garbo verso chi restava in trattativa: l'oggetto e' andato.
    # MAI al compratore che ha appena pagato: se aveva un'altra
    # offerta sua, decade in silenzio (dirgli «venduto a qualcun
    # altro» sarebbe falso).
    for riga in decadute:
        if riga["compratore_id"] == o["compratore_id"]:
            continue
        await notifica(riga["compratore_id"],
            f"🕊 «{riga['titolo'][:60]}» è appena stato venduto a "
            f"qualcun altro: la tua offerta decade. In vetrina ci "
            f"sono altre occasioni che aspettano!")
    con.close()
    return {"stato": "locked"}


@app.post("/api/orders/{ordine_id}/punto-ritiro")
async def indica_punto_ritiro(ordine_id: int, req: Request,
                              x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Il COMPRATORE corregge (o indica) il punto di ritiro dentro
    l'ordine. Dal QUARTO giro (ago 2026) e' la RETE DI SICUREZZA
    della scelta anticipata: il punto si sceglie in pagina prima di
    «Paga», qui si corregge finche' il venditore non spedisce — ed e'
    cio' che rende sostenibile sceglierlo senza conoscere la rete;
    per gli ordini nati senza punto (i client di ieri, che il server
    tollera) qui si scrive la prima volta. Solo il compratore, solo
    su 'locked' e solo sulla via punto: dopo la spedizione il pacco
    e' partito e il campo si chiude. Il VUOTO si rifiuta: un punto
    scritto si corregge, non si svuota mai — cosi' il gate di
    segna_spedito non puo' riscattare su un ordine gia' compilato.
    Il venditore riceve la notifica STATICA a ogni cambio — mai il
    testo del compratore nell'HTML, si legge nell'ordine sotto
    esc()."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    punto = " ".join(str(d.get("punto_ritiro") or "").split())[:120]
    if not punto:
        raise HTTPException(400, "Scrivi il punto di ritiro (nome o "
                                 "indirizzo del punto)")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato='locked'", (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if not o["via_punto"]:
        con.close()
        raise HTTPException(400, "Questo ordine non è una spedizione a "
                                 "un punto di ritiro")
    cambiato = (o["punto_ritiro"] or "") != punto
    con.execute("UPDATE ordini SET punto_ritiro=? WHERE id=?",
                (punto, ordine_id))
    con.commit()
    con.close()
    if cambiato:
        await notifica(o["venditore_id"],
                       "📦 <b>Il compratore ha indicato il punto di "
                       "ritiro</b>: lo trovi nell'ordine, ora puoi "
                       "spedire.")
    return {"ok": True, "punto_ritiro": punto}


# ------------------ LA BUSTA DI CONSEGNA (ago 2026) ------------------
# Per ritirare un pacco a un punto servono il NOME che il venditore ha
# messo come destinatario (di fantasia: il corriere esige un nome, noi
# non raccogliamo dati veri) e il CODICE di ritiro che il corriere gli
# manda quando il pacco arriva al punto. Prima viaggiavano in chat
# privata — e chi non ha username Telegram ne' npub non e'
# contattabile: l'ordine restava bloccato (successo davvero). La busta
# li porta DENTRO l'ordine, cifrati col trasporto dei contenuti
# digitali (_cifra_contenuto) ma MAI con la sua semantica: aprire la
# busta significa poter andare a ritirare, NON aver ricevuto — la
# lettura non e' una ricevuta, non tocca `consegnato` ne' lo stato, e
# i sats si muovono solo con la conferma del compratore, coi bottoni
# di sempre.

# Il segnale d'arrivo e' UNA costante perche' parte da due strade — il
# deposito a pacco gia' dichiarato in viaggio (il caso normale) e
# segna_spedito nel caso raro del codice immediato — e le due non
# devono divergere.
MSG_BUSTA_PRONTA = (
    "📦 <b>Il tuo pacco ti aspetta al punto di ritiro!</b> Nell'ordine "
    "trovi il <b>nome del destinatario</b> e il <b>codice</b> per "
    "ritirarlo. ⏳ La giacenza dura pochi giorni (di solito circa 3), "
    "poi il pacco torna indietro: ritiralo presto, e dopo il ritiro "
    "conferma nella Mini App per sbloccare i sats al venditore.")


@app.post("/api/orders/{ordine_id}/busta-ritiro")
async def deposita_busta_ritiro(ordine_id: int, req: Request,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """Il VENDITORE deposita le istruzioni di ritiro: il nome del
    destinatario (serve al compratore se glielo chiedono al banco, e
    a entrambi se il pacco torna indietro) e il codice di ritiro.
    NIENTE gate su segna_spedito (decisione di Andrea): il codice
    arriva quando il pacco e' GIA' al punto, e col gate il venditore
    non potrebbe dichiarare la spedizione per tutto il viaggio — al
    posto del gate ci sono lo stato «in attesa del codice» visibile
    nell'ordine e sollecita_buste_ferme nell'orologio. Deposito su
    'locked' (caso raro del codice immediato: spedizione da un punto),
    'shipped' (il caso normale) e 'dispute' (un PIN sbagliato si
    corregge SOLO da qui: il moderatore non puo', non legge la busta).
    busta_il resta il PRIMO deposito; le correzioni timbrano
    busta_corretta_il e contano in busta_correzioni — cosi' in disputa
    si vede che la busta e' cambiata e quando, mai cosa c'e' dentro.
    Qui non si tocca ne' lo stato ne' spedito_il ne' consegnato: la
    macchina dell'escrow non sa che la busta esiste. Dichiarato: il
    compratore puo' ancora cambiare punto su 'locked' dopo un deposito
    precoce (il venditore riceve gia' la notifica statica a ogni
    cambio, e il codice immediato e' suo: sa se combacia)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    nome = " ".join(str(d.get("nome") or "").split())
    codice = (d.get("codice") or "").strip()
    if not nome or not codice:
        raise HTTPException(400, "Servono entrambi: il nome del "
                                 "destinatario e il codice di ritiro")
    # 400 espliciti, MAI il troncamento silenzioso del punto_ritiro:
    # un PIN troncato e' un PIN rotto, e il nome deve combaciare con
    # quello scritto sull'etichetta.
    if len(nome) > 80:
        raise HTTPException(400, "Il nome del destinatario è troppo "
                                 "lungo (massimo 80 caratteri)")
    if len(codice) > 1000:
        raise HTTPException(400, "Il codice di ritiro è troppo lungo "
                                 "(massimo 1000 caratteri)")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND venditore_id=? "
                    "AND stato IN ('locked','shipped','dispute')",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if not o["via_punto"]:
        con.close()
        raise HTTPException(400, "Questo ordine non è una spedizione a "
                                 "un punto di ritiro")
    adesso = int(time.time())
    correzione = o["busta_il"] > 0
    con.execute("UPDATE ordini SET busta_nome=?, busta_codice=?, "
                "busta_il=?, busta_corretta_il=?, busta_correzioni=? "
                "WHERE id=?",
                (_cifra_contenuto(nome), _cifra_contenuto(codice),
                 o["busta_il"] or adesso,
                 adesso if correzione else o["busta_corretta_il"],
                 o["busta_correzioni"] + (1 if correzione else 0),
                 ordine_id))
    con.commit()
    con.close()
    # Il journal dice COSA (impronta, mai il testo: nel journal non
    # entrano segreti) e QUANDO — il pattern della consegna digitale.
    impronta = hashlib.sha256(codice.encode("utf-8")).hexdigest()[:16]
    print(f"📦 Ordine #{ordine_id}: busta di consegna "
          f"{'corretta' if correzione else 'depositata'} "
          f"(nome {len(nome)} caratteri, codice {len(codice)}, "
          f"impronta {impronta})")
    # La dedup del segnale d'arrivo: su 'locked' SILENZIO (parlera'
    # segna_spedito col suo ramo via_punto), sul primo deposito a
    # pacco gia' in viaggio parte il «ti aspetta», sulla correzione
    # l'avviso statico. Il segnale parte cosi' ESATTAMENTE una volta,
    # da una sola delle due strade. Testi statici, mai il contenuto.
    if o["stato"] != "locked":
        if correzione:
            await notifica(o["compratore_id"],
                           "📦 <b>Le istruzioni di ritiro sono state "
                           "aggiornate</b>: apri l'ordine e usa il "
                           "nome e il codice nuovi.")
        else:
            await notifica(o["compratore_id"], MSG_BUSTA_PRONTA)
    return {"ok": True, "busta_il": o["busta_il"] or adesso,
            "busta_correzioni": o["busta_correzioni"]
            + (1 if correzione else 0)}


@app.get("/api/orders/{ordine_id}/busta-ritiro")
async def leggi_busta_ritiro(ordine_id: int,
                             x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """La busta si legge SOLO da qui, mai da /api/orders — e SOLO le
    due parti: il moderatore MAI, da nessuna strada (a differenza del
    contenuto digitale; in disputa vede solo SE e QUANDO, dalla nota
    e da busta_il). GET PURO, ed e' la separazione dall'escrow:
    aprire la busta significa poter andare a ritirare, NON aver
    ricevuto — nessuna scrittura, `consegnato` e lo stato non si
    toccano, i sats restano in cassaforte finche' il compratore non
    conferma coi bottoni di sempre. L'autorizzazione sta PRIMA
    dell'esistenza: l'estraneo e l'ordine inesistente ricevono la
    stessa risposta (niente oracolo, la lezione di
    verifica-pagamento)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND "
                    "(compratore_id=? OR venditore_id=?)",
                    (ordine_id, user["id"], user["id"])).fetchone()
    con.close()
    if not o:
        raise HTTPException(400, "Operazione non permessa")
    if not o["busta_il"]:
        raise HTTPException(404, "Nessuna istruzione di ritiro su "
                                 "questo ordine")
    return {"ok": True,
            "nome": _decifra_contenuto(o["busta_nome"]),
            "codice": _decifra_contenuto(o["busta_codice"]),
            "depositata_il": o["busta_il"],
            "corretta_il": o["busta_corretta_il"],
            "correzioni": o["busta_correzioni"]}


@app.post("/api/orders/{ordine_id}/nascondi")
async def nascondi_ordine(ordine_id: int, req: Request,
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """Nasconde (o rimette in vista, body {"nascosto": 0}) un affare
    CONCLUSO dalla lista di chi lo chiede. NASCONDERE, mai cancellare:
    la riga resta nel database — libro mastro, feedback, export e
    registro di moderazione ci poggiano sopra. Il flag e' PER-PARTE
    (il compratore nasconde il suo, il venditore il suo, mai a
    vicenda) e solo su released/refunded, gli unici stati ASSORBENTI
    (risolvi_disputa li esclude, nessuna rotta li riapre): quindi «un
    nascosto che torna a muoversi» non esiste per costruzione. Il
    feedback della controparte puo' ancora arrivare, e l'ordine RESTA
    nascosto — un feedback non e' un movimento: lo si ritrova da
    «mostrali». NON `annullato`: e' una lapide che il reaper cancella
    o risuscita da solo. Rimettere in vista non ha guardie in piu'
    (riaprire non e' mai un problema, il patto delle ferie).
    L'autorizzazione sta PRIMA dell'esistenza: estraneo, inesistente
    e stato sbagliato ricevono la STESSA risposta (niente oracolo,
    la lezione di verifica-pagamento)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    valore = 1 if d.get("nascosto", 1) else 0
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND "
                    "(compratore_id=? OR venditore_id=?) AND "
                    "stato IN ('released','refunded')",
                    (ordine_id, user["id"], user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    colonna = ("nascosto_compratore" if user["id"] == o["compratore_id"]
               else "nascosto_venditore")
    # UNA colonna e basta, MAI `aggiornato`: nascondere non e' un
    # movimento dell'ordine — non riordina la lista di nessuno e non
    # sposta nessuna ancora. E nessuna notifica: e' un fatto privato
    # di una parte.
    con.execute(f"UPDATE ordini SET {colonna}=? WHERE id=?",
                (valore, ordine_id))
    con.commit()
    con.close()
    return {"ok": True, "nascosto": valore}


@app.post("/api/orders/{ordine_id}/spedito")
async def segna_spedito(ordine_id: int, req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Il venditore segna la spedizione, con corriere e numero di
    tracciamento (l'acquirente li vedrà). Da qui parte il timer di
    sblocco d'ufficio: se dopo GIORNI_AUTO_SBLOCCO nessuno segnala
    nulla, i sats vanno al venditore."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    corriere = (d.get("corriere") or "").strip()[:40]
    tracking = (d.get("tracking") or "").strip()[:60]
    # 'Ritiro in zona' e' il gemello di 'Consegna a mano' per gli
    # ordini col ritiro scelto dal compratore: niente pacco, niente
    # tracciamento — ma il timer di sblocco d'ufficio parte uguale.
    if corriere not in ("Consegna a mano", "Ritiro in zona") and not tracking:
        raise HTTPException(400, "Inserisci il numero di tracciamento "
                                 "(o scegli 'Consegna a mano')")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND venditore_id=? "
                    "AND stato='locked'", (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if o["consegna_scelta"] == "digitale":
        # Un ordine digitale non si «spedisce»: il timer partirebbe
        # senza che il compratore abbia ricevuto NULLA. La strada e'
        # una sola, la consegna del codice dentro Barattolo.
        con.close()
        raise HTTPException(400, "Questo ordine è a consegna digitale: "
                                 "consegna il contenuto dal pannello "
                                 "dedicato dell'ordine")
    if not o["consegna_scelta"]:
        # L'ordine nato da un'ASTA aspetta la scelta del vincitore:
        # niente spedizione e nessuna finestra di tutela prima della
        # scelta (decisione di Andrea). Gli ordini STORICI con
        # consegna '' restano il flusso di sempre: la differenza la
        # fa l'annuncio all'asta.
        a_asta = con.execute("SELECT asta_base_sats FROM annunci "
                             "WHERE id=?", (o["annuncio_id"],)).fetchone()
        if a_asta and a_asta["asta_base_sats"] > 0:
            con.close()
            raise HTTPException(400, "Il vincitore dell'asta sta "
                                     "scegliendo come riceverlo: "
                                     "attendi la sua scelta prima di "
                                     "spedire")
    if o["via_punto"] and not o["punto_ritiro"]:
        # Via punto senza punto indicato: DOVE spedirebbe? Dal quarto
        # giro il punto si sceglie in pagina e questo caso e' quasi
        # sparito (resta per gli ordini dei client di ieri, che il
        # server tollera) — la guardia RESTA, e una volta scritto il
        # punto non puo' riscattare: si CORREGGE ma non si svuota mai
        # (indica_punto_ritiro rifiuta il vuoto). Il compratore ha il
        # campo nell'ordine; se serve, la chat.
        con.close()
        raise HTTPException(400, "Il compratore non ha ancora indicato "
                                 "il punto di ritiro: appena lo scrive "
                                 "nell'ordine potrai segnare la "
                                 "spedizione (se serve, ricordaglielo "
                                 "in chat)")
    con.execute("UPDATE ordini SET stato='shipped', corriere=?, tracking=?, "
                "spedito_il=?, aggiornato=? WHERE id=?",
                (corriere, tracking, int(time.time()), int(time.time()),
                 ordine_id))
    con.commit()
    con.close()
    if corriere == "Ritiro in zona":
        await notifica(o["compratore_id"],
                       f"🤝 <b>Il venditore ha segnato la consegna a mano</b>. "
                       f"Se hai ritirato l'oggetto, confermalo nella Mini App "
                       f"per sbloccare i sats al venditore.")
        return {"ok": True}
    if o["via_punto"]:
        if o["busta_il"]:
            # Il caso raro dei due momenti coincidenti (codice
            # immediato, spedizione da un punto): la busta era gia'
            # depositata in silenzio su 'locked', e il segnale
            # d'arrivo parte da QUI — una volta sola, mai il doppione
            # «in viaggio» + «ti aspetta».
            await notifica(o["compratore_id"], MSG_BUSTA_PRONTA)
        else:
            # Il caso normale: il pacco parte, il codice arrivera'
            # al venditore quando il pacco e' al punto — e sara' il
            # deposito della busta a dire «ti aspetta».
            dettaglio = (f" con <b>{corriere}</b>, tracciamento "
                         f"<b>{tracking}</b>" if tracking else "")
            await notifica(o["compratore_id"],
                f"📦 <b>Il tuo oggetto è in viaggio verso il punto di "
                f"ritiro</b>{dettaglio}! Ti avviseremo quando il nome "
                f"e il codice per ritirarlo saranno nell'ordine.")
        return {"ok": True}
    dettaglio = (f"con <b>{corriere}</b>, tracciamento <b>{tracking}</b>"
                 if tracking else "in consegna a mano")
    await notifica(o["compratore_id"],
                   f"📦 <b>Il tuo oggetto è in viaggio</b> {dettaglio}! "
                   f"Quando arriva, conferma nella Mini App per sbloccare i "
                   f"sats al venditore.")
    return {"ok": True}


@app.post("/api/orders/{ordine_id}/consegnato")
async def segna_consegnato(ordine_id: int, x_tg_init_data: str = Header(""),
                                           barattolo_sessione: str = Cookie("")):
    """SOLO L'ACQUIRENTE segnala l'arrivo del pacco: si apre la sua
    finestra di ORE_CONFERMA ore per controllare l'oggetto.
    (Il venditore NON puo' usarlo: potrebbe far partire il timer
    prima della consegna reale. In futuro questo scatto arrivera' in
    automatico dal tracking del corriere.)
    ATTENZIONE, dal ago 2026: allo scadere della finestra NON c'e' piu'
    nessuno sblocco automatico — i sats restano nel deposito e parte il
    promemoria di sollecita_conferme_ferme, poi il moderatore. Vedi il
    disarmo dell'auto-sblocco in CLAUDE.md."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND stato='shipped' "
                    "AND compratore_id=?",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    con.execute("UPDATE ordini SET stato='delivered', consegnato=?, "
                "aggiornato=? WHERE id=?",
                (int(time.time()), int(time.time()), ordine_id))
    con.commit()
    con.close()
    await notifica(o["venditore_id"],
                   f"📬 L'acquirente ha segnalato la <b>consegna del pacco</b> "
                   f"e sta controllando l'oggetto: ha {ORE_CONFERMA} ore di "
                   f"tempo. I sats restano nel deposito di garanzia finché "
                   f"non conferma — se non si fa vivo gli mandiamo un "
                   f"promemoria, e poi interviene un moderatore.")
    return {"ok": True, "stato": "delivered"}


# ------------------- CONSEGNA DIGITALE (lug 2026) --------------------
# Il principio cardine: il codice passa DENTRO Barattolo, mai fuori.
# Il venditore lo consegna in un campo dedicato (locked -> shipped,
# corriere-sentinella 'Consegna digitale'); il compratore lo RIVELA
# con un tocco che fa da ricevuta di lettura (shipped -> delivered,
# consegnato = il momento della rivelazione). Il journal registra
# cosa e' stato consegnato (hash, mai il testo), quando, e quando e'
# stato visualizzato. Da li' partono le finestre corte del digitale
# (ORE_CONFERMA_DIGITALE / ORE_SILENZIO_DIGITALE nell'orologio).

@app.post("/api/orders/{ordine_id}/consegna-digitale")
async def consegna_digitale(ordine_id: int, req: Request,
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Il venditore consegna il contenuto (buono, codice, licenza):
    e' il gemello digitale di segna_spedito. Solo su ordini pagati
    (locked) con consegna digitale scelta."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    contenuto = (d.get("contenuto") or "").strip()
    if not contenuto:
        raise HTTPException(400, "Scrivi il contenuto da consegnare "
                                 "(codice, istruzioni, link di riscatto)")
    if len(contenuto) > 4000:
        raise HTTPException(400, "Il contenuto è troppo lungo "
                                 "(massimo 4000 caratteri)")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND venditore_id=? "
                    "AND stato='locked'", (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if o["consegna_scelta"] != "digitale":
        con.close()
        raise HTTPException(400, "Questo ordine non è a consegna digitale")
    adesso = int(time.time())
    con.execute("UPDATE ordini SET stato='shipped', "
                "corriere='Consegna digitale', tracking='', spedito_il=?, "
                "contenuto_digitale=?, aggiornato=? WHERE id=?",
                (adesso, _cifra_contenuto(contenuto), adesso, ordine_id))
    con.commit()
    con.close()
    # La traccia nel journal: COSA e' stato consegnato (impronta, mai
    # il testo: nel journal non entrano segreti) e quando. In disputa
    # e' la prova che il contenuto rivelato e' quello consegnato.
    impronta = hashlib.sha256(contenuto.encode("utf-8")).hexdigest()[:16]
    print(f"💾 Ordine #{ordine_id}: contenuto digitale consegnato "
          f"({len(contenuto)} caratteri, impronta {impronta})")
    await notifica(o["compratore_id"],
                   f"💾 <b>Il venditore ha consegnato il contenuto</b> del "
                   f"tuo acquisto digitale! Rivelalo nella Mini App e "
                   f"provalo subito: dalla rivelazione hai "
                   f"{ORE_CONFERMA_DIGITALE} ore per aprire una disputa "
                   f"se qualcosa non va, poi l'acquisto è definitivo. "
                   f"⚠️ Un codice, una volta rivelato, non torna indietro.")
    return {"ok": True, "stato": "shipped"}


@app.get("/api/orders/{ordine_id}/contenuto")
async def leggi_contenuto_digitale(ordine_id: int,
                                   x_tg_init_data: str = Header(""),
                                   barattolo_sessione: str = Cookie("")):
    """Il contenuto digitale si legge SOLO da qui, mai da /api/orders:
    per il compratore la PRIMA lettura e' la rivelazione — la ricevuta
    che apre la finestra di conferma (shipped -> delivered). Il
    venditore rilegge cio' che ha consegnato senza far scattare nulla;
    il moderatore legge negli stati di disputa."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?",
                    (ordine_id,)).fetchone()
    if not o or not o["contenuto_digitale"]:
        con.close()
        raise HTTPException(404, "Nessun contenuto digitale su questo ordine")
    admin_disputa = (e_admin(user["id"]) and o["stato"] in
                     ("dispute", "return_pending", "return_shipped", "refund"))
    if user["id"] not in (o["compratore_id"], o["venditore_id"]) \
            and not admin_disputa:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    rivelato = o["consegnato"]
    prima_volta = (user["id"] == o["compratore_id"]
                   and o["stato"] == "shipped")
    if prima_volta:
        # La rivelazione: da qui la finestra di ORE_CONFERMA_DIGITALE.
        # Le letture successive ri-servono il contenuto senza toccare
        # nulla (idempotente: un refresh non e' una seconda ricevuta).
        rivelato = int(time.time())
        con.execute("UPDATE ordini SET stato='delivered', consegnato=?, "
                    "aggiornato=? WHERE id=?",
                    (rivelato, rivelato, ordine_id))
        con.commit()
    con.close()
    if prima_volta:
        print(f"👁 Ordine #{ordine_id}: contenuto digitale rivelato "
              f"dal compratore")
        await notifica(o["venditore_id"],
                       f"👁 L'acquirente ha <b>rivelato il contenuto</b> "
                       f"del suo acquisto digitale: ha "
                       f"{ORE_CONFERMA_DIGITALE} ore per provarlo, poi i "
                       f"sats si sbloccano automaticamente.")
    return {"ok": True, "contenuto": _decifra_contenuto(o["contenuto_digitale"]),
            "rivelato": rivelato}


@app.post("/api/orders/{ordine_id}/sollecita")
async def sollecita_acquirente(ordine_id: int, x_tg_init_data: str = Header(""),
                                               barattolo_sessione: str = Cookie("")):
    """Il venditore invia un promemoria Telegram all'acquirente
    (massimo uno ogni 24 ore, per non trasformarlo in molestia)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND venditore_id=? "
                    "AND stato IN ('shipped','delivered')",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    if o["sollecito_il"] and o["sollecito_il"] > int(time.time()) - 86400:
        con.close()
        raise HTTPException(400, "Hai già inviato un promemoria nelle "
                                 "ultime 24 ore")
    con.execute("UPDATE ordini SET sollecito_il=? WHERE id=?",
                (int(time.time()), ordine_id))
    con.commit()
    con.close()
    await notifica(o["compratore_id"],
                   "🔔 <b>Promemoria dal venditore:</b> se il pacco è arrivato, "
                   "apri l'ordine nella Mini App e conferma la ricezione (o "
                   "segnala un problema). Grazie! 🙏")
    return {"ok": True}


def e_admin(tg_id: int) -> bool:
    """L'utente e' un moderatore? (nel collaudo: l'identita' 999)"""
    return tg_id in ADMIN_IDS or (MODALITA_COLLAUDO and tg_id == 999)


# ---------------------- API: PROFILO / INCASSI ----------------------

# ------------------- DOPPIONI SU NOSTR ------------------------------
# Il doppio cittadino puo' avere lo stesso oggetto due volte sui
# relay: l'annuncio importato (evento firmato da LUI) e quello nativo
# ripubblicato dalla piattaforma. Qui si RILEVANO le coppie sospette;
# il ritiro — sempre e solo della copia della piattaforma, mai
# dell'originale dell'utente — lo decide l'utente con un click
# esplicito, mai il codice da solo.

def _impronta_titolo(titolo: str) -> str:
    """Le parole del titolo normalizzato, in ordine alfabetico:
    'iPhone 13 Pro usato' e 'Usato iphone 13 pro' hanno la stessa
    impronta. Niente fuzzy: meglio pochi match certi che tanti dubbi."""
    return " ".join(sorted(normalizza(titolo).split()))


def _prezzi_compatibili(a, b) -> bool:
    """La conferma sul prezzo (il criterio primario e' il titolo).
    EUR contro EUR e' un confronto tra numeri stabili (scarto <=10%);
    sui sats si tollera di piu' (<=30%) perche' l'import riconverte
    il prezzo dell'importato al cambio di ogni ora mentre il nativo
    resta fissato al cambio di pubblicazione."""
    if a["prezzo_eur"] and b["prezzo_eur"]:
        x, y, tolleranza = a["prezzo_eur"], b["prezzo_eur"], 0.10
    else:
        x, y, tolleranza = a["prezzo_sats"], b["prezzo_sats"], 0.30
    return abs(x - y) <= max(x, y) * tolleranza


def trova_doppioni_nostr(con, tg_id: int) -> list:
    """Le coppie (importato, nativo) dello stesso venditore che
    sembrano lo stesso oggetto. Restano fuori le coppie archiviate
    con «non e' un doppione». Guardia d'ingresso: chi non ha annunci
    importati — la quasi totalita' degli utenti — esce subito."""
    campi = "id, titolo, prezzo_sats, valuta, prezzo_eur, foto"
    importati = con.execute(
        f"SELECT {campi} FROM annunci WHERE venditore_id=? "
        "AND stato='attivo' AND contatto_nostr!=''", (tg_id,)).fetchall()
    if not importati:
        return []
    nativi = con.execute(
        f"SELECT {campi} FROM annunci WHERE venditore_id=? "
        "AND stato='attivo' AND contatto_nostr='' AND nostr_event_id!=''",
        (tg_id,)).fetchall()
    if not nativi:
        return []
    ignorate = {(r["id_importato"], r["id_nativo"]) for r in con.execute(
        "SELECT id_importato, id_nativo FROM doppioni_ignorati")}

    def scheda(r):
        try:
            foto0 = (json.loads(r["foto"]) or [""])[0]
        except Exception:
            foto0 = ""
        return dict(id=r["id"], titolo=r["titolo"],
                    prezzo_sats=r["prezzo_sats"], valuta=r["valuta"],
                    prezzo_eur=r["prezzo_eur"], foto0=foto0)

    coppie = []
    for imp in importati:
        for nat in nativi:
            if ((imp["id"], nat["id"]) in ignorate
                    or _impronta_titolo(imp["titolo"])
                    != _impronta_titolo(nat["titolo"])
                    or not _prezzi_compatibili(imp, nat)):
                continue
            coppie.append({"importato": scheda(imp), "nativo": scheda(nat)})
    return coppie


# --------------- FACCIA E NOME DEL PROFILO (lug 2026) ---------------
# La foto accanto al nome, presa dal social di provenienza: la foto
# profilo Telegram per chi entra da Telegram, la picture del kind-0
# per chi entra con Nostr. E dal kind-0 viene anche il NOME di chi e'
# nato su Nostr: senza, resterebbe per sempre la npub abbreviata che
# gli mette addosso crea_utente_nostr — un venditore chiamato
# «npub1abcd…w3x9», che nessuno riconosce e nessuno cerca.
#
# MAI un link agli originali: gli URL delle
# foto via Bot API contengono il TOKEN del bot e scadono in un'ora,
# quelli Nostr sono host esterni arbitrari (e ogni visitatore della
# vetrina gli regalerebbe il suo IP). Quindi: si scarica, si riduce a
# un francobollo 128px e si serve la NOSTRA copia da foto/ col nome
# 'av_{negozio}_{ts}.jpg' — chiave = codice negozio pubblico (mai il
# tg_id, che non deve uscire), timestamp = versione anti-cache: la
# cache di 1 giorno su /foto lavora gratis come per le _min. Il
# francobollo e' seconda generazione ammessa dal patto della filiera,
# come le miniature. Fail-open totale: tutto gira in create_task e
# senza foto resta l'iniziale di sempre.
AVATAR_LATO = 128
AVATAR_QUALITA = 85
GIORNI_AVATAR = 7                    # rinfresco opportunistico
_AVATAR_IN_CORSO: set[int] = set()   # anti-valanga: un fetch per utente


def _salva_avatar(negozio: str, raw: bytes | None) -> str:
    """Il francobollo: quadrato ritagliato al centro come le _min
    (il CSS poi lo fa tondo). '' = niente foto."""
    if not ImmaginePillow or not raw or not negozio:
        return ""
    try:
        img = ImmaginePillow.open(io.BytesIO(raw))
        img = ImageOps.exif_transpose(img).convert("RGB")
        img = ImageOps.fit(img, (AVATAR_LATO, AVATAR_LATO),
                           ImmaginePillow.Resampling.LANCZOS)
        nome = f"av_{negozio}_{int(time.time())}.jpg"
        img.save(os.path.join(FOTO_DIR, nome), "JPEG",
                 quality=AVATAR_QUALITA)
        return nome
    except Exception:
        return ""


def _scrivi_avatar(tg_id: int, nome_nuovo: str):
    """Aggiorna la colonna e spazza il file vecchio (i nomi sono
    versionati: il vecchio non serve piu' a nessuno). Si scrive anche
    il '' — la foto rimossa dal social sparisce anche da noi — e
    avatar_aggiornato si segna comunque: niente ritentativi a raffica
    per chi una foto non ce l'ha proprio."""
    con = db()
    r = con.execute("SELECT avatar FROM utenti WHERE tg_id=?",
                    (tg_id,)).fetchone()
    vecchio = r["avatar"] if r else ""
    con.execute("UPDATE utenti SET avatar=?, avatar_aggiornato=? "
                "WHERE tg_id=?", (nome_nuovo, int(time.time()), tg_id))
    con.commit()
    con.close()
    if vecchio and vecchio != nome_nuovo:
        # Col francobollo vecchio se ne va anche la _min che gli avatar
        # non avrebbero mai dovuto avere (ago 2026): finche' la passata
        # d'avvio gliela faceva, ogni cambio di foto profilo ne lasciava
        # indietro una — nessuno la chiedeva e nessuno la cancellava.
        # E' il pattern delle foto degli annunci in modifica().
        for da_togliere in (vecchio, vecchio[:-4] + "_min.jpg"):
            try:
                os.remove(os.path.join(FOTO_DIR, da_togliere))
            except OSError:
                pass


async def _foto_profilo_telegram(tg_id: int) -> bytes | None:
    """La foto profilo che il bot vede (se l'utente la nasconde ai
    non-contatti, il bot non vede nulla: e' il suo modo di dire no).
    L'URL del file va scaricato subito e mai esposto: porta il token.
    In collaudo bot_api simula e qui esce None, come deve."""
    r = await bot_api("getUserProfilePhotos",
                      {"user_id": tg_id, "limit": 1})
    try:
        taglie = r["result"]["photos"][0]
        # le misure arrivano in ordine crescente: la prima che copre
        # il francobollo basta, e pesa meno
        t = next((t for t in taglie
                  if t.get("width", 0) >= AVATAR_LATO), taglie[-1])
        f = await bot_api("getFile", {"file_id": t["file_id"]})
        percorso = f["result"]["file_path"]
        async with httpx.AsyncClient(timeout=15) as c:
            resp = await c.get("https://api.telegram.org/file/"
                               f"bot{BOT_TOKEN}/{percorso}")
            resp.raise_for_status()
            return resp.content
    except Exception:
        return None    # niente foto, privacy o rete che manca: pari sono


def _kind0_profilo(relay: str, hexkey: str):
    """Chiede a UN relay il profilo kind-0 e ne restituisce il content
    gia' letto (name, display_name, picture...). Sincrona: va in
    asyncio.to_thread (pattern chiedi_relay_dm)."""
    try:
        ws = create_connection(relay, timeout=5,
                               sslopt={"cert_reqs": ssl.CERT_NONE})
        ws.send(json.dumps(["REQ", "av", {
            "kinds": [0], "authors": [hexkey], "limit": 1}]))
        profilo, inizio = None, time.time()
        while time.time() - inizio < 6:
            msg = json.loads(ws.recv())
            if msg[0] == "EVENT" and msg[1] == "av":
                letto = json.loads(msg[2].get("content") or "{}")
                if isinstance(letto, dict) and letto:
                    profilo = letto
            elif msg[0] == "EOSE":
                break
        ws.close()
        return profilo
    except Exception:
        return None


async def _profilo_nostr(npub: str) -> dict:
    """Il kind-0 dai 4 relay: si tiene il primo che risponde con
    qualcosa. Un giro solo per tutto — la faccia e il nome stanno
    nello stesso evento e non vale la pena chiederlo due volte."""
    if not create_connection:
        return {}
    try:
        hexkey = npub_to_hex(npub)
    except Exception:
        return {}
    risposte = await asyncio.gather(*[
        asyncio.to_thread(_kind0_profilo, r, hexkey)
        for r in RELAYS_VERIFICA])
    return next((p for p in risposte if p), None) or {}


async def _foto_profilo_nostr(profilo: dict) -> bytes | None:
    """La picture del kind-0, scaricata con le stesse guardie delle
    foto da URL dell'import (anti-SSRF + tetto 8MB): l'URL lo scrive
    l'utente nel suo profilo, non un fidato."""
    url = (profilo.get("picture") or "").strip()
    if not url or not url_foto_ammesso(url):
        return None
    return await asyncio.to_thread(scarica_foto_import, url)


MAX_NOME_NOSTR = 40      # sta accanto agli annunci: una riga, corta


def nome_da_profilo(profilo: dict) -> str:
    """Il nome leggibile del kind-0: display_name se c'e', altrimenti
    name. Arriva da un estraneo e finisce sotto i suoi annunci, quindi
    una riga sola e corta (l'esc() del frontend fa il resto).
    '' = il kind-0 non dice come si chiama."""
    for chiave in ("display_name", "displayName", "name"):
        v = profilo.get(chiave)
        if isinstance(v, str):
            v = " ".join(v.split())[:MAX_NOME_NOSTR].strip()
            if v:
                return v
    return ""


def _scrivi_nome_nostr(tg_id: int, nome: str):
    """Il nome di un NATIVO Nostr (tg_id negativo) viene dal suo
    kind-0: qui non c'e' altra anagrafica, e senza questa riga resta
    per sempre la npub abbreviata di crea_utente_nostr. Mai sui tg_id
    positivi: li' comanda Telegram (upsert_utente), che riscriverebbe
    comunque al primo accesso. Un kind-0 muto non cancella nulla: si
    tiene quello che c'e' gia'."""
    if tg_id > 0 or not nome:
        return
    con = db()
    con.execute("UPDATE utenti SET nome=? WHERE tg_id=? AND nome!=?",
                (nome, tg_id, nome))
    con.commit()
    con.close()


async def aggiorna_profilo_social(tg_id: int):
    """Rinfresca dal social di provenienza cio' che e' suo: il
    francobollo e — per chi e' nato da Nostr — il NOME.

    La foto segue avatar_scelta: '' = automatico, la catena dei doppi
    cittadini — prima la foto Telegram (l'anagrafica comanda: dopo la
    fusione nome e username vengono da li'), poi la picture Nostr, e
    senza nulla l'iniziale; 'telegram' | 'nostr' = solo quella gamba,
    senza ripiego (la scelta esplicita si rispetta: il social senza
    foto = iniziale); 'nessuna' = non si scarica proprio.

    Il nome invece NON e' una preferenza estetica: e' come si chiama
    quello che vende, e per un nativo Nostr esiste solo nel kind-0.
    Per questo si chiede anche con 'nessuna' — chi non vuole la faccia
    vuole comunque essere chiamato per nome.

    La gamba Nostr SOLO da chiave dal possesso dimostrato, la regola
    di notifica(): mai pescare la faccia (o il nome) di Caio perche'
    Tizio ne ha dichiarato la npub."""
    if tg_id in _AVATAR_IN_CORSO:
        return
    _AVATAR_IN_CORSO.add(tg_id)
    try:
        con = db()
        u = con.execute(
            "SELECT negozio, avatar, npub, npub_verificata, npub_accesso, "
            "avatar_scelta FROM utenti WHERE tg_id=?",
            (tg_id,)).fetchone()
        con.close()
        if not u or not u["negozio"]:
            return
        scelta = u["avatar_scelta"]
        npub = u["npub_accesso"] or \
            (u["npub"] if u["npub_verificata"] else "")
        # Un solo giro sui relay per il nome e per la faccia
        profilo = {}
        if npub and (tg_id < 0 or scelta in ("", "nostr")):
            profilo = await _profilo_nostr(npub)
        _scrivi_nome_nostr(tg_id, nome_da_profilo(profilo))
        if scelta == "nessuna":
            # niente da scaricare, ma il giro e' fatto: si timbra lo
            # stesso, o il kind-0 si richiederebbe a ogni battito
            _scrivi_avatar(tg_id, u["avatar"] or "")
            return
        raw = None
        if tg_id > 0 and scelta in ("", "telegram"):
            raw = await _foto_profilo_telegram(tg_id)
        if not raw and profilo and scelta in ("", "nostr"):
            raw = await _foto_profilo_nostr(profilo)
        _scrivi_avatar(tg_id, _salva_avatar(u["negozio"], raw))
    except Exception as e:
        print(f"⚠️ Profilo social non aggiornato ({tg_id}): {e}")
    finally:
        _AVATAR_IN_CORSO.discard(tg_id)


SECONDI_RINFRESCO_NOSTR = 3600      # ogni ora si guarda chi e' scaduto
MAX_RINFRESCHI_GIRO = 20            # ...e non piu' di venti per volta
_prossimo_rinfresco_nostr = 0.0


async def rinfresca_profili_nostr():
    """Il giro che va a prendere nome e faccia di chi non passa mai da
    /api/me. Serve perche' l'import aperto apre account da se': un
    venditore scoperto sui relay non ha mai aperto la Mini App, quindi
    il rinfresco opportunistico del profilo non scatta mai per lui —
    e i suoi annunci resterebbero firmati da una npub abbreviata.

    Non e' legato a IMPORT_NOSTR_APERTO: come si chiama un venditore e'
    questione di vetrina, non d'importazione, e vale anche per chi e'
    entrato da se' col login Nostr. Cadenza per utente GIORNI_AVATAR
    come per tutti (il timbro e' avatar_aggiornato), tetto per giro
    perche' ogni riga costa una domanda ai relay."""
    global _prossimo_rinfresco_nostr
    if time.time() < _prossimo_rinfresco_nostr:
        return
    _prossimo_rinfresco_nostr = time.time() + SECONDI_RINFRESCO_NOSTR
    con = db()
    righe = con.execute(
        "SELECT tg_id FROM utenti WHERE tg_id<0 AND negozio!='' "
        "AND avatar_aggiornato < ? ORDER BY avatar_aggiornato LIMIT ?",
        (int(time.time()) - GIORNI_AVATAR * 86400,
         MAX_RINFRESCHI_GIRO)).fetchall()
    con.close()
    for r in righe:
        # Uno alla volta: sono quattro relay a testa, non c'e' fretta
        await aggiorna_profilo_social(r["tg_id"])


@app.get("/api/me")
async def mio_profilo(x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    # async (era def) per il rinfresco dell'avatar in create_task:
    # il resto e' identico, sqlite qui e' questione di millisecondi
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    u = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    # Rinfresco opportunistico del francobollo (e del nome, per i
    # nativi Nostr): alla prima apertura e poi al piu' una volta a
    # settimana, in sottofondo (fail-open: questa risposta non lo
    # aspetta, la faccia compare al giro dopo). La scelta 'nessuna' la
    # rispetta aggiorna_profilo_social, che non scarica nulla.
    if u and (int(time.time()) - (u["avatar_aggiornato"] or 0)
              > GIORNI_AVATAR * 86400):
        asyncio.create_task(aggiorna_profilo_social(user["id"]))
    if u:
        # Passata silenziosa dei distintivi: cosi' Pioniere e compagni
        # compaiono al primo sguardo al Profilo, senza aspettare un
        # gancio. Scrittura su GET ma idempotente (INSERT OR IGNORE):
        # e' cio' che rende il sistema auto-riparante. Niente notifiche
        # qui: quelle spettano ai ganci dal vivo.
        controlla_distintivi(con, user["id"])
        # LA VISITA GIORNALIERA, timbrata qui perche' qui si passa
        # comunque a ogni apertura — e il precedente c'e' gia': su
        # questa GET si scrive da sempre (rinfresco avatar, passata
        # dei distintivi). Il giorno LOCALE in colonna serve solo a
        # non tentare la scrittura a ogni chiamata: a impedire il
        # doppio punto ci pensa la UNIQUE del registro, che e' il vero
        # giudice. NIENTE serie consecutiva, e non e' una svista: in
        # un mercatino non c'e' nulla da fare ogni giorno, e una
        # fiammella che si spegne punisce chi ha lavorato invece di
        # aprire l'app. Se un giorno si vorra' premiare la costanza,
        # si contano i giorni TOTALI, che salgono e basta.
        # La coorte al primo sguardo, per chi e' entrato dopo l'avvio
        # (il backfill di init_db copre solo chi c'era). Congelata.
        if not u["coorte"]:
            assegna_coorte(con, user["id"])
        # Il titolo dei fondatori si mette da solo anche qui, non solo
        # all'avvio: cosi' vale pure per un fondatore che apre l'app
        # la prima volta dopo che il suo id e' finito nel config.
        # Auto-riparante come la passata dei distintivi.
        if user["id"] in FONDATORI and not u["titolo"]:
            con.execute("UPDATE utenti SET titolo='t_fondatore' "
                        "WHERE tg_id=?", (user["id"],))
        giorno = oggi_locale()
        if (u["xp_ultimo_giorno"] or "") != giorno:
            assegna_xp(con, user["id"], "visita", AZIONI_XP["visita"],
                       f"giorno:{giorno}")
            con.execute("UPDATE utenti SET xp_ultimo_giorno=? WHERE tg_id=?",
                        (giorno, user["id"]))
        con.commit()
    presi = {r["badge_id"]: r["ottenuto_il"] for r in con.execute(
        "SELECT badge_id, ottenuto_il FROM badge_utente WHERE tg_id=?",
        (user["id"],))}
    # Doppioni su Nostr: coppie importato/nativo che sembrano lo
    # stesso oggetto (vedi trova_doppioni_nostr). Per quasi tutti
    # la guardia interna esce subito con la lista vuota.
    doppioni = trova_doppioni_nostr(con, user["id"])
    # Le offerte che aspettano una MIA mossa: da venditore una proposta
    # da valutare, da compratore una controproposta o un'accettata da
    # pagare. Un numero solo, per il pallino sulla scheda Ordini.
    da_agire = con.execute(
        "SELECT COUNT(*) AS n FROM offerte WHERE "
        "(venditore_id=? AND stato='proposta') OR "
        "(compratore_id=? AND stato IN ('controproposta','accettata'))",
        (user["id"], user["id"])).fetchone()["n"]
    # Il pallino dei moderatori: quanti annunci aspettano una
    # decisione (solo per gli admin, gli altri non lo vedono mai)
    da_moderare = 0
    if e_admin(user["id"]):
        da_moderare = con.execute(
            "SELECT COUNT(*) AS n FROM annunci "
            "WHERE stato='revisione'").fetchone()["n"]
    # I titoli sbloccati si chiedono con la connessione ancora aperta
    sbloccati = set(titoli_disponibili(con, user["id"])) if u else set()
    con.close()
    profilo = dict(u) if u else {}
    profilo["admin"] = e_admin(user["id"])
    profilo["in_revisione"] = da_moderare
    profilo["doppioni_nostr"] = doppioni
    profilo["offerte_da_agire"] = da_agire
    # Le leve dell'offerta lampo per il foglio di lancio (solo il
    # proprietario lo apre): il client non hardcoda mai le cifre.
    profilo["lampo_leve"] = {
        "attive": bool(LAMPO_ATTIVE), "sconti": LAMPO_SCONTI,
        "minimo": LAMPO_MIN_PERCENTO, "massimo": LAMPO_MAX_PERCENTO,
        "ore": ORE_LAMPO_OPZIONI}
    # Il pallino delle aste: dove sono stato SUPERATO (tocca a me:
    # rilancio o ritiro) piu' i rimborsi fermi in «Da riscuotere».
    # Chi e' in testa lo dice SOLO _leader_asta — un MAX sulla cifra
    # qui direbbe il contrario del giudice sul caso pari-cifra.
    con2 = db()
    superato = 0
    for pz in con2.execute(
            "SELECT p.id, p.annuncio_id FROM puntate p "
            "JOIN annunci a ON a.id=p.annuncio_id "
            "WHERE p.tg_id=? AND p.stato='attiva' AND p.versato_sats>0 "
            "AND a.stato='attivo' AND a.asta_scadenza>?",
            (user["id"], int(time.time()))).fetchall():
        testa = _leader_asta(con2, pz["annuncio_id"])
        if testa and testa["id"] != pz["id"]:
            superato += 1
    da_riscuotere = con2.execute(
        "SELECT COUNT(*) AS n FROM rimborsi_asta WHERE tg_id=? AND "
        "stato='da_riscuotere'", (user["id"],)).fetchone()["n"]
    con2.close()
    profilo["aste_da_agire"] = superato + da_riscuotere
    # Il tetto del barattolo, che dall'ago 2026 e' una leva: il client
    # non ne tiene una copia a memoria (divergerebbe al primo ritocco).
    profilo["max_barattolo"] = MAX_PREFERITI
    # Il catalogo degli spedizionieri per il cassetto «📦 Come
    # spedisci» (stesso patto: le voci non si hardcodano nel client).
    profilo["spedizionieri"] = list(SPEDIZIONIERI)
    # Il negozio in ferie, per il cassetto «🌴»: lo stato di adesso e
    # le sue leve — il client non hardcoda mai un tetto (il patto di
    # max_barattolo). `ferie_fino` esce gia' dal SELECT *, ma il
    # tetto e l'interruttore no.
    profilo["ferie_leve"] = {
        "attive": bool(FERIE_ATTIVE),
        "max_giorni": FERIE_MAX_GIORNI}
    # Lo sconto sul carrello, per il cassetto «🎁»: criteri, soglie e
    # percentuali proposte sono le PILLOLE del venditore (il patto di
    # LAMPO_SCONTI), i minimi e il tetto servono ai messaggi. I suoi
    # quattro valori escono gia' dal SELECT *.
    profilo["sconto_pacco_leve"] = {
        "attivo": bool(SCONTO_PACCO_ATTIVO),
        "criteri": list(SCONTO_PACCO_CRITERI),
        "soglie": list(SCONTO_PACCO_SOGLIE),
        "valori_eur": list(SCONTO_PACCO_VALORI_EUR),
        "sconti": list(SCONTO_PACCO_SCONTI),
        "min_soglia": SCONTO_PACCO_MIN_SOGLIA,
        "min_valore_eur": SCONTO_PACCO_MIN_VALORE_EUR,
        "max_percento": SCONTO_PACCO_MAX_PERCENTO}
    # E la spedizione gratis sopra soglia, per il cassetto «🚚»: le
    # soglie proposte sono le pillole del venditore, il minimo serve al
    # messaggio del 400. `sped_gratis_soglia_eur` esce gia' dal
    # SELECT *, e qui esce GREZZA di proposito — e' il suo negozio,
    # deve vedere cosa ha scritto; a spegnerla nelle vetrine ci pensa
    # il giudice, e il cassetto si nasconde da solo su `attivo`.
    profilo["sped_gratis_leve"] = {
        "attivo": bool(SPED_GRATIS_ATTIVO),
        "soglie_eur": list(SPED_GRATIS_SOGLIE_EUR),
        "min_eur": SPED_GRATIS_MIN_EUR}
    # I SUGGERIMENTI escono come STATO EFFETTIVO e non come valore
    # grezzo: `suggerimenti_annunci` esce dal SELECT * ed e' 0 anche
    # per chi non ha mai toccato niente — cioe' per chi li riceve. Un
    # client che leggesse quello direbbe «Attiva» a gente che li ha
    # gia' accesi, e chi tocca il bottone per accenderli li
    # SPEGNEREBBE. Il giudice e' uno solo, ed e' lo stesso che decide
    # se il messaggio parte davvero.
    profilo["suggerimenti_annunci"] = suggerimenti_accesi(
        u["suggerimenti_scelti"] if u else 0,
        u["suggerimenti_annunci"] if u else 0)
    profilo["suggerimenti_ogni_giorni"] = SUGGERIMENTI_OGNI_GIORNI
    # E quelle dell'asta, per il form di vendita e il foglio puntata
    # (stesso patto: mai cifre hardcodate nel client).
    profilo["asta_leve"] = {
        "abilitata": bool(ASTA_ABILITATA),
        "durate_giorni": ASTA_DURATE_GIORNI,
        "incremento_percento": ASTA_INCREMENTO_PERCENTO,
        "proroga_minuti": ASTA_PROROGA_MINUTI,
        "max_attive": ASTA_MAX_ATTIVE_VENDITORE,
        "proxy_attivo": bool(ASTA_PROXY_ATTIVO)}
    # Il catalogo COMPLETO, con la data per i guadagnati e null per gli
    # altri: il frontend non deve mai conoscere la lista a memoria.
    profilo["distintivi"] = [
        dict(id=d["id"], emoji=d["emoji"], nome=d["nome"],
             descrizione=d["descrizione"], fiducia=d["fiducia"],
             ottenuto=presi.get(d["id"]))
        for d in DISTINTIVI]
    # Il grado, coi numeri del gradino successivo: la progressione la
    # disegna il client, ma le soglie restano qui — sono catalogo, e
    # il client non hardcoda mai un catalogo.
    profilo["livello"] = livello_utente(
        u["xp"] if u else 0,
        ((u["vendite_ok"] or 0) + (u["acquisti_ok"] or 0)) if u else 0)
    # Stessa regola dei distintivi: catalogo COMPLETO col flag, cosi'
    # chi non ha ancora sbloccato un titolo vede comunque cosa c'e' e
    # cosa serve — che e' la molla.
    profilo["titoli"] = [
        dict(id=t["id"], nome=t["nome"], descrizione=t["descrizione"],
             sbloccato=t["id"] in sbloccati) for t in TITOLI]
    return profilo


@app.post("/api/me/doppioni/{annuncio_id}/ritira")
async def ritira_doppione(annuncio_id: int,
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """Ritira dai relay la copia del doppione firmata dalla
    PIATTAFORMA (mai l'originale dell'utente, che non si tocca).
    L'annuncio su Barattolo resta com'e': diventa solo-locale, e con
    nostr_event_id vuoto nessun gancio lo ripubblichera' piu'.
    Lo stato non conta: ritirare l'evento di un nativo nel frattempo
    venduto o rimosso e' innocuo e deduplica comunque."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _NOSTR:
        raise HTTPException(503, "La funzione Nostr non e' attiva sul server")
    con = db()
    a = con.execute(
        "SELECT venditore_id, contatto_nostr, nostr_event_id "
        "FROM annunci WHERE id=?", (annuncio_id,)).fetchone()
    con.close()
    if not a or a["venditore_id"] != user["id"]:
        raise HTTPException(404, "Annuncio non trovato")
    if a["contatto_nostr"]:
        raise HTTPException(400, "Questo e' l'annuncio importato: "
                                 "l'originale non si tocca mai")
    if not a["nostr_event_id"]:
        raise HTTPException(400, "Gia' sistemato: questo annuncio non "
                                 "e' piu' pubblicato su Nostr")
    # Qui si ASPETTA il risultato dei relay (niente create_task):
    # l'utente ha chiesto un'azione e merita una risposta onesta.
    ok = await ritira_da_nostr(annuncio_id, esigi_ok=True)
    if not ok:
        raise HTTPException(502, "I relay non rispondono: non e' "
                                 "cambiato nulla, riprova tra poco")
    return {"ok": True, "relay": ok}


@app.post("/api/me/doppioni/ignora")
async def ignora_doppione(req: Request, x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """«Non e' un doppione»: la coppia si archivia per sempre, su
    ogni dispositivo (per questo sta nel DB e non in localStorage)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    try:
        id_imp = int(d.get("id_importato") or 0)
        id_nat = int(d.get("id_nativo") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Coppia non valida")
    if id_imp <= 0 or id_nat <= 0 or id_imp == id_nat:
        raise HTTPException(400, "Coppia non valida")
    con = db()
    miei = {r["id"] for r in con.execute(
        "SELECT id FROM annunci WHERE venditore_id=? AND id IN (?,?)",
        (user["id"], id_imp, id_nat))}
    if miei != {id_imp, id_nat}:
        con.close()
        raise HTTPException(404, "Annuncio non trovato")
    con.execute("INSERT OR IGNORE INTO doppioni_ignorati"
                "(id_importato, id_nativo, tg_id, creato) VALUES(?,?,?,?)",
                (id_imp, id_nat, user["id"], int(time.time())))
    con.commit()
    con.close()
    return {"ok": True}


@app.post("/api/me/ln-address")
async def salva_ln_address(req: Request, x_tg_init_data: str = Header(""),
                                         barattolo_sessione: str = Cookie("")):
    """Il venditore imposta (una volta sola) il suo Lightning address:
    da quel momento tutti gli incassi sono AUTOMATICI. Prima di
    salvarlo lo verifichiamo dal vivo con una richiesta di prova.
    Se il venditore ha ordini gia' confermati in attesa, i sats
    partono immediatamente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    addr = (d.get("ln_address") or "").strip().lower()

    if addr:
        if "@" not in addr or "." not in addr.split("@")[-1]:
            raise HTTPException(400, "Formato non valido: dev'essere tipo nome@wallet.com")
        # Verifica dal vivo: il wallet risponde e accetta almeno 100 sats?
        if not await invoice_da_ln_address(addr, 100):
            # PERCHE' due messaggi (ago 2026): un indirizzo Phoenix e'
            # scritto benissimo, semplicemente parla un'altra lingua —
            # e dirgli «controlla di averlo scritto giusto» lo manda a
            # caccia di un refuso che non esiste. Il primo messaggio
            # spiega, il secondo resta quello di sempre; tutti e due
            # finiscono col CONSIGLIO, che e' l'unica cosa che serve
            # davvero a chi e' rimasto senza incassi.
            perche = diagnosi_ln_address(addr.split("@")[-1])
            if perche == "bip353":
                raise HTTPException(400,
                    "Questo è un indirizzo BIP-353 (è il tipo che usa "
                    "Phoenix): funziona via DNS, non via LNURL, e "
                    "Barattolo non lo sa ancora pagare. Non hai "
                    f"sbagliato a scriverlo. {CONSIGLIO_LNURL}")
            if perche == "inesistente":
                raise HTTPException(400,
                    f"Il dominio «{addr.split('@')[-1]}» non esiste: "
                    "quasi sempre è un carattere sbagliato. "
                    f"{CONSIGLIO_LNURL}")
            raise HTTPException(400,
                "Questo Lightning address non risponde: controlla di "
                f"averlo scritto giusto. {CONSIGLIO_LNURL}")

    con = db()
    con.execute("UPDATE utenti SET ln_address=? WHERE tg_id=?",
                (addr, user["id"]))
    # Ci sono incassi o rimborsi rimasti in sospeso? Ora possiamo sbloccarli.
    incassi = [r["id"] for r in con.execute(
        "SELECT id FROM ordini WHERE venditore_id=? AND stato='confirmed'",
        (user["id"],))] if addr else []
    rimborsi = [r["id"] for r in con.execute(
        "SELECT id FROM ordini WHERE compratore_id=? AND stato='refund'",
        (user["id"],))] if addr else []
    # ...e anche i rimborsi d'asta fermi in «Da riscuotere»: lo
    # scandaglio e' il recupero universale del denaro orfano, e il
    # registro delle aste viaggia sullo stesso binario.
    rimborsi_asta = [r["id"] for r in con.execute(
        "SELECT id FROM rimborsi_asta WHERE tg_id=? AND "
        "stato='da_riscuotere'", (user["id"],))] if addr else []
    con.commit()
    con.close()
    # Un indirizzo che INCASSA vale XP, una volta sola. Solo se c'e'
    # davvero: la stessa POST serve anche a cancellarlo, e togliere
    # non e' un traguardo. Chi lo toglie tiene i punti — il registro
    # e' append-only, e questo qui e' un fatto successo.
    if addr:
        await premia_xp(user["id"], "incassi", AZIONI_XP["incassi"],
                        "ln_address")
    sbloccati = 0
    for oid in incassi:
        r = await _sblocca_sats(oid)
        if r.get("ok"):
            sbloccati += 1
    for oid in rimborsi:
        r = await _rimborsa_compratore(oid)
        if r.get("ok"):
            sbloccati += 1
    for rid in rimborsi_asta:
        r = await _paga_rimborso(rid)
        if r.get("ok"):
            sbloccati += 1
    return {"ok": True, "ln_address": addr, "incassi_sbloccati": sbloccati}


# La npub e' "npub1" + 58 caratteri del charset bech32. Controllo di
# SOLO FORMATO: la npub resta AUTO-DICHIARATA e NON verificata (la
# proprieta' si dimostra con la nota pubblica qui sotto, oppure
# entrando col login Nostr, che firma una sfida).
RE_NPUB = re.compile(r"^npub1[023456789acdefghjklmnpqrstuvwxyz]{58}$")


@app.post("/api/me/npub")
async def salva_npub(req: Request, x_tg_init_data: str = Header(""),
                                   barattolo_sessione: str = Cookie("")):
    """Badge Nostr del profilo: l'utente dichiara la sua npub (chiave
    PUBBLICA) e i suoi annunci mostrano il badge. Stringa vuota = rimozione.
    REGOLA FERREA: mai chiedere ne' accettare nsec (chiavi private)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    npub = (d.get("npub") or "").strip().lower().removeprefix("nostr:")
    if npub.startswith("nsec"):
        raise HTTPException(400,
            "Quella e' una chiave PRIVATA (nsec): non incollarla MAI, qui "
            "o altrove! Serve la npub, la chiave pubblica (inizia con npub1)")
    if npub and not RE_NPUB.fullmatch(npub):
        raise HTTPException(400,
            "Formato non valido: la npub inizia con npub1 ed e' lunga 63 caratteri")
    con = db()
    attuale = con.execute(
        "SELECT npub, npub_verificata, npub_accesso FROM utenti WHERE tg_id=?",
        (user["id"],)).fetchone()
    # REGOLA nativo Nostr: se questa npub e' anche la SUA chiave
    # d'ingresso e non c'e' una chat Telegram (tg_id<0), rimuoverla
    # lo chiuderebbe fuori per sempre. Prima si collega Telegram.
    if not npub and attuale and user["id"] < 0 \
            and attuale["npub"] \
            and attuale["npub"] == attuale["npub_accesso"]:
        con.close()
        raise HTTPException(400,
            "Questa npub e' il tuo unico modo di entrare: collega prima "
            "Telegram dal blocco «Identita'», poi potrai rimuoverla")
    verificata = bool(attuale and attuale["npub_verificata"])
    accesso_revocato = False
    canale_azzerato = False
    if not attuale or npub != attuale["npub"]:
        # npub nuova, cambiata o rimossa: la verifica riparte da zero.
        # E se quel badge era anche la chiave d'accesso web, la revoca
        # del badge revoca pure l'accesso (la credenziale era nata DA
        # quel badge verificato). SOLO su account Telegram (tg_id>0):
        # a un nativo Nostr la chiave d'ingresso non si toglie mai,
        # resterebbe chiuso fuori per sempre.
        verificata = False
        accesso_revocato = bool(attuale and user["id"] > 0
                                and attuale["npub_accesso"]
                                and attuale["npub_accesso"] == attuale["npub"])
        con.execute(
            "UPDATE utenti SET npub=?, npub_verificata=0, "
            "verifica_codice='', verifica_scade=0, "
            "npub_accesso=CASE WHEN tg_id>0 AND npub_accesso=? "
            "THEN '' ELSE npub_accesso END WHERE tg_id=?",
            (npub, attuale["npub"] if attuale else "", user["id"]))
        # Se il canale avvisi scelto era Nostr ma la destinazione non
        # esiste piu' (niente chiave d'accesso ne' badge verificato),
        # si torna all'automatico: il cassetto Avvisi non deve mentire.
        cur = con.execute(
            "UPDATE utenti SET canale_notifiche='' WHERE tg_id=? "
            "AND canale_notifiche IN ('nostr','entrambi') "
            "AND npub_accesso='' AND (npub='' OR npub_verificata=0)",
            (user["id"],))
        canale_azzerato = cur.rowcount > 0
    con.commit()
    con.close()
    return {"ok": True, "npub": npub, "npub_verificata": verificata,
            "accesso_revocato": accesso_revocato,
            "canale_azzerato": canale_azzerato}


@app.post("/api/me/canale-notifiche")
async def scegli_canale_notifiche(req: Request,
                                  x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """L'utente sceglie dove ricevere gli avvisi: 'telegram', 'nostr'
    (DM cifrato NIP-17), 'entrambi', oppure '' = automatico (Telegram
    se c'e' la chat, DM Nostr per i nativi). Si accetta solo un canale
    che puo' davvero raggiungerlo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    canale = (d.get("canale") or "").strip().lower()
    if canale not in ("", "telegram", "nostr", "entrambi"):
        raise HTTPException(400, "Canale sconosciuto: telegram, nostr, "
                                 "entrambi o vuoto (automatico)")
    con = db()
    u = con.execute(
        "SELECT npub, npub_verificata, npub_accesso FROM utenti "
        "WHERE tg_id=?", (user["id"],)).fetchone()
    if not u:
        con.close()
        raise HTTPException(404, "Profilo non trovato")
    ha_nostr = bool(u["npub_accesso"] or
                    (u["npub"] and u["npub_verificata"]))
    if canale in ("nostr", "entrambi") and not ha_nostr:
        con.close()
        raise HTTPException(400,
            "Prima verifica la tua npub (o entra con Nostr): i DM si "
            "mandano solo a una chiave di cui hai dimostrato il possesso")
    if canale in ("telegram", "entrambi") and user["id"] < 0:
        con.close()
        raise HTTPException(400,
            "Questo account non ha una chat Telegram: collegala dal "
            "blocco «Le tue identita'»")
    con.execute("UPDATE utenti SET canale_notifiche=? WHERE tg_id=?",
                (canale, user["id"]))
    con.commit()
    con.close()
    return {"ok": True, "canale": canale}


@app.post("/api/me/spedizioniere")
async def scegli_spedizioniere(req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """«📦 Come spedisci»: con che rete di punti di ritiro lavora il
    negozio (catalogo SPEDIZIONIERI). '' = non dichiarato = la strada
    «punto di ritiro» resta spenta sui suoi annunci — si accende
    venditore per venditore, ed e' il pattern di canale-notifiche.
    Qui non c'e' una «realta'» da controllare: e' una dichiarazione
    di negozio, non una credenziale."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelta = (d.get("spedizioniere") or "").strip()
    if scelta not in ("",) + SPEDIZIONIERI:
        raise HTTPException(400, "Spedizioniere sconosciuto: "
                            + ", ".join(SPEDIZIONIERI)
                            + " o vuoto (non dichiarato)")
    con = db()
    con.execute("UPDATE utenti SET spedizioniere=? WHERE tg_id=?",
                (scelta, user["id"]))
    con.commit()
    con.close()
    return {"ok": True, "spedizioniere": scelta}


@app.post("/api/me/sconto-pacco")
async def imposta_sconto_pacco(req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """«🎁 Sconto sul carrello»: «da 3 articoli, −10%» — o «da 25 €,
    −10%» — su tutto il negozio. UNA regola sola, niente
    scaglioni: cambia il CRITERIO, non il numero di regole. E' il
    pattern di spedizioniere: una dichiarazione di negozio, non una
    credenziale.
    Body {criterio, soglia, valore_eur, percento}. `percento <= 0` e' lo
    SPEGNIMENTO e non ha NESSUNA guardia, criterio compreso (il patto
    del rientro dalle ferie: togliere una promessa non e' mai un
    problema, e chi spegne non deve saper compilare un campo).
    LE DUE SOGLIE SI CONSERVANO A VICENDA: la chiave assente non
    azzera, come per lo stock. Cosi' chi prova il criterio a valore e
    torna ai pezzi ritrova il suo 3, e un client vecchio — che di
    `valore` non sa niente — non cancella una soglia che non ha mai
    visto. Il COALESCE tiene tutto in UN solo UPDATE: una SELECT prima
    aprirebbe una finestra in cui la regola e' letta e non ancora
    scritta.
    NON c'e' un _impegni_aperti, e non e' una dimenticanza: le ferie lo
    hanno perche' chiudere il negozio toglie una via d'uscita a chi ha
    gia' pagato — qui non si toglie niente a nessuno. Gli ordini gia'
    nati portano il loro sconto FOTOGRAFATO in testata e la loro escrow
    e' gia' scontata; l'unica cosa «aperta» e' un carrello nella
    memoria di un client, che non sta nel database, non ha scadenza e
    non ha una controparte. Una guardia qui vorrebbe dire che un
    venditore non puo' spegnere una promessa sul SUO negozio perche'
    qualcuno, da qualche parte, sta guardando: un lucchetto senza fine.
    E nemmeno una guardia_ferie_venditore: lampo e asta ce l'hanno
    perche' sono atti di vendita, mentre sistemare il listino mentre si
    e' via e' esattamente cio' che si fa in ferie.
    Nessun avviso ai barattoli (il gemello della lampo): quella e' una
    notizia a tempo su un annuncio, questa e' una regola ferma — un
    ping a ogni ritocco sarebbe solo rumore."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not SCONTO_PACCO_ATTIVO:
        raise HTTPException(400, "Lo sconto sul carrello non è attivo")
    try:
        # None = «non me ne occupo», e la colonna resta com'era: e' il
        # patto dello stock, ed e' cio' che protegge la soglia
        # dell'altro criterio da un client che non la conosce
        soglia = None if d.get("soglia") is None else int(d["soglia"] or 0)
        # `valore_eur` e non `valore`: la chiave vecchia portava dei
        # SATS e si IGNORA per sempre. Scriverla in una colonna che ora
        # parla euro farebbe di «50.000» una soglia da cinquantamila
        # euro — cioe' una promessa che non scatta mai, in silenzio. Un
        # client rimasto in cache che salva a criterio valore prende
        # invece un 400 onesto, perche' la colonna nuova resta a zero.
        valore = (None if d.get("valore_eur") is None
                  else int(d["valore_eur"] or 0))
        percento = int(d.get("percento") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Numeri dello sconto non leggibili")
    criterio = str(d.get("criterio") or "").strip().lower()
    if percento <= 0:
        # lo spegnimento, senza guardie: le due soglie si azzerano
        # entrambe, o resterebbe una promessa a mezz'aria
        criterio, soglia, valore, percento = "pezzi", 0, 0, 0
    else:
        # criterio assente = 'pezzi': e' letteralmente il mondo di ieri,
        # ed e' il body di un client vecchio, che di pezzi parla per
        # forza. NON si eredita il criterio salvato — lo stesso body
        # significherebbe due cose secondo uno stato che non si vede.
        criterio = criterio or "pezzi"
        if criterio not in SCONTO_PACCO_CRITERI:
            raise HTTPException(400,
                "Il criterio dello sconto può essere «a pezzi» o "
                "«a valore».")
        if criterio == "pezzi" and (soglia or 0) < SCONTO_PACCO_MIN_SOGLIA:
            raise HTTPException(400,
                f"Lo sconto sul carrello parte da almeno "
                f"{SCONTO_PACCO_MIN_SOGLIA} articoli: sotto non è uno "
                f"sconto sul carrello, è un ribasso di listino — e quello "
                f"si fa sul prezzo.")
        if (criterio == "valore"
                and (valore or 0) < SCONTO_PACCO_MIN_VALORE_EUR):
            raise HTTPException(400,
                f"Lo sconto sul carrello a valore parte da almeno "
                f"{SCONTO_PACCO_MIN_VALORE_EUR} € di merce: sotto non è "
                f"uno sconto sul carrello, è un ribasso di listino — e "
                f"quello si fa sul prezzo.")
        if percento > SCONTO_PACCO_MAX_PERCENTO:
            raise HTTPException(400,
                f"Lo sconto sul carrello arriva al massimo al "
                f"{SCONTO_PACCO_MAX_PERCENTO}%.")
    con = db()
    con.execute("UPDATE utenti SET sconto_pacco_criterio=?, "
                "sconto_pacco_percento=?, "
                "sconto_pacco_soglia=COALESCE(?, sconto_pacco_soglia), "
                "sconto_pacco_valore_eur=COALESCE(?,sconto_pacco_valore_eur) "
                "WHERE tg_id=?",
                (criterio, percento, soglia, valore, user["id"]))
    con.commit()
    # si rilegge cio' che e' rimasto scritto: col COALESCE la risposta
    # non si puo' dedurre dal body, e il client deve poter riallineare
    # le sue pillole a colpo sicuro
    r = con.execute("SELECT sconto_pacco_soglia AS s, "
                    "sconto_pacco_valore_eur AS v FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    con.close()
    # `valore` esce a zero e il numero vero sta in `valore_eur`: e' la
    # regola d'oro di _sconto_pubblico applicata anche alla risposta
    return {"ok": True, "criterio": criterio, "percento": percento,
            "soglia": r["s"] if r else (soglia or 0),
            "valore": 0,
            "valore_eur": r["v"] if r else (valore or 0)}


@app.post("/api/me/spedizione-gratis")
async def imposta_sped_gratis(req: Request,
                              x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """«🚚 Spedizione gratis»: «da N € di articoli la spedizione la
    offro io», su tutto il negozio. E' la sorella dello sconto carrello
    — una dichiarazione di bottega, non una credenziale — ma molto piu'
    corta, perche' i numeri da decidere sono UNO: niente criterio (il
    criterio E' il valore) e niente percentuale (gratis e' gratis).
    Body {soglia_eur}. `soglia_eur <= 0` e' lo SPEGNIMENTO e non ha
    NESSUNA guardia (il patto del rientro dalle ferie: togliere una
    promessa non e' mai un problema).
    La chiave si chiama `soglia_eur` e la vecchia `soglia` si IGNORA:
    portava dei sats, e scriverla in una colonna che ora parla euro
    farebbe di «50.000» una soglia da cinquantamila euro, cioe' una
    promessa che non scatta mai — in silenzio. Un client rimasto in
    cache non salva piu' niente, che e' il verso giusto in cui
    rompersi.
    Niente _impegni_aperti e niente guardia_ferie_venditore, per le due
    ragioni scritte per esteso nello sconto: qui non si toglie niente a
    nessuno — gli ordini gia' nati hanno la loro escrow fissata e la
    tariffa risparmiata fotografata in colonna — e sistemare il listino
    mentre si e' via e' esattamente cio' che si fa in ferie.
    Nessun avviso ai barattoli (il gemello della lampo): e' una regola
    ferma, non una notizia a tempo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not SPED_GRATIS_ATTIVO:
        raise HTTPException(400, "La spedizione gratis sopra soglia non "
                                 "è attiva")
    try:
        soglia = int(d.get("soglia_eur") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Soglia non leggibile")
    if soglia < 0:
        soglia = 0
    if 0 < soglia < SPED_GRATIS_MIN_EUR:
        raise HTTPException(400,
            f"La spedizione gratis parte da almeno {SPED_GRATIS_MIN_EUR} € "
            f"di merce: sotto, la spedizione sarebbe gratis sempre — e "
            f"quella si dichiara nel prezzo dell'annuncio, che è già "
            f"previsto (costo 0).")
    con = db()
    con.execute("UPDATE utenti SET sped_gratis_soglia_eur=? WHERE tg_id=?",
                (soglia, user["id"]))
    con.commit()
    con.close()
    # `soglia` a zero e il numero vero in `soglia_eur`, come nel gemello
    return {"ok": True, "soglia": 0, "soglia_eur": soglia}


@app.post("/api/me/ferie")
async def imposta_ferie(req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """«🌴 Negozio in ferie»: il venditore che parte chiude la bottega
    con la data di rientro. Gli annunci RESTANO in vetrina, col prezzo
    in grigio e la data scritta sopra — si guarda, non si compra: e'
    tutta la differenza con la rimozione, e il motivo per cui non si
    tocca nemmeno una riga di `annunci`.
    Body {fino: <timestamp>}. `fino = 0` e' il RIENTRO, e non ha
    nessuna guardia: riaprire il negozio non e' mai un problema, e
    dall'istante dopo tutto e' comprabile — il gate e' in lettura,
    non c'e' nessun giro da aspettare.
    NON SI CHIUDE CON IMPEGNI APERTI: _impegni_aperti li elenca uno
    per uno con la sua via d'uscita, e il 400 li dice tutti insieme —
    un venditore non deve scoprirli a uno a uno riprovando.
    Le offerte PENDENTI ricevute decadono nella stessa transazione
    (decisione di Andrea): lasciarle vive sarebbe la trappola «il
    venditore accetta dalle ferie e il compratore non puo' pagare».
    Le notifiche 🕊 partono DOPO il commit, come sempre."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    if not FERIE_ATTIVE:
        raise HTTPException(400, "Le ferie del negozio non sono attive")
    try:
        fino = int(d.get("fino") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Data di rientro non valida")
    adesso = int(time.time())
    con = db()
    if fino:
        if fino <= adesso:
            con.close()
            raise HTTPException(400, "La data di rientro deve essere nel "
                                     "futuro: scegli il giorno in cui "
                                     "riapri.")
        if fino > adesso + FERIE_MAX_GIORNI * 86400:
            con.close()
            raise HTTPException(400,
                f"Le ferie durano al massimo {FERIE_MAX_GIORNI} giorni: "
                f"per una pausa piu' lunga conviene ritirare gli annunci.")
        impegni = _impegni_aperti(con, user["id"])
        if impegni:
            con.close()
            raise HTTPException(400,
                "Prima di chiudere devi sistemare questi impegni:\n• "
                + "\n• ".join(impegni)
                + "\nGli affari gia' spediti seguono il loro corso: quelli "
                  "non ti trattengono.")
    # Le offerte pendenti ricevute decadono: il venditore non sara' li'
    # a rispondere, e chi ha offerto deve poter cercare altrove subito.
    pendenti = []
    if fino:
        pendenti = [dict(r) for r in con.execute(
            "SELECT o.id, o.compratore_id, a.titolo FROM offerte o "
            "JOIN annunci a ON a.id = o.annuncio_id "
            "WHERE o.venditore_id=? AND o.stato IN "
            "('proposta','controproposta')", (user["id"],))]
        for o in pendenti:
            con.execute("UPDATE offerte SET stato='decaduta', aggiornato=? "
                        "WHERE id=?", (adesso, o["id"]))
    # ferie_avvisato torna a zero: il promemoria del rientro e' di
    # QUESTE ferie, non di quelle dell'anno scorso.
    con.execute("UPDATE utenti SET ferie_fino=?, ferie_avvisato=0 "
                "WHERE tg_id=?", (fino, user["id"]))
    con.commit()
    con.close()
    for o in pendenti:
        try:
            await notifica(o["compratore_id"],
                f"🕊 Il venditore di «{html.escape((o['titolo'] or '?')[:60])}» "
                f"è andato in ferie: la tua offerta decade. L'annuncio "
                f"resta in vetrina — riapre il {data_ferie(fino)}, e da "
                f"lì potrai riprovare.")
        except Exception as e:
            print(f"⚠️ Avviso decadenza per ferie saltato (#{o['id']}): {e}")
    return {"ok": True, "ferie_fino": fino}


@app.post("/api/me/suggerimenti")
async def scegli_suggerimenti(req: Request,
                              x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """«💡 Suggerimenti sui miei annunci»: l'utente autorizza (o
    revoca) i messaggi che segnalano cosa manca ai suoi annunci —
    consegna, condizioni, categoria, e il codice online per i buoni.

    Dall'ago 2026 sono ACCESI di serie (leva SUGGERIMENTI_DI_SERIE) e a
    tenerli gentili e' il RITMO, non l'opt-in: uno ogni N giorni per
    persona, qualunque sia la coda.
    QUI SI SCRIVONO DUE COSE, e la seconda e' il punto: il valore, e il
    fatto che a sceglierlo sia stato l'utente. Da questo momento la sua
    decisione batte il default per sempre — se un domani il default
    tornasse spento, chi l'ha acceso resta acceso, e viceversa. Senza
    `suggerimenti_scelti` un rovesciamento del default calpesterebbe
    ogni volta meta' delle persone (vedi suggerimenti_accesi).
    Non c'e' nulla da validare: e' un si' o un no. Nessun canale da
    controllare — se l'utente non e' raggiungibile il messaggio
    semplicemente non parte, come ogni altra notifica."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    attivi = 1 if d.get("attivi") else 0
    con = db()
    con.execute("UPDATE utenti SET suggerimenti_annunci=?, "
                "suggerimenti_scelti=1 WHERE tg_id=?",
                (attivi, user["id"]))
    con.commit()
    con.close()
    return {"ok": True, "attivi": bool(attivi)}


@app.post("/api/me/avviso-trasporto")
async def timbra_avviso_trasporto(x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """«L'ho visto»: il foglio sul rischio del trasporto e' stato
    aperto, e non si riapre mai piu' (vedi #trasportoSheet nel client).

    Niente body e niente da validare: e' un timbro, e l'unico valore
    possibile e' 1 — non esiste il verso opposto, perche' un avviso
    letto non si puo' slettere. Il client lo scrive quando il foglio SI
    APRE e non quando si chiude, il patto delle campagne: un errore di
    rete puo' perdere un avviso di cortesia, mai raddoppiarlo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("UPDATE utenti SET avvisato_trasporto=1 WHERE tg_id=?",
                (user["id"],))
    con.commit()
    con.close()
    return {"ok": True}


BIGLIETTI_FIRMA_NOSTR: dict[str, dict] = {}


@app.get("/api/me/firme-nostr")
async def firme_nostr_da_fare(x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Cosa aspetta la firma di questo utente. Per ogni annuncio in
    coda si prepara l'evento GIA' PRONTO ma NON firmato, col suo
    biglietto: il client firma (bunker, estensione o nsec in pagina —
    mai qui), pubblica sui relay e torna con {biglietto, pubkey, sig}.
    Se l'utente non ha piu' una chiave provata la coda si svuota da
    sola: senza chiave quelle firme non arriveranno mai."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    u = con.execute("SELECT npub, npub_verificata, npub_accesso "
                    "FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
    sua = chiave_nostr_provata(u)
    if not sua:
        con.execute("DELETE FROM firme_nostr WHERE tg_id=?", (user["id"],))
        con.commit()
        con.close()
        return {"firme": []}
    righe = con.execute(
        "SELECT f.annuncio_id, f.azione, a.* FROM firme_nostr f "
        "JOIN annunci a ON a.id=f.annuncio_id "
        "WHERE f.tg_id=? ORDER BY f.creato LIMIT 20",
        (user["id"],)).fetchall()
    con.close()

    adesso = time.time()
    for b in [b for b, v in BIGLIETTI_FIRMA_NOSTR.items()
              if v["scade"] < adesso]:
        BIGLIETTI_FIRMA_NOSTR.pop(b, None)
    while len(BIGLIETTI_FIRMA_NOSTR) >= 1000:
        BIGLIETTI_FIRMA_NOSTR.pop(next(iter(BIGLIETTI_FIRMA_NOSTR)))

    fuori = []
    for r in righe:
        a = dict(r)
        if a["azione"] == "ritira":
            if not a["nostr_event_id"]:
                continue     # non e' mai nato: non c'e' niente da ritirare
            tags = [["e", a["nostr_event_id"]],
                    ["a", f"30402:{sua}:barattolo-{a['id']}"],
                    ["k", "30402"]]
            evento = evento_non_firmato(sua, 5, tags,
                                        "Annuncio rimosso da Barattolo",
                                        int(time.time()))
        else:
            # 'pubblica' rilegge lo stato di ADESSO: fra l'accodamento
            # e la firma l'annuncio puo' essere stato venduto, e
            # nascere «attivo» sarebbe una bugia in piazza.
            stato = a["azione"] if a["azione"] in ("sold", "active") else (
                "sold" if a["stato"] == "venduto" else "active")
            # Si riusa evento_annuncio per non avere DUE posti che
            # costruiscono i tag NIP-99 di un annuncio (divergerebbero
            # al primo campo nuovo, ed e' anche cio' che la sentinella
            # del «punto» sorveglia). Firma con la chiave nostra e la
            # firma si butta: qui servono solo tags e content, che poi
            # l'utente firma con la SUA. Uno spreco dichiarato, in
            # cambio di un posto solo — e la coda si riempie solo dopo
            # il gate _NOSTR, quindi la chiave c'e' di sicuro.
            base = evento_annuncio(a, stato)
            evento = evento_non_firmato(sua, 30402, base["tags"],
                                        base["content"], base["created_at"])
        biglietto = secrets.token_urlsafe(32)
        BIGLIETTI_FIRMA_NOSTR[biglietto] = {
            "annuncio_id": a["id"], "tg_id": user["id"],
            "azione": a["azione"], "kind": evento["kind"],
            "tags": evento["tags"], "content": evento["content"],
            "created_at": evento["created_at"], "scade": adesso + 600}
        fuori.append({"biglietto": biglietto, "annuncio_id": a["id"],
                      "titolo": a["titolo"], "azione": a["azione"],
                      "evento": evento})
    return {"firme": fuori, "relays": _relays_import(),
            "collaudo": MODALITA_COLLAUDO}


@app.post("/api/me/firme-nostr")
async def firma_nostr_fatta(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Il client ha firmato e messo l'evento sui relay: qui si
    verifica la firma sull'evento RICOSTRUITO dal biglietto (una
    divergenza e' impossibile per costruzione) e si registra chi l'ha
    firmato. Da quel momento la piattaforma NON tocca piu' quell'evento
    — e' proprio il punto di tutto questo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    b = BIGLIETTI_FIRMA_NOSTR.pop(str(d.get("biglietto") or ""), None)
    if not b or b["scade"] < time.time() or b["tg_id"] != user["id"]:
        raise HTTPException(400, "La firma ha aspettato troppo: "
                                 "la richiesta tornerà da sola")
    pubkey = str(d.get("pubkey") or "").lower()
    sig = str(d.get("sig") or "").lower()
    if not RE_HEX_64.fullmatch(pubkey) or not RE_HEX_128.fullmatch(sig):
        raise HTTPException(400, "Firma malformata")
    if ChiavePubblicaNostr is None:
        raise HTTPException(503, "Firma Nostr non disponibile: sul server "
                                 "manca il pacchetto coincurve")
    con = db()
    u = con.execute("SELECT npub, npub_verificata, npub_accesso "
                    "FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
    # La chiave si rilegge FRESCA: fra il biglietto e adesso l'utente
    # puo' aver cambiato npub, e un evento firmato da una chiave che
    # non e' piu' sua non e' suo.
    if pubkey != chiave_nostr_provata(u):
        con.close()
        raise HTTPException(400, "La firma non è della tua chiave Nostr")
    ev = evento_non_firmato(pubkey, b["kind"], b["tags"], b["content"],
                            b["created_at"])
    try:
        buona = ChiavePubblicaNostr(bytes.fromhex(pubkey)).verify(
            bytes.fromhex(sig), bytes.fromhex(ev["id"]))
    except Exception:
        buona = False
    if not buona:
        con.close()
        raise HTTPException(400, "Firma non valida")
    if b["azione"] == "ritira":
        # Ritirato: la riga torna com'era prima di Nostr, e nessun
        # gancio la ripubblichera' piu' (sono tutti solo_aggiornamento)
        con.execute("UPDATE annunci SET nostr_event_id='', nostr_autore='' "
                    "WHERE id=?", (b["annuncio_id"],))
    else:
        con.execute("UPDATE annunci SET nostr_event_id=?, nostr_autore=? "
                    "WHERE id=?", (ev["id"], pubkey, b["annuncio_id"]))
    con.execute("DELETE FROM firme_nostr WHERE annuncio_id=?",
                (b["annuncio_id"],))
    con.commit()
    con.close()
    return {"ok": True, "evento": ev["id"]}


@app.post("/api/me/titolo")
async def scegli_titolo(req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Il titolo che si porta sotto il nome. Si accetta SOLO un titolo
    davvero sbloccato — il pattern di canale-notifiche e
    avatar-scelta: si accetta solo una sorgente che esiste — e il
    giudice e' titoli_disponibili, lo stesso che compila l'elenco nel
    Profilo, o si potrebbe indossare qualcosa che l'elenco non offre.
    Stringa vuota = nessun titolo, ed e' sempre lecita."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelto = (d.get("titolo") or "").strip()
    con = db()
    try:
        if scelto and scelto not in titoli_disponibili(con, user["id"]):
            raise HTTPException(400, "Questo titolo non l'hai ancora "
                                     "sbloccato")
        con.execute("UPDATE utenti SET titolo=? WHERE tg_id=?",
                    (scelto, user["id"]))
        con.commit()
    finally:
        con.close()
    return {"ok": True, "titolo": scelto}


@app.post("/api/me/avatar-scelta")
async def scegli_avatar(req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Il selettore «La tua foto» del cassetto Identita': da quale
    social prendere il francobollo — '' = automatico (la catena
    Telegram → Nostr → iniziale), 'telegram' | 'nostr' espliciti per
    chi ha entrambe le sorgenti, 'nessuna' = iniziale ovunque per il
    pubblico (reversibile: il file resta in dispensa e il CASE nelle
    SELECT lo tiene in casa). Si accetta solo una sorgente che esiste
    davvero — il pattern di canale-notifiche."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelta = (d.get("scelta") or "").strip().lower()
    if scelta not in ("", "telegram", "nostr", "nessuna"):
        raise HTTPException(400, "Scelta sconosciuta: telegram, nostr, "
                                 "nessuna o vuoto (automatico)")
    con = db()
    u = con.execute(
        "SELECT npub, npub_verificata, npub_accesso FROM utenti "
        "WHERE tg_id=?", (user["id"],)).fetchone()
    if not u:
        con.close()
        raise HTTPException(404, "Profilo non trovato")
    if scelta == "telegram" and user["id"] < 0:
        con.close()
        raise HTTPException(400,
            "Questo account non ha una chat Telegram: collegala dal "
            "blocco «Le tue identita'»")
    ha_nostr = bool(u["npub_accesso"] or
                    (u["npub"] and u["npub_verificata"]))
    if scelta == "nostr" and not ha_nostr:
        con.close()
        raise HTTPException(400,
            "Prima verifica la tua npub (o entra con Nostr): la foto si "
            "prende solo da una chiave di cui hai dimostrato il possesso")
    con.execute("UPDATE utenti SET avatar_scelta=? WHERE tg_id=?",
                (scelta, user["id"]))
    con.commit()
    con.close()
    # La sorgente e' cambiata: il francobollo in dispensa puo' venire
    # dall'altro social, si rifa' subito (con 'nessuna' non si scarica)
    if scelta != "nessuna":
        asyncio.create_task(aggiorna_profilo_social(user["id"]))
    return {"ok": True, "scelta": scelta}


# --- Avvisi di ricerca: «dimmi quando esce quello che cerco» ---------
# L'utente salva fino a 5 ricerche (categorie, comune+raggio, prezzo
# max, parole chiave) e il matching alla pubblicazione lo avvisa via
# notifica() multi-canale. Il motore vive accanto ai post automatici.

MAX_AVVISI_UTENTE = 5
RAGGI_AMMESSI = (10, 25, 50, 100)
def _avviso_pubblico(r) -> dict:
    """La riga del DB come la vede il frontend: categorie da
    '|A|B|' a lista, il resto com'e'."""
    return {"id": r["id"],
            "categorie": [c for c in r["categorie"].split("|") if c],
            "comune": r["comune"], "raggio_km": r["raggio_km"],
            "prezzo_max_sats": r["prezzo_max_sats"],
            "prezzo_max_eur": r["prezzo_max_eur"],
            "parole": r["parole"], "attivo": r["attivo"]}


@app.get("/api/comuni")
async def cerca_comuni(q: str = "",
                       x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """Suggerimenti per i campi comune (la Zona di Vendi e il comune
    degli avvisi di ricerca): primi 10 comuni per prefisso.
    Autenticato come tutto cio' che non e' vetrina. E' stata PUBBLICA
    per due giorni, per il filtro «Vicino a me» che viveva anche nella
    vetrina anonima: morto quello, e' tornata dov'era — non perche'
    aprirla facesse danno (e' l'elenco ISTAT committato in chiaro), ma
    perche' una superficie pubblica senza piu' un motivo e' solo
    superficie."""
    verifica_utente(x_tg_init_data, barattolo_sessione)
    prefisso = normalizza(q)
    if len(prefisso) < 2:
        return {"comuni": []}
    trovati = [c for c in COMUNI_LISTA
               if normalizza(c["nome"]).startswith(prefisso)][:10]
    return {"comuni": trovati}


@app.get("/api/zona-controlla")
async def zona_controlla(testo: str = "",
                         x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """La validazione MORBIDA della zona di Vendi (lug 2026): se nel
    testo libero c'e' un comune riconoscibile (anche «provincia di
    Pavia»: gli n-grammi lo pescano) va tutto bene; se non c'e' NULLA
    ma un quasi-comune si' («Pvia» -> Pavia), il client mostra
    «intendevi...?». Mai bloccante: e' solo un consiglio. Dataset
    assente = sempre riconosciuto (la funzione si spegne in silenzio,
    come tutta la geografia)."""
    verifica_utente(x_tg_init_data, barattolo_sessione)
    testo = (testo or "").strip()[:120]
    if not testo or not COMUNI:
        return {"riconosciuto": True, "suggerimento": ""}
    lat, lon = coordinate_da_zona(testo)
    if lat or lon:
        return {"riconosciuto": True, "suggerimento": ""}
    return {"riconosciuto": False, "suggerimento": suggerisci_comune(testo)}


@app.get("/api/me/avvisi-ricerca")
async def lista_avvisi_ricerca(x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
